// SECURE VERSION - See SECURITY REVIEW below for details

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const validator = require('validator');
const cors = require('cors');

const app = express();

// SECURITY: Apply helmet middleware for security headers
app.use(helmet());

// SECURITY: Enable CORS with restrictive settings
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// SECURITY: Apply rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use(limiter);

// SECURITY: Parse JSON with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// SECURITY: Health check endpoint (no data exposure)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// SECURITY: Users endpoint with input validation and authentication
// In production, this should check authentication tokens
app.get('/users', authenticateToken, (req, res) => {
  // SECURITY: Input validation for query parameters
  const limit = req.query.limit ? Math.min(parseInt(req.query.limit), 100) : 10;
  const offset = req.query.offset ? parseInt(req.query.offset) : 0;

  if (isNaN(limit) || isNaN(offset) || limit < 1 || offset < 0) {
    return res.status(400).json({ error: 'Invalid pagination parameters' });
  }

  // Mock user data - in production, fetch from database with parameterized queries
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const paginatedUsers = users.slice(offset, offset + limit);
  res.json({ data: paginatedUsers, total: users.length });
});

// SECURITY: Authentication middleware
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Missing authentication token' });
  }

  // TODO: Validate JWT token properly in production
  // const verified = verifyJWT(token);
  // if (!verified) return res.status(403).json({ error: 'Invalid token' });

  next();
}

// SECURITY: Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);
  // Don't expose internal error details to client
  res.status(500).json({ error: 'Internal server error' });
});

// SECURITY: 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

# COMPREHENSIVE SECURITY REVIEW - app.js

## Executive Summary
The current app.js contains multiple critical and high-severity security vulnerabilities. This review identifies OWASP Top 10 issues and provides specific remediation guidance.

---

## CRITICAL FINDINGS

### 1. ❌ MISSING AUTHENTICATION & AUTHORIZATION
**Severity: CRITICAL**
**OWASP: A01:2021 - Broken Access Control**

**Issue:** 
The `/users` endpoint exposes sensitive user data without any authentication mechanism.

```javascript
// VULNERABLE - No authentication
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Risks:**
- Any unauthenticated user can access all user information
- PII (email addresses) is publicly exposed
- Potential GDPR/privacy law violations
- Directory enumeration attacks possible

**Remediation:**
```javascript
// Use JWT authentication middleware
const jwt = require('jsonwebtoken');

function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Missing authentication token' });
  }

  jwt.verify(token, process.env.ACCESS_TOKEN_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user;
    next();
  });
}

app.get('/users', authenticateToken, (req, res) => {
  // Protected endpoint
  res.json(users);
});
```

---

### 2. ❌ MISSING INPUT VALIDATION
**Severity: HIGH**
**OWASP: A03:2021 - Injection**

**Issue:**
No validation on query parameters. If this endpoint accepted parameters, SQL injection or other injection attacks would be possible.

```javascript
// Vulnerable example - if this existed:
app.get('/users/:id', (req, res) => {
  const id = req.params.id; // No validation!
  // Direct DB query would be vulnerable to SQL injection
  const user = db.query(`SELECT * FROM users WHERE id = ${id}`);
});
```

**Remediation:**
```javascript
const validator = require('validator');

app.get('/users/:id', authenticateToken, (req, res) => {
  // Validate ID is a number
  if (!validator.isInt(req.params.id)) {
    return res.status(400).json({ error: 'Invalid user ID' });
  }

  const userId = parseInt(req.params.id, 10);

  // Use parameterized queries (never string concatenation)
  const user = db.query('SELECT * FROM users WHERE id = ?', [userId]);
  res.json(user);
});
```

---

### 3. ❌ NO SECURITY HEADERS
**Severity: HIGH**
**OWASP: A05:2021 - Security Misconfiguration**

**Issue:**
Missing critical HTTP security headers that provide defense-in-depth protection.

**Vulnerable Code:**
```javascript
// No security headers configured
const app = express();
app.get('/health', (req, res) => { ... });
```

**Attacks Enabled:**
- Clickjacking attacks (X-Frame-Options missing)
- XSS attacks (X-Content-Type-Options missing)
- MIME type confusion
- Insecure third-party content loading

**Remediation:**
```javascript
const helmet = require('helmet');

// Install: npm install helmet
app.use(helmet());

// This enables:
// - X-Frame-Options: DENY (prevents clickjacking)
// - X-Content-Type-Options: nosniff (prevents MIME sniffing)
// - X-XSS-Protection: 1; mode=block
// - Strict-Transport-Security (HTTPS enforcement)
// - Content-Security-Policy
```

---

### 4. ❌ NO RATE LIMITING
**Severity: HIGH**
**OWASP: A04:2021 - Insecure Design**

**Issue:**
Endpoints are vulnerable to brute force, DoS, and enumeration attacks.

**Remediation:**
```javascript
const rateLimit = require('express-rate-limit');

// General rate limiter
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,     // Return rate limit info in headers
  legacyHeaders: false       // Disable X-RateLimit-* headers
});

app.use(limiter); // Apply to all routes

// Stricter limit for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 attempts per 15 minutes
  skipSuccessfulRequests: true
});

app.post('/login', authLimiter, (req, res) => { ... });
```

---

### 5. ❌ NO REQUEST SIZE LIMITS
**Severity: MEDIUM**
**OWASP: A04:2021 - Insecure Design**

**Issue:**
Application doesn't limit request payload size, vulnerable to memory exhaustion attacks.

**Remediation:**
```javascript
// Limit payload sizes
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// This prevents:
// - Memory exhaustion attacks
// - Buffer overflow attempts
// - Uncontrolled data processing
```

---

### 6. ❌ MISSING CORS CONFIGURATION
**Severity: MEDIUM**
**OWASP: A05:2021 - Security Misconfiguration**

**Issue:**
CORS is not configured, allowing requests from any origin.

**Vulnerable:**
```javascript
// Implicitly allows all origins
app.get('/users', (req, res) => { ... });
```

**Remediation:**
```javascript
const cors = require('cors');

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Or specific route protection:
app.get('/users', cors({ origin: 'https://trusted-domain.com' }), (req, res) => {
  res.json(users);
});
```

---

### 7. ❌ INFORMATION DISCLOSURE VIA ERRORS
**Severity: MEDIUM**
**OWASP: A05:2021 - Security Misconfiguration**

**Issue:**
No error handling middleware - stack traces exposed to clients.

**Remediation:**
```javascript
// Global error handler (register last)
app.use((err, req, res, next) => {
  console.error('Error:', err); // Log for debugging

  // Never expose internal error details to client
  res.status(err.status || 500).json({
    error: 'Internal server error',
    // message: err.message // DON'T include this in production
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});
```

---

### 8. ❌ NO LOGGING & MONITORING
**Severity: MEDIUM**
**OWASP: A09:2021 - Logging and Monitoring Failures**

**Issue:**
No security event logging, making intrusion detection impossible.

**Remediation:**
```javascript
const morgan = require('morgan');
const winston = require('winston');

// HTTP request logging
app.use(morgan('combined'));

// Security event logger
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'security.log' }),
    new winston.transports.Console()
  ]
});

// Log security events
function logSecurityEvent(event, severity, details) {
  logger.log({
    level: severity,
    event,
    timestamp: new Date().toISOString(),
    ...details
  });
}

// Example usage
app.get('/users', authenticateToken, (req, res) => {
  logSecurityEvent('users_accessed', 'info', {
    userId: req.user.id,
    ip: req.ip
  });
  res.json(users);
});
```

---

### 9. ❌ NO HTTPS ENFORCEMENT
**Severity: HIGH**
**OWASP: A02:2021 - Cryptographic Failures**

**Issue:**
No enforced HTTPS in production.

**Remediation:**
```javascript
// Enforce HTTPS in production
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(`https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  });
}

// Or use helmet which sets HSTS header:
app.use(helmet.hsts({
  maxAge: 31536000, // 1 year in seconds
  includeSubDomains: true,
  preload: true
}));
```

---

### 10. ❌ HARDCODED CONFIGURATION
**Severity: MEDIUM**
**OWASP: A05:2021 - Security Misconfiguration**

**Issue:**
Port is hardcoded, no environment variable support.

**Remediation:**
```javascript
// Use environment variables
const PORT = process.env.PORT || 3000;
const ENV = process.env.NODE_ENV || 'development';

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${ENV} mode`);
});

// .env file
// PORT=3000
// NODE_ENV=production
// ALLOWED_ORIGINS=https://example.com,https://app.example.com
// ACCESS_TOKEN_SECRET=your-secret-here
```

