#### ❌ VULNERABLE (BEFORE)
```javascript
const express = require('express');
const app = express();

// No security headers!
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});
```
**Problem:** Exposed to clickjacking, XSS, MIME sniffing

#### ✅ SECURE (AFTER)
```javascript
const helmet = require('helmet');

app.use(helmet()); // Adds all security headers

// Returns with security headers:
// X-Frame-Options: DENY
// X-Content-Type-Options: nosniff
// X-XSS-Protection: 1; mode=block
// Strict-Transport-Security: max-age=...
// Content-Security-Policy: ...
```
**Benefit:** Defense against multiple attack vectors

---

### 3. INPUT VALIDATION

#### ❌ VULNERABLE (BEFORE)
```javascript
// If endpoint accepted parameters:
app.get('/users/:id', (req, res) => {
  // No validation!
  const id = req.params.id;
  // Vulnerable to: SQL injection, path traversal, command injection
  const user = db.query(`SELECT * FROM users WHERE id = ${id}`);
  res.json(user);
});
```
**Problem:** Direct string concatenation in queries

#### ✅ SECURE (AFTER)
```javascript
const validator = require('validator');

app.get('/users/:id', authenticateToken, (req, res) => {
  // Validate input
  if (!validator.isInt(req.params.id)) {
    return res.status(400).json({ error: 'Invalid user ID' });
  }

  const userId = parseInt(req.params.id, 10);

  // Use parameterized queries (NEVER concatenate)
  const user = db.query('SELECT * FROM users WHERE id = ?', [userId]);
  res.json(user);
});
```
**Benefit:** SQL injection impossible with parameterized queries

---

### 4. RATE LIMITING

#### ❌ VULNERABLE (BEFORE)
```javascript
// No rate limiting
app.get('/users', (req, res) => {
  // Attacker can make unlimited requests
  // -> Brute force attacks possible
  // -> DoS attacks possible
  // -> Account enumeration possible
  res.json(users);
});
```
**Problem:** Unlimited requests from single IP

#### ✅ SECURE (AFTER)
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // 100 requests per window
  message: 'Too many requests, please try again later'
});

app.use(limiter);
app.get('/users', authenticateToken, (req, res) => {
  res.json(users);
});
```
**Benefit:** Protection against brute force and DoS

---

### 5. CORS CONFIGURATION

#### ❌ VULNERABLE (BEFORE)
```javascript
// No CORS configuration
app.get('/users', (req, res) => {
  res.json(users);
});
// Implicitly allows all origins (no CORS policy = wildcard)
```
**Problem:** Vulnerable to cross-origin attacks

#### ✅ SECURE (AFTER)
```javascript
const cors = require('cors');

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  credentials: true,
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

app.get('/users', authenticateToken, (req, res) => {
  res.json(users);
});
```
**Benefit:** Only trusted origins can access API

---

### 6. REQUEST SIZE LIMITS

#### ❌ VULNERABLE (BEFORE)
```javascript
const express = require('express');
const app = express();

// No size limits
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Attacker could send 1GB payload -> Memory exhaustion
app.post('/data', (req, res) => {
  res.json({ received: req.body });
});
```
**Problem:** Memory exhaustion attack possible

#### ✅ SECURE (AFTER)
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Payloads > 10KB rejected with 413 Payload Too Large
app.post('/data', (req, res) => {
  res.json({ received: req.body });
});
```
**Benefit:** Protection against memory exhaustion

---

### 7. ERROR HANDLING

#### ❌ VULNERABLE (BEFORE)
```javascript
app.get('/users', (req, res) => {
  try {
    const user = db.query("SELECT * FROM users WHERE id = " + req.params.id);
    res.json(user);
  } catch(err) {
    // Stack trace exposed!
    res.status(500).json({ 
      error: err.message,
      stack: err.stack // SECURITY ISSUE!
    });
  }
});
```
**Problem:** Stack traces reveal system information

#### ✅ SECURE (AFTER)
```javascript
app.use((err, req, res, next) => {
  console.error('Error:', err); // Log for debugging

  // Generic error to client
  res.status(err.status || 500).json({
    error: 'Internal server error'
    // No stack trace or message
  });
});

app.get('/users', authenticateToken, (req, res) => {
  try {
    // Use parameterized queries
    const user = db.query('SELECT * FROM users WHERE id = ?', [userId]);
    res.json(user);
  } catch(err) {
    next(err); // Pass to error handler
  }
});
```
**Benefit:** No information disclosure via errors

---

### 8. CONFIGURATION MANAGEMENT

#### ❌ VULNERABLE (BEFORE)
```javascript
