**Implement automatic rotation:**

```javascript
const secretCache = {};
const SECRET_CACHE_TTL = 3600000; // 1 hour

async function getSecret(secretName) {
  // Return cached secret if fresh
  if (secretCache[secretName] && 
      Date.now() - secretCache[secretName].timestamp < SECRET_CACHE_TTL) {
    return secretCache[secretName].value;
  }

  // Fetch fresh secret
  const response = await secretsManager.getSecretValue({
    SecretId: secretName
  }).promise();

  secretCache[secretName] = {
    value: JSON.parse(response.SecretString),
    timestamp: Date.now()
  };

  return secretCache[secretName].value;
}

// Usage with auto-refresh
setInterval(async () => {
  try {
    await getSecret('app/prod/secrets');
    console.log('Secrets refreshed');
  } catch (error) {
    console.error('Failed to refresh secrets:', error);
  }
}, 30 * 60 * 1000); // Refresh every 30 minutes
