// Secure version with security best practices implemented

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('mongo-sanitize');
const xss = require('xss-clean');
const cors = require('cors');
const morgan = require('morgan');
const validator = require('validator');

const app = express();

// ========== SECURITY MIDDLEWARE ==========

// 1. Set security HTTP headers
app.use(helmet());

// 2. CORS - Restrict origins
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['https://example.com'],
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
};
app.use(cors(corsOptions));

// 3. Rate limiting - Prevent brute force/DoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 4. Body parser with size limits
app.use(express.json({ limit: '10kb' })); // Prevent payload bombing
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 5. Data sanitization against NoSQL injection
app.use(mongoSanitize({
  onSanitize: ({ req, key }) => {
    console.warn(`Potential NoSQL injection attempt detected in ${key}`);
  }
}));

// 6. Data sanitization against XSS
app.use(xss());

// 7. Logging - Use morgan for request logging (don't log sensitive data)
app.use(morgan('combined'));

// ========== ENVIRONMENT CONFIGURATION ==========
const NODE_ENV = process.env.NODE_ENV || 'development';
const API_VERSION = process.env.API_VERSION || '1.0.0';

// Disable powered-by header
app.disable('x-powered-by');

// ========== AUTHENTICATION MIDDLEWARE ==========
// Simple JWT validation example
const validateToken = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1]; // Bearer token

  if (!token) {
    return res.status(401).json({ error: 'Unauthorized - Missing token' });
  }

  // In production, use jwt.verify() with a secret
  if (token.length < 10) {
    return res.status(401).json({ error: 'Unauthorized - Invalid token' });
  }

  req.user = { id: 1 }; // Placeholder - decode JWT in production
  next();
};

// ========== INPUT VALIDATION HELPERS ==========
const validateEmail = (email) => {
  if (!email || typeof email !== 'string') {
    return { valid: false, error: 'Email must be a non-empty string' };
  }
  if (!validator.isEmail(email)) {
    return { valid: false, error: 'Invalid email format' };
  }
  if (email.length > 254) {
    return { valid: false, error: 'Email is too long' };
  }
  return { valid: true };
};

const validateUserId = (id) => {
  if (!id || !Number.isInteger(Number(id)) || Number(id) <= 0) {
    return { valid: false, error: 'User ID must be a positive integer' };
  }
  return { valid: true };
};

const validateName = (name) => {
  if (!name || typeof name !== 'string') {
    return { valid: false, error: 'Name must be a non-empty string' };
  }
  if (name.length > 100) {
    return { valid: false, error: 'Name is too long' };
  }
  if (!/^[a-zA-Z\s'-]+$/.test(name)) {
    return { valid: false, error: 'Name contains invalid characters' };
  }
  return { valid: true };
};

// ========== ROUTES ==========

// Health check - Public endpoint
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    version: API_VERSION
  });
});

// Get all users - Protected endpoint with input validation
app.get('/api/users', validateToken, (req, res) => {
  // Validate query parameters
  const { limit, offset } = req.query;

  const validatedLimit = Math.min(parseInt(limit) || 10, 100); // Max 100
  const validatedOffset = Math.max(parseInt(offset) || 0, 0);

  if (validatedLimit <= 0 || validatedOffset < 0) {
    return res.status(400).json({
      error: 'Invalid pagination parameters',
      details: 'limit and offset must be non-negative integers'
    });
  }

  // Mock database data
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const paginatedUsers = users.slice(validatedOffset, validatedOffset + validatedLimit);

  res.json({
    data: paginatedUsers,
    pagination: {
      limit: validatedLimit,
      offset: validatedOffset,
      total: users.length
    }
  });
});

// Get user by ID - Protected with input validation
app.get('/api/users/:id', validateToken, (req, res) => {
  // Validate ID parameter
  const validation = validateUserId(req.params.id);
  if (!validation.valid) {
    return res.status(400).json({ error: validation.error });
  }

  const userId = parseInt(req.params.id);

  // Mock data
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const user = users.find(u => u.id === userId);

  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }

  // Check authorization - users can only see their own data (or admin)
  if (req.user.id !== userId && !req.user.isAdmin) {
    return res.status(403).json({ error: 'Forbidden - Access denied' });
  }

  res.json({ data: user });
});

// Create user - Protected with comprehensive validation
app.post('/api/users', validateToken, (req, res) => {
  const { name, email } = req.body;

  // Validate name
  const nameValidation = validateName(name);
  if (!nameValidation.valid) {
    return res.status(400).json({ error: nameValidation.error });
  }

  // Validate email
  const emailValidation = validateEmail(email);
  if (!emailValidation.valid) {
    return res.status(400).json({ error: emailValidation.error });
  }

  // Additional checks
  if (!req.user.isAdmin) {
    return res.status(403).json({ error: 'Only admins can create users' });
  }

  // Mock create
  const newUser = {
    id: 3,
    name: name.trim(),
    email: email.toLowerCase().trim()
  };

  res.status(201).json({ data: newUser, message: 'User created successfully' });
});

// ========== ERROR HANDLING ==========

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Unexpected error:', {
    message: err.message,
    stack: NODE_ENV === 'production' ? undefined : err.stack,
    timestamp: new Date().toISOString()
  });

  // Don't expose internal errors in production
  const statusCode = err.statusCode || 500;
  const message = NODE_ENV === 'production' ? 'Internal Server Error' : err.message;

  res.status(statusCode).json({
    error: message,
    ...(NODE_ENV !== 'production' && { stack: err.stack })
  });
});

// ========== SERVER STARTUP ==========
const PORT = process.env.PORT || 3000;

if (require.main === module) {
  app.listen(PORT, '127.0.0.1', () => {
    console.log(`Server running on http://127.0.0.1:${PORT}`);
    console.log(`Environment: ${NODE_ENV}`);
  });
}

module.exports = app;

