**Recommendation:**
```javascript
const cors = require('cors');

const corsOptions = {
  origin: ['https://example.com', 'https://app.example.com'],
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
};

app.use(cors(corsOptions));
```

**Issue 2: No Rate Limiting**
**Risk:** DoS attacks, brute force attacks, API abuse

**Recommendation:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,    // 15 minutes
  max: 100,                     // 100 requests per windowMs
  message: 'Too many requests, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Stricter limit for login endpoint
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,  // 5 attempts
  skipSuccessfulRequests: true,
});

app.post('/api/login', loginLimiter, (req, res) => {...});
```

**Issue 3: Server Info Leakage**
```javascript
// VULNERABLE - Exposes Express framework details
// Default header: X-Powered-By: Express
```

**Recommendation:**
```javascript
app.disable('x-powered-by');
```

---

### 🟠 HIGH: A2 - Cryptographic Failures

**Issue:** Plaintext data handling
```javascript
// VULNERABLE - No mention of HTTPS/TLS
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Recommendation:**
```javascript
const https = require('https');
const fs = require('fs');

// Force HTTPS in production
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure) {
    return res.redirect(`https://${req.headers.host}${req.url}`);
  }
  next();
});

if (process.env.NODE_ENV === 'production') {
  const options = {
    key: fs.readFileSync(process.env.PRIVATE_KEY_PATH),
    cert: fs.readFileSync(process.env.CERTIFICATE_PATH)
  };
  https.createServer(options, app).listen(443);
} else {
  app.listen(3000, '127.0.0.1');
}
```

---

### 🟠 HIGH: A4 - Insecure Design (No Input Size Limits)

**Issue:** Unbounded payload handling
```javascript
// VULNERABLE - No payload size limits
app.listen(3000, ...);
```

**Risk:** Payload bombing/DoS attacks

**Recommendation:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

---

### 🟡 MEDIUM: A9 - Logging and Monitoring Failures

**Issue:** No logging mechanism
```javascript
// VULNERABLE - No audit trail or security logging
app.get('/users', (req, res) => {...});
```

**Recommendation:**
```javascript
const morgan = require('morgan');

// Log all requests (but don't log sensitive data)
app.use(morgan('combined'));

// Custom error logging
app.use((err, req, res, next) => {
  console.error({
    timestamp: new Date().toISOString(),
    error: err.message,
    path: req.path,
    method: req.method,
    ip: req.ip,
    userId: req.user?.id
  });

  // Don't expose stack traces in production
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  res.status(500).json({ error: message });
});
```

---

### 🟡 MEDIUM: A10 - Server-Side Request Forgery (SSRF)

**Issue:** If file uploads/external requests added later, SSRF risk
**Recommendation:**
```javascript
// Use allowlist for external APIs/resources
const ALLOWED_DOMAINS = [
  'api.example.com',
  'cdn.example.com'
];

const isAllowedDomain = (url) => {
  try {
    const domain = new URL(url).hostname;
    return ALLOWED_DOMAINS.includes(domain);
  } catch {
    return false;
  }
};

app.post('/api/fetch', validateToken, (req, res) => {
  const { url } = req.body;

  if (!isAllowedDomain(url)) {
    return res.status(400).json({ error: 'Domain not allowed' });
  }

  // Proceed with request
});
```

