## 4. RATE LIMITING CONFIGURATION

### Multi-tier Rate Limiting
```javascript
const rateLimit = require('express-rate-limit');
const RedisStore = require('rate-limit-redis');
const redis = require('redis');

const client = redis.createClient({
  host: process.env.REDIS_HOST || 'localhost',
  port: process.env.REDIS_PORT || 6379
});

// General API limiter
const apiLimiter = rateLimit({
  store: new RedisStore({
    client: client,
    prefix: 'rl:api:'
  }),
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => req.user?.isAdmin, // Skip for admins
  keyGenerator: (req) => req.ip
});

// Login limiter (stricter)
const loginLimiter = rateLimit({
  store: new RedisStore({
    client: client,
    prefix: 'rl:login:'
  }),
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
  message: 'Too many login attempts, please try again later'
});

// Create resource limiter (stricter)
const createLimiter = rateLimit({
  store: new RedisStore({
    client: client,
    prefix: 'rl:create:'
  }),
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 10,
  message: 'Too many resources created, please try again later'
});

app.use('/api/', apiLimiter);
app.post('/api/login', loginLimiter, loginHandler);
app.post('/api/users', createLimiter, createUserHandler);
```

