/**
 * SECURE SECRETS MANAGEMENT IMPLEMENTATION
 * Demonstrates best practices for handling secrets in Node.js
 */

const express = require('express');
const path = require('path');
require('dotenv').config({
  path: path.resolve(__dirname, `.env.${process.env.NODE_ENV}`)
});

// ========== SECRETS MANAGER (Choose one based on your platform) ==========

/**
 * Option 1: AWS Secrets Manager
 */
class AWSSecretsManager {
  constructor() {
    const AWS = require('aws-sdk');
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTimeout = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    // Check cache
    if (this.cache.has(secretName)) {
      const { value, timestamp } = this.cache.get(secretName);
      if (Date.now() - timestamp < this.cacheTimeout) {
        return value;
      }
      this.cache.delete(secretName);
    }

    try {
      const response = await this.client.getSecretValue({
        SecretId: secretName
      }).promise();

      let secret;
      if (response.SecretString) {
        secret = JSON.parse(response.SecretString);
      } else {
        secret = Buffer.from(response.SecretBinary, 'base64');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  async rotateSecret(secretName, newSecret) {
    try {
      const response = await this.client.putSecretValue({
        SecretId: secretName,
        ClientRequestToken: this.generateToken(),
        SecretString: JSON.stringify(newSecret)
      }).promise();

      // Invalidate cache
      this.cache.delete(secretName);

      console.log(`✅ Secret rotated: ${secretName} (v${response.VersionId})`);
      return response.VersionId;
    } catch (error) {
      console.error(`Error rotating secret ${secretName}:`, error);
      throw error;
    }
  }

  generateToken() {
    return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }
}

/**
 * Option 2: HashiCorp Vault
 */
class VaultSecretsManager {
  constructor() {
    const VaultClient = require('node-vault');
    this.client = new VaultClient({
      endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
      token: process.env.VAULT_TOKEN
    });
    this.cache = new Map();
    this.cacheTimeout = 3600000; // 1 hour
  }

  async getSecret(path) {
    if (this.cache.has(path)) {
      const { value, timestamp } = this.cache.get(path);
      if (Date.now() - timestamp < this.cacheTimeout) {
        return value;
      }
      this.cache.delete(path);
    }

    try {
      const response = await this.client.read(path);
      const secret = response.data.data || response.data;

      this.cache.set(path, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      console.error(`Error retrieving secret from ${path}:`, error);
      throw new Error(`Failed to retrieve secret: ${path}`);
    }
  }

  async rotateSecret(path, newSecret) {
    try {
      await this.client.write(path, newSecret);
      this.cache.delete(path);
      console.log(`✅ Secret rotated in Vault: ${path}`);
    } catch (error) {
      console.error(`Error rotating secret in ${path}:`, error);
      throw error;
    }
  }
}

/**
 * Option 3: Azure Key Vault
 */
class AzureKeyVaultManager {
  constructor() {
    const { SecretClient } = require('@azure/keyvault-secrets');
    const { DefaultAzureCredential } = require('@azure/identity');

    const credential = new DefaultAzureCredential();
    this.client = new SecretClient(
      `https://${process.env.AZURE_VAULT_NAME}.vault.azure.net/`,
      credential
    );
    this.cache = new Map();
    this.cacheTimeout = 3600000;
  }

  async getSecret(secretName) {
    if (this.cache.has(secretName)) {
      const { value, timestamp } = this.cache.get(secretName);
      if (Date.now() - timestamp < this.cacheTimeout) {
        return value;
      }
      this.cache.delete(secretName);
    }

    try {
      const secret = await this.client.getSecret(secretName);
      const value = JSON.parse(secret.value);

      this.cache.set(secretName, {
        value,
        timestamp: Date.now()
      });

      return value;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  async rotateSecret(secretName, newSecret) {
    try {
      await this.client.setSecret(
        secretName,
        JSON.stringify(newSecret)
      );
      this.cache.delete(secretName);
      console.log(`✅ Secret rotated in Azure Key Vault: ${secretName}`);
    } catch (error) {
      console.error(`Error rotating secret ${secretName}:`, error);
      throw error;
    }
  }
}

// ========== CONFIGURATION MANAGEMENT ==========

class SecureConfig {
  constructor(secretsManager) {
    this.secretsManager = secretsManager;
    this.config = {};
  }

  async initialize() {
    // Load secrets based on environment
    const environment = process.env.NODE_ENV || 'development';

    console.log(`🔐 Loading secrets for ${environment} environment...`);

    try {
      if (this.secretsManager) {
        // Load from secrets manager (production)
        await this.loadFromSecretsManager();
      } else {
        // Fall back to .env (development only)
        await this.loadFromEnv();
      }

      // Validate required secrets
      this.validateRequiredSecrets();

      console.log('✅ Secrets loaded successfully');
    } catch (error) {
      console.error('❌ Failed to load secrets:', error.message);
      throw error;
    }
  }

  async loadFromSecretsManager() {
    // Load database credentials
    const dbSecret = await this.secretsManager.getSecret('prod/database');
    this.config.database = {
      url: `postgres://${dbSecret.username}:${dbSecret.password}@${dbSecret.host}:${dbSecret.port}/${dbSecret.database}`,
      ssl: dbSecret.ssl !== false
    };

    // Load JWT secret
    const jwtSecret = await this.secretsManager.getSecret('prod/jwt');
    this.config.jwt = {
      secret: jwtSecret.secret,
      expiry: jwtSecret.expiry || '24h'
    };

    // Load API keys
    const apiKeys = await this.secretsManager.getSecret('prod/api-keys');
    this.config.api = apiKeys;

    // Load third-party service credentials
    this.config.aws = await this.secretsManager.getSecret('prod/aws');
    this.config.stripe = await this.secretsManager.getSecret('prod/stripe');
  }

  loadFromEnv() {
    // DEVELOPMENT ONLY
    if (process.env.NODE_ENV !== 'development') {
      throw new Error('Environment variables only allowed in development');
    }

    this.config = {
      database: {
        url: process.env.DATABASE_URL,
        ssl: process.env.DB_SSL === 'true'
      },
      jwt: {
        secret: process.env.JWT_SECRET,
        expiry: process.env.JWT_EXPIRY || '24h'
      },
      api: {
        key: process.env.API_KEY
      },
      aws: {
        accessKeyId: process.env.AWS_ACCESS_KEY_ID,
        secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
        region: process.env.AWS_REGION
      },
      stripe: {
        secretKey: process.env.STRIPE_SECRET_KEY,
        publishableKey: process.env.STRIPE_PUBLISHABLE_KEY
      }
    };
  }

  validateRequiredSecrets() {
    const required = [
      'database.url',
      'jwt.secret',
      'api.key'
    ];

    for (const key of required) {
      const [primary, secondary] = key.split('.');
      if (!this.config[primary]?.[secondary]) {
        throw new Error(`Missing required secret: ${key}`);
      }
    }
  }

  get(key) {
    const keys = key.split('.');
    let value = this.config;

    for (const k of keys) {
      value = value[k];
      if (value === undefined) {
        throw new Error(`Configuration key not found: ${key}`);
      }
    }

    return value;
  }

  // Return sanitized config (for logging)
  toJSON() {
    return this.sanitize(this.config);
  }

  sanitize(obj) {
    if (typeof obj !== 'object' || obj === null) {
      return obj;
    }

    const sensitiveKeys = ['password', 'secret', 'key', 'token', 'credential'];
    const sanitized = Array.isArray(obj) ? [...obj] : { ...obj };

    Object.keys(sanitized).forEach(key => {
      if (sensitiveKeys.some(s => key.toLowerCase().includes(s))) {
        sanitized[key] = '***REDACTED***';
      } else if (typeof sanitized[key] === 'object') {
        sanitized[key] = this.sanitize(sanitized[key]);
      }
    });

    return sanitized;
  }
}

// ========== APPLICATION SETUP ==========

async function createApp() {
  const app = express();

