      secretsManager = new AWSSecretsManager();
    } else if (process.env.SECRETS_MANAGER === 'vault') {
      secretsManager = new VaultSecretsManager();
    } else if (process.env.SECRETS_MANAGER === 'azure') {
      secretsManager = new AzureKeyVaultManager();
    }
  }

  // 2. Initialize configuration
  const config = new SecureConfig(secretsManager);
  await config.initialize();

  // 3. Store config in app locals (not in environment)
  app.locals.config = config;

  // ========== MIDDLEWARE ==========

  app.use(express.json({ limit: '10kb' }));

  // Middleware to prevent secrets in logs
  app.use((req, res, next) => {
    // Sanitize request body if it contains sensitive fields
    if (req.body) {
      const sensitiveFields = ['password', 'token', 'secret', 'key', 'credit_card'];
      Object.keys(req.body).forEach(key => {
