      timestamp: new Date().toISOString(),
      // NEVER return actual config
      environment: process.env.NODE_ENV
    });
  });

  // Secure route using config
  app.get('/api/users', (req, res) => {
    try {
      // Access config safely
      const dbUrl = app.locals.config.get('database.url');

      // Never return the actual URL
      res.json({
