### Recommended Solution:

```javascript
// Implement automatic secret rotation
const cron = require('node-cron');
const AWS = require('aws-sdk');

class SecretsManager {
  constructor() {
    this.secrets = null;
    this.lastRefresh = null;
    this.refreshInterval = 60 * 60 * 1000; // 1 hour
  }

  async initialize() {
    await this.refreshSecrets();

    // Refresh secrets every hour
    cron.schedule('0 * * * *', () => {
      this.refreshSecrets();
    });
  }

  async refreshSecrets() {
    try {
      const secretsManager = new AWS.SecretsManager();
      const data = await secretsManager.getSecretValue({
        SecretId: process.env.SECRET_ARN
      }).promise();

      this.secrets = JSON.parse(data.SecretString);
      this.lastRefresh = new Date();

      console.log('Secrets refreshed at', this.lastRefresh);
      return this.secrets;
    } catch (error) {
      console.error('Failed to refresh secrets:', error);

      // If refresh fails, keep using cached secrets
      if (!this.secrets) {
        throw error; // First load must succeed
      }
    }
  }

  getSecret(key) {
    if (!this.secrets) {
      throw new Error('Secrets not initialized');
    }

    const value = this.secrets[key];
    if (!value) {
      throw new Error(`Secret key '${key}' not found`);
    }

    return value;
  }
}

module.exports = SecretsManager;
```

