/**
 * SECURE EXPRESS APPLICATION
 * 
 * This is a production-ready, security-hardened version of app.js
 * Implements authentication, authorization, validation, and security headers
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const { query, validationResult } = require('express-validator');
const dotenv = require('dotenv');
const winston = require('winston');

// Load environment variables
dotenv.config();

const app = express();

// ============================================================================
// SECURITY CONFIGURATION
// ============================================================================

// Validate required environment variables
const requiredEnvVars = ['NODE_ENV', 'JWT_SECRET', 'PORT'];
requiredEnvVars.forEach(envVar => {
  if (!process.env[envVar]) {
    throw new Error(`Missing required environment variable: ${envVar}`);
  }
});

const PORT = parseInt(process.env.PORT, 10) || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const JWT_SECRET = process.env.JWT_SECRET;

// ============================================================================
// LOGGING CONFIGURATION
// ============================================================================

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'api-service' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

if (NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

// Security event logger
const logSecurityEvent = (event, details) => {
  logger.warn({
    timestamp: new Date().toISOString(),
    event,
    ...details
  });
};

// ============================================================================
// REQUEST SIZE AND PARSING LIMITS
// ============================================================================

app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// ============================================================================
// HELMET - SECURITY HEADERS
// ============================================================================

app.use(helmet());

// Additional custom security headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  res.setHeader('Permissions-Policy', 'geolocation=(), microphone=(), camera=()');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  next();
});

// ============================================================================
// HTTPS REDIRECT
// ============================================================================

app.use((req, res, next) => {
  if (NODE_ENV === 'production') {
    if (req.header('x-forwarded-proto') !== 'https') {
      return res.redirect(301, `https://${req.header('host')}${req.url}`);
    }
  }
  next();
});

// ============================================================================
// CORS CONFIGURATION
// ============================================================================

const corsOptions = {
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600
};

app.use(cors(corsOptions));

// ============================================================================
// RATE LIMITING
// ============================================================================

const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => NODE_ENV !== 'production'
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // limit each IP to 5 login attempts per windowMs
  message: 'Too many login attempts, please try again after 15 minutes',
  skipSuccessfulRequests: true
});

app.use(globalLimiter);

// ============================================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================================

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logSecurityEvent('missing_auth_token', {
      ip: req.ip,
      url: req.url,
      method: req.method
    });
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      logSecurityEvent('invalid_token', {
        ip: req.ip,
        url: req.url,
        error: err.message
      });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// ============================================================================
// AUTHORIZATION MIDDLEWARE
// ============================================================================

const authorize = (requiredRoles) => {
  return (req, res, next) => {
    if (!req.user || !requiredRoles.includes(req.user.role)) {
      logSecurityEvent('unauthorized_access_attempt', {
        ip: req.ip,
        url: req.url,
        userId: req.user?.id,
        requiredRoles,
        userRole: req.user?.role
      });
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
};

// ============================================================================
// SECURITY MONITORING
// ============================================================================

app.use((req, res, next) => {
  res.on('finish', () => {
    if (res.statusCode === 401 || res.statusCode === 403) {
      logSecurityEvent('security_event', {
        ip: req.ip,
        url: req.url,
        method: req.method,
        statusCode: res.statusCode
      });
    }
  });
  next();
});

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint (public)
 * GET /health
 */
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV
  });
});

/**
 * Login endpoint
 * POST /login
 * Body: { username: string, password: string }
 */
app.post('/login', authLimiter, (req, res) => {
  try {
    // IMPORTANT: In production, verify credentials against database using bcrypt
    // This is a simplified example
    const { username, password } = req.body;

    if (!username || !password) {
      logSecurityEvent('login_failed', {
        ip: req.ip,
        reason: 'missing_credentials'
      });
      return res.status(400).json({ error: 'Username and password required' });
    }

    // Mock authentication (REPLACE WITH REAL AUTHENTICATION)
    if (username === 'admin' && password === process.env.ADMIN_PASSWORD) {
      const user = { 
        id: 1, 
        username: 'admin',
        role: 'admin',
        iat: Date.now()
      };
      const token = jwt.sign(user, JWT_SECRET, { expiresIn: '1h' });

      logger.info({
        event: 'user_login_successful',
        ip: req.ip,
        username
      });

      return res.json({ token, expiresIn: '1h' });
    }

    logSecurityEvent('login_failed', {
      ip: req.ip,
      username,
      reason: 'invalid_credentials'
    });
    return res.status(401).json({ error: 'Invalid credentials' });

  } catch (error) {
    logger.error({
      message: 'Login error',
      error: error.message
    });
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Get all users (admin only)
 * GET /users
 * Requires: Authentication + Admin role
 * Query params (optional): id (integer), email (valid email)
 */
app.get('/users',
  authenticateToken,
  authorize(['admin']),
  query('id').optional().isInt().toInt(),
  query('email').optional().isEmail(),
  (req, res) => {
    try {
      // Validate query parameters
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ errors: errors.array() });
      }

      // Mock user data (would come from database in real app)
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      logger.info({
        event: 'users_retrieved',
        userId: req.user.id,
        ip: req.ip
      });

      res.json(users);
    } catch (error) {
      logger.error({
        message: 'Error retrieving users',
        error: error.message,
        userId: req.user.id
      });
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

/**
 * Get user by ID
 * GET /users/:id
 * Requires: Authentication
 * Allows: Users to view their own profile, admins to view any profile
 */
app.get('/users/:id',
  authenticateToken,
  query('id').optional().isInt(),
  (req, res) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ errors: errors.array() });
      }

      const userId = parseInt(req.params.id, 10);

      // Authorization: Can only view own profile or admin can view any
      if (userId !== req.user.id && req.user.role !== 'admin') {
        logSecurityEvent('unauthorized_user_access', {
          ip: req.ip,
          requestedUserId: userId,
          authenticatedUserId: req.user.id
        });
        return res.status(403).json({ error: 'Not authorized to view this user' });
      }

      // Mock user data
      const user = { 
        id: userId, 
        name: 'Alice', 
        email: 'alice@example.com' 
      };

      logger.info({
        event: 'user_profile_viewed',
        viewedUserId: userId,
        viewerUserId: req.user.id,
        ip: req.ip
      });

      res.json(user);
    } catch (error) {
      logger.error({
        message: 'Error retrieving user',
        error: error.message,
        userId: req.user.id
      });
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * 404 Not Found Handler
 */
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    path: req.path 
  });
});

/**
 * Global error handler
 */
app.use((err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
