// SECURED VERSION OF app.js WITH SECURITY IMPROVEMENTS
// See detailed security recommendations below

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const cors = require('cors');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE - APPLIED FIRST
// ============================================================================

// 1. HELMET - Sets various HTTP headers for security
app.use(helmet());

// 2. CORS - Restrict cross-origin requests
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// 3. RATE LIMITING - Prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use(limiter);

// 4. BODY PARSER with size limits to prevent large payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ============================================================================
// MIDDLEWARE - INPUT VALIDATION ERROR HANDLER
// ============================================================================

const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Invalid input',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// ============================================================================
// AUTHENTICATION/AUTHORIZATION (Example implementation)
// ============================================================================

// Mock authentication middleware - REPLACE WITH REAL AUTH
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No authentication token provided' });
  }

  // TODO: Validate JWT token properly in production
  // Use a library like jsonwebtoken and verify against your secret
  try {
    // This is a simplified example - use proper JWT verification
    const decoded = require('jsonwebtoken').verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
};

// ============================================================================
// ROUTES WITH VALIDATION
// ============================================================================

// HEALTH CHECK - Public endpoint (no auth required)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    version: '1.0.0'
  });
});

// GET USERS - Protected endpoint with input validation
// VULNERABILITY FIXES:
// 1. Added authentication requirement
// 2. Added input validation for query parameters
// 3. Limited returned fields to prevent data leakage
// 4. Added pagination to prevent resource exhaustion
app.get('/users',
  authenticateToken,
  [
    query('page')
      .optional()
      .isInt({ min: 1, max: 1000 })
      .withMessage('Page must be a positive integer between 1 and 1000'),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('sort')
      .optional()
      .isIn(['id', 'name', 'email'])
      .withMessage('Invalid sort field')
  ],
  handleValidationErrors,
  (req, res) => {
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;
    const sort = req.query.sort || 'id';

    // Sample data - in production, fetch from secure database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Return only necessary fields (prevents information disclosure)
    const safeUsers = users.map(user => ({
      id: user.id,
      name: user.name,
      email: user.email
      // Don't include sensitive fields like password_hash, ssn, etc.
    }));

    res.json({
      data: safeUsers.slice((page - 1) * limit, page * limit),
      pagination: {
        page,
        limit,
        total: safeUsers.length
      }
    });
  }
);

// POST USER - Example of secure data creation with validation
app.post('/users',
  authenticateToken,
  [
    body('name')
      .trim()
      .notEmpty().withMessage('Name is required')
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .matches(/^[a-zA-Z\s'-]+$/)
      .withMessage('Name contains invalid characters'),
    body('email')
      .trim()
      .isEmail().withMessage('Invalid email format')
      .normalizeEmail(),
    body('phone')
      .optional()
      .trim()
      .matches(/^\+?[1-9]\d{1,14}$/)
