// Security testing examples for app.js
// Run with: npm test

const request = require('supertest');
const app = require('./app_secured');
const jwt = require('jsonwebtoken');

describe('Security Tests', () => {

  let validToken;
  let invalidToken = 'invalid.token.here';

  beforeAll(() => {
    // Generate a valid token for testing
    validToken = jwt.sign(
      { id: 1, email: 'test@example.com' },
      process.env.JWT_SECRET || 'test-secret',
      { expiresIn: '1h' }
    );
  });

  describe('Authentication Tests', () => {

    it('should reject requests without authentication token', async () => {
      const res = await request(app)
        .get('/users');

      expect(res.status).toBe(401);
      expect(res.body.error).toBeDefined();
    });

    it('should reject requests with invalid token', async () => {
      const res = await request(app)
        .get('/users')
        .set('Authorization', `Bearer ${invalidToken}`);

      expect(res.status).toBe(403);
      expect(res.body.error).toBeDefined();
    });

    it('should accept requests with valid token', async () => {
      const res = await request(app)
        .get('/users')
        .set('Authorization', `Bearer ${validToken}`);

      expect(res.status).toBe(200);
      expect(res.body.data).toBeDefined();
    });
  });

  describe('Input Validation Tests', () => {

    it('should reject invalid page parameter', async () => {
      const res = await request(app)
        .get('/users?page=invalid')
        .set('Authorization', `Bearer ${validToken}`);

      expect(res.status).toBe(400);
      expect(res.body.error).toBe('Invalid input');
    });

    it('should reject page > 1000', async () => {
      const res = await request(app)
        .get('/users?page=9999')
        .set('Authorization', `Bearer ${validToken}`);

      expect(res.status).toBe(400);
    });

    it('should reject limit > 100', async () => {
      const res = await request(app)
        .get('/users?limit=999')
        .set('Authorization', `Bearer ${validToken}`);

      expect(res.status).toBe(400);
    });

    it('should reject invalid sort parameter', async () => {
      const res = await request(app)
        .get('/users?sort=malicious_field')
        .set('Authorization', `Bearer ${validToken}`);

      expect(res.status).toBe(400);
    });

    it('should accept valid parameters', async () => {
      const res = await request(app)
        .get('/users?page=1&limit=10&sort=name')
        .set('Authorization', `Bearer ${validToken}`);

      expect(res.status).toBe(200);
      expect(res.body.data).toBeInstanceOf(Array);
      expect(res.body.pagination).toBeDefined();
    });
  });

  describe('Input Sanitization Tests', () => {

    it('should sanitize user input on create', async () => {
      const res = await request(app)
        .post('/users')
        .set('Authorization', `Bearer ${validToken}`)
        .send({
          name: '<script>alert("xss")</script>',
          email: 'test@example.com'
        });

      expect(res.status).toBe(400);
    });

    it('should reject invalid email format', async () => {
      const res = await request(app)
        .post('/users')
        .set('Authorization', `Bearer ${validToken}`)
        .send({
          name: 'John Doe',
          email: 'not-an-email'
        });

      expect(res.status).toBe(400);
    });

    it('should validate phone number format', async () => {
      const res = await request(app)
        .post('/users')
        .set('Authorization', `Bearer ${validToken}`)
        .send({
          name: 'John Doe',
          email: 'john@example.com',
          phone: 'invalid'
        });

      expect(res.status).toBe(400);
    });

    it('should accept valid phone in E.164 format', async () => {
      const res = await request(app)
        .post('/users')
        .set('Authorization', `Bearer ${validToken}`)
        .send({
          name: 'John Doe',
          email: 'john@example.com',
          phone: '+12025551234'
        });

      expect(res.status).toBe(201);
    });
  });

  describe('Security Headers Tests', () => {

    it('should include security headers', async () => {
      const res = await request(app)
        .get('/health');

      expect(res.headers['x-content-type-options']).toBe('nosniff');
      expect(res.headers['x-frame-options']).toBeDefined();
      expect(res.headers['strict-transport-security']).toBeDefined();
    });

    it('should include CSP header', async () => {
      const res = await request(app)
        .get('/health');

      expect(res.headers['content-security-policy']).toBeDefined();
    });
  });

  describe('Rate Limiting Tests', () => {

    it('should allow requests under limit', async () => {
      const res = await request(app)
        .get('/health');

      expect(res.status).toBe(200);
      expect(res.headers['ratelimit-limit']).toBeDefined();
    });

    it('should include rate limit headers', async () => {
      const res = await request(app)
        .get('/health');

      expect(res.headers['ratelimit-limit']).toBeDefined();
      expect(res.headers['ratelimit-remaining']).toBeDefined();
    });
  });

  describe('Error Handling Tests', () => {

    it('should return 404 for undefined routes', async () => {
      const res = await request(app)
        .get('/undefined-route');

      expect(res.status).toBe(404);
      expect(res.body.error).toBe('Not found');
    });

    it('should not expose stack traces in production mode', async () => {
      process.env.NODE_ENV = 'production';

      const res = await request(app)
        .get('/health');

      expect(res.body.stack).toBeUndefined();
    });
  });

  describe('CORS Tests', () => {

    it('should set CORS headers for allowed origins', async () => {
      const res = await request(app)
        .get('/health')
        .set('Origin', 'http://localhost:3000');

      expect(res.headers['access-control-allow-origin']).toBeDefined();
    });
  });

  describe('Data Exposure Tests', () => {

    it('should not return sensitive fields', async () => {
      const res = await request(app)
        .get('/users')
        .set('Authorization', `Bearer ${validToken}`);

      expect(res.status).toBe(200);

      res.body.data.forEach(user => {
        expect(user.password).toBeUndefined();
        expect(user.password_hash).toBeUndefined();
        expect(user.ssn).toBeUndefined();
        expect(user.api_key).toBeUndefined();
      });
    });

    it('should include pagination info', async () => {
      const res = await request(app)
        .get('/users')
        .set('Authorization', `Bearer ${validToken}`);

      expect(res.body.pagination).toBeDefined();
      expect(res.body.pagination.page).toBeDefined();
      expect(res.body.pagination.limit).toBeDefined();
    });
  });

  describe('Body Size Limit Tests', () => {

    it('should reject oversized payloads', async () => {
      const largePayload = { name: 'A'.repeat(50000) };

      const res = await request(app)
        .post('/users')
        .set('Authorization', `Bearer ${validToken}`)
        .send(largePayload);

      expect(res.status).toBeGreaterThanOrEqual(400);
    });
  });

  describe('SQL Injection Prevention', () => {

    it('should safely handle SQL injection attempts', async () => {
      const res = await request(app)
        .get("/users?sort=id' OR '1'='1")
        .set('Authorization', `Bearer ${validToken}`);

      expect(res.status).toBe(400);
    });
  });

  describe('XSS Prevention', () => {

    it('should sanitize script tags in input', async () => {
      const xssPayload = {
        name: 'John<script>alert("xss")</script>',
        email: 'john@example.com'
      };

      const res = await request(app)
        .post('/users')
        .set('Authorization', `Bearer ${validToken}`)
        .send(xssPayload);

      expect(res.status).toBe(400);
    });
  });
});

// Comprehensive Security Configuration for Express.js
// Import and use: const securityConfig = require('./security-config');
// Then: app.use(securityConfig.middleware);

const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const express = require('express');

// ============================================================================
// HELMET CONFIGURATION - HTTP Security Headers
// ============================================================================

const helmetConfig = helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", 'data:', 'https:'],
      fontSrc: ["'self'"],
      connectSrc: ["'self'"],
      frameSrc: ["'none'"],
      objectSrc: ["'none'"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true,
  },
  frameguard: { action: 'deny' },
  nosniff: true,
  xssFilter: true,
});

// ============================================================================
// RATE LIMITING CONFIGURATIONS
// ============================================================================

const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per window
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  keyGenerator: (req, res) => {
    // Use user ID if authenticated, otherwise use IP
    return req.user?.id || req.ip;
  },
  skip: (req, res) => {
    // Don't rate limit health checks
    return req.path === '/health';
  },
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 attempts
  skipSuccessfulRequests: true,
  message: 'Too many authentication attempts, please try again later.',
});

const apiLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 30, // 30 requests per minute for API endpoints
  message: 'Too many API requests, please try again later.',
});

// ============================================================================
// CORS CONFIGURATION
// ============================================================================

const corsConfig = {
  origin: (origin, callback) => {
    const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || [
      'http://localhost:3000',
      'http://localhost:3001',
    ];

    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],
  maxAge: 86400, // 24 hours
  optionsSuccessStatus: 200,
};

// ============================================================================
// BODY PARSER CONFIGURATION
// ============================================================================

const bodyParserConfig = {
  json: {
    limit: '10kb',
    strict: true,
  },
  urlencoded: {
    limit: '10kb',
    extended: true,
  },
};

// ============================================================================
// REQUEST LOGGING MIDDLEWARE
// ============================================================================

const requestLogger = (req, res, next) => {
  const start = Date.now();

  // Log when response is sent
  res.on('finish', () => {
    const duration = Date.now() - start;
    const log = {
      timestamp: new Date().toISOString(),
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('user-agent'),
      userId: req.user?.id,
    };
    console.log(JSON.stringify(log));
  });

  next();
};

// ============================================================================
// SECURITY HEADERS MIDDLEWARE
// ============================================================================

const securityHeadersMiddleware = (req, res, next) => {
  // Prevent browsers from inferring content type
  res.set('X-Content-Type-Options', 'nosniff');

  // Prevent clickjacking
  res.set('X-Frame-Options', 'DENY');

  // Enable browser XSS protection
  res.set('X-XSS-Protection', '1; mode=block');

  // Disable client-side caching for sensitive data
  if (req.path.includes('/users') || req.path.includes('/admin')) {
    res.set('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
    res.set('Pragma', 'no-cache');
    res.set('Expires', '0');
  }

  next();
};

// ============================================================================
// INPUT SANITIZATION MIDDLEWARE
// ============================================================================

const sanitizeInput = (req, res, next) => {
  // Trim all string inputs
  const sanitize = (obj) => {
    if (typeof obj === 'string') {
      return obj.trim();
    }
    if (typeof obj === 'object' && obj !== null) {
      return Object.keys(obj).reduce((acc, key) => {
        acc[key] = sanitize(obj[key]);
        return acc;
      }, Array.isArray(obj) ? [] : {});
    }
    return obj;
  };

  if (req.body) {
    req.body = sanitize(req.body);
  }
  if (req.query) {
    req.query = sanitize(req.query);
  }

  next();
};

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

const errorHandler = (err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

  const isDevelopment = process.env.NODE_ENV === 'development';
  const statusCode = err.status || err.statusCode || 500;

  const response = {
    error: err.message || 'Internal server error',
    ...(isDevelopment && { stack: err.stack }),
    requestId: req.id, // Should be set by request ID middleware
  };

  res.status(statusCode).json(response);
};

// ============================================================================
// REQUEST ID MIDDLEWARE - For tracking requests
// ============================================================================

const requestIdMiddleware = (req, res, next) => {
  req.id = `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  res.setHeader('X-Request-ID', req.id);
  next();
};

// ============================================================================
// COMBINED MIDDLEWARE STACK
// ============================================================================

const allMiddleware = [
  requestIdMiddleware,
  helmetConfig,
  cors(corsConfig),
