// SECURE SECRETS LOADING MODULE
// Use this to abstract secrets management from the rest of your app

const AWS = require('aws-sdk');
const fs = require('fs');
const path = require('path');

class SecretsLoader {
  constructor(options = {}) {
    this.useLocalFallback = options.useLocalFallback !== false; // true by default
    this.cacheTTL = options.cacheTTL || 3600000; // 1 hour
    this.secrets = null;
    this.lastLoadTime = null;
    this.environment = process.env.NODE_ENV || 'development';
  }

  /**
   * Load secrets from the configured source
   * Priority: AWS Secrets Manager > Environment Variables > Local file
   */
  async loadSecrets() {
    // Return cached secrets if still valid
    if (this.secrets && this.isCacheValid()) {
      console.log('Returning cached secrets');
      return this.secrets;
    }

    try {
      // Try AWS Secrets Manager first (production)
      if (this.isProduction() && process.env.AWS_SECRET_NAME) {
        console.log('Loading secrets from AWS Secrets Manager...');
        this.secrets = await this.loadFromAWS();
      }
      // Try environment variables (staging)
      else if (this.hasRequiredEnvVars()) {
        console.log('Loading secrets from environment variables...');
        this.secrets = this.loadFromEnv();
      }
      // Try local file as fallback (development)
      else if (this.useLocalFallback && this.hasLocalSecretsFile()) {
        console.log('Loading secrets from local file...');
        this.secrets = this.loadFromFile();
      }
      // If nothing works, throw error
      else {
        throw new Error(
          'No valid secrets source found. ' +
          'Set AWS_SECRET_NAME (prod), env vars (staging), or local .secrets file (dev)'
        );
      }

      this.lastLoadTime = Date.now();
      this.validateSecrets();
      return this.secrets;
    } catch (error) {
      console.error('Failed to load secrets:', error.message);
      throw error;
    }
  }

  /**
   * Load from AWS Secrets Manager (Production)
   */
  async loadFromAWS() {
    const secretsManager = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });

    try {
      const response = await secretsManager.getSecretValue({
        SecretId: process.env.AWS_SECRET_NAME
      }).promise();

      let secretString;
      if ('SecretString' in response) {
        secretString = response.SecretString;
      } else {
        secretString = Buffer.from(
          response.SecretBinary,
          'base64'
        ).toString('utf8');
      }

      return JSON.parse(secretString);
    } catch (error) {
      throw new Error(`AWS Secrets Manager error: ${error.message}`);
    }
  }

  /**
   * Load from environment variables (Staging)
   */
  loadFromEnv() {
    const requiredVars = [
      'JWT_SECRET',
      'DATABASE_URL',
      'ALLOWED_ORIGINS'
    ];

    const secrets = {};
    for (const varName of requiredVars) {
      if (!process.env[varName]) {
        throw new Error(`Missing required environment variable: ${varName}`);
      }
      secrets[varName] = process.env[varName];
    }

    return secrets;
  }

  /**
   * Load from encrypted local file (Development)
   */
  loadFromFile() {
    const secretsPath = path.join(process.cwd(), '.secrets');

    if (!fs.existsSync(secretsPath)) {
      throw new Error(
        `Secrets file not found at ${secretsPath}. ` +
        'Create it with: node scripts/setup-secrets.js'
      );
    }

    try {
      const content = fs.readFileSync(secretsPath, 'utf8');

      // If file is encrypted, decrypt it
      if (process.env.MASTER_KEY) {
        return this.decryptSecrets(content);
      }

      // Otherwise, parse as JSON (development only)
      return JSON.parse(content);
    } catch (error) {
      throw new Error(`Failed to load secrets file: ${error.message}`);
    }
  }

  /**
   * Simple encryption/decryption for local development
   */
  decryptSecrets(encryptedContent) {
    const crypto = require('crypto');
    const masterKey = process.env.MASTER_KEY;

    if (!masterKey) {
      throw new Error('MASTER_KEY required for encrypted secrets');
    }

    try {
      const [iv, encrypted] = encryptedContent.split(':');
      const decipher = crypto.createDecipheriv(
        'aes-256-cbc',
        Buffer.from(masterKey, 'hex'),
        Buffer.from(iv, 'hex')
      );

      let decrypted = decipher.update(encrypted, 'hex', 'utf8');
      decrypted += decipher.final('utf8');
      return JSON.parse(decrypted);
    } catch (error) {
      throw new Error(`Failed to decrypt secrets: ${error.message}`);
    }
  }

  /**
   * Validate that all required secrets are present
   */
  validateSecrets() {
    const required = ['JWT_SECRET', 'DATABASE_URL', 'ALLOWED_ORIGINS'];

    for (const secret of required) {
      if (!this.secrets[secret]) {
        throw new Error(`Missing required secret: ${secret}`);
      }

      // Additional validations
      if (secret === 'JWT_SECRET' && this.secrets[secret].length < 32) {
        throw new Error('JWT_SECRET must be at least 32 characters');
      }

      if (secret === 'DATABASE_URL' && !this.secrets[secret].startsWith('postgresql://')) {
        console.warn('DATABASE_URL should use PostgreSQL connection string');
      }
    }

    console.log('All required secrets validated ✓');
  }

  /**
   * Check if cache is still valid
   */
  isCacheValid() {
    if (!this.lastLoadTime) return false;
    return (Date.now() - this.lastLoadTime) < this.cacheTTL;
  }

  /**
   * Check if running in production
   */
  isProduction() {
    return this.environment === 'production';
  }

  /**
   * Check if all required env vars are set
   */
  hasRequiredEnvVars() {
    return !!(
      process.env.JWT_SECRET &&
      process.env.DATABASE_URL &&
      process.env.ALLOWED_ORIGINS
    );
  }

  /**
   * Check if local secrets file exists
   */
  hasLocalSecretsFile() {
    const secretsPath = path.join(process.cwd(), '.secrets');
    return fs.existsSync(secretsPath);
  }

  /**
   * Get a specific secret
   */
  getSecret(name) {
    if (!this.secrets) {
      throw new Error('Secrets not loaded. Call loadSecrets() first');
    }

    if (!this.secrets[name]) {
      throw new Error(`Secret not found: ${name}`);
    }

    return this.secrets[name];
  }

  /**
   * Force reload secrets (for rotation testing)
   */
  async forceReload() {
    this.secrets = null;
    this.lastLoadTime = null;
    console.log('Secrets cache cleared, will reload on next access');
    return this.loadSecrets();
  }

  /**
   * Get all loaded secrets (be careful with this!)
   */
  getAllSecrets() {
    if (!this.secrets) {
      throw new Error('Secrets not loaded');
    }
    return { ...this.secrets }; // Return copy, not reference
  }
}

module.exports = SecretsLoader;

// SETUP SCRIPT FOR LOCAL DEVELOPMENT
// Creates encrypted .secrets file for development
// Usage: node scripts/setup-secrets.js

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const readline = require('readline');

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

function question(query) {
  return new Promise((resolve) => {
    rl.question(query, resolve);
  });
}

async function main() {
  console.log('\n╔════════════════════════════════════════╗');
  console.log('║  Secure Secrets Setup for Development   ║');
  console.log('╚════════════════════════════════════════╝\n');

  // Determine encryption preference
  const encrypt = await question(
    'Would you like to encrypt secrets? (y/n) [recommended for teams]: '
  );
  const useEncryption = encrypt.toLowerCase() === 'y';

  let masterKey = null;
  if (useEncryption) {
    // Generate or use provided master key
    const provideMasterKey = await question(
      'Do you have an existing MASTER_KEY? (y/n): '
    );

    if (provideMasterKey.toLowerCase() === 'y') {
      masterKey = await question('Enter MASTER_KEY (hex format): ');
    } else {
      // Generate new master key
      masterKey = crypto.randomBytes(32).toString('hex');
      console.log(`\n✓ Generated new MASTER_KEY:\n${masterKey}\n`);
      console.log('Save this in your .env file as: MASTER_KEY=' + masterKey);
    }

    // Verify key format
    if (masterKey.length !== 64) {
      console.error('✗ MASTER_KEY must be 64 characters (32 bytes in hex)');
      process.exit(1);
    }
  }

  // Collect secrets
  console.log('\nEnter your secrets:\n');

  const jwtSecret = await question('JWT_SECRET (min 32 chars): ');
  if (jwtSecret.length < 32) {
    console.error('✗ JWT_SECRET must be at least 32 characters');
    process.exit(1);
  }

  const databaseUrl = await question('DATABASE_URL (e.g., postgresql://user:pass@localhost/db): ');
  if (!databaseUrl.startsWith('postgresql://')) {
    console.warn('⚠ DATABASE_URL should use PostgreSQL');
  }

  const allowedOrigins = await question('ALLOWED_ORIGINS (comma-separated): ');

  const secrets = {
    JWT_SECRET: jwtSecret,
    DATABASE_URL: databaseUrl,
    ALLOWED_ORIGINS: allowedOrigins,
    CREATED_AT: new Date().toISOString(),
    ENVIRONMENT: 'development'
  };

  // Save secrets
  const secretsPath = path.join(process.cwd(), '.secrets');

  try {
    let content;
    if (useEncryption) {
      // Encrypt secrets
      const iv = crypto.randomBytes(16);
      const cipher = crypto.createCipheriv(
        'aes-256-cbc',
        Buffer.from(masterKey, 'hex'),
        iv
      );

      let encrypted = cipher.update(JSON.stringify(secrets, null, 2), 'utf8', 'hex');
      encrypted += cipher.final('hex');
      content = `${iv.toString('hex')}:${encrypted}`;
    } else {
      // Plain JSON (development only)
      content = JSON.stringify(secrets, null, 2);
    }

    fs.writeFileSync(secretsPath, content);
    console.log(`\n✓ Secrets saved to: ${secretsPath}`);

    if (useEncryption) {
      console.log('✓ Secrets are encrypted');
    } else {
      console.log('⚠ Secrets are NOT encrypted (development only)');
    }

    console.log('\nNext steps:');
    console.log('1. Add to .gitignore: .secrets');
    if (useEncryption) {
      console.log('2. Add to .env: MASTER_KEY=' + masterKey);
      console.log('3. Keep MASTER_KEY secure, do not commit to git');
    }
    console.log('4. Test loading: npm start\n');

  } catch (error) {
    console.error('✗ Failed to save secrets:', error.message);
    process.exit(1);
  }

  rl.close();
}

main().catch(error => {
  console.error('✗ Setup failed:', error);
  process.exit(1);
});

// IMPROVED app.js WITH SECURE SECRETS LOADING
// Uses SecretsLoader for abstracted secrets management

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const cors = require('cors');
const SecretsLoader = require('./SecretsLoader');

const app = express();

// Global secrets instance
let secrets = null;

// ============================================================================
// SECRETS INITIALIZATION
// ============================================================================

// Initialize secrets loader with options
const secretsLoader = new SecretsLoader({
  useLocalFallback: true,      // Allow .secrets file for development
  cacheTTL: 3600000,           // Cache for 1 hour
});

// Initialize secrets on startup
async function initializeApp() {
  try {
    console.log('Initializing application...');

    // Load secrets
    secrets = await secretsLoader.loadSecrets();
    console.log('✓ Secrets loaded successfully');

    // Validate environment
    if (process.env.NODE_ENV === 'production') {
      if (!process.env.AWS_SECRET_NAME) {
        console.error('✗ AWS_SECRET_NAME not set in production');
        process.exit(1);
      }
      console.log('✓ Production mode with AWS Secrets Manager');
    } else {
      console.log('✓ Development mode');
    }

    return true;
  } catch (error) {
    console.error('✗ Failed to initialize app:', error.message);
    process.exit(1);
  }
}

// ============================================================================
// MIDDLEWARE
// ============================================================================

// Must initialize secrets before using them
app.use(async (req, res, next) => {
  if (!secrets) {
    try {
      secrets = await secretsLoader.loadSecrets();
    } catch (error) {
      return res.status(500).json({ error: 'Failed to load configuration' });
    }
  }
  next();
});

app.use(helmet());

// CORS using secrets
app.use(cors({
  origin: secrets?.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ============================================================================
// AUTHENTICATION
// ============================================================================

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No authentication token provided' });
  }

  try {
    // Use JWT_SECRET from secrets manager
    const decoded = require('jsonwebtoken').verify(
      token,
      secrets.JWT_SECRET  // NOW LOADED FROM SECRETS MANAGER!
    );
    req.user = decoded;
    next();
  } catch (err) {
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
};

// ============================================================================
// INPUT VALIDATION
// ============================================================================

const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Invalid input',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// ============================================================================
// ROUTES
// ============================================================================

app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    version: '1.0.0',
    environment: process.env.NODE_ENV
  });
});

app.get('/users',
  authenticateToken,
  [
    query('page')
      .optional()
      .isInt({ min: 1, max: 1000 })
      .withMessage('Page must be between 1 and 1000'),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('sort')
      .optional()
      .isIn(['id', 'name', 'email'])
      .withMessage('Invalid sort field')
  ],
  handleValidationErrors,
  (req, res) => {
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const safeUsers = users.map(user => ({
      id: user.id,
      name: user.name,
      email: user.email
    }));

    res.json({
      data: safeUsers.slice((page - 1) * limit, page * limit),
      pagination: {
        page,
        limit,
        total: safeUsers.length
      }
    });
  }
);

app.post('/users',
  authenticateToken,
  [
    body('name')
      .trim()
      .notEmpty().withMessage('Name is required')
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters'),
    body('email')
      .trim()
      .isEmail().withMessage('Invalid email format')
      .normalizeEmail(),
  ],
  handleValidationErrors,
  (req, res) => {
    const newUser = {
      id: Math.random(),
      name: req.body.name,
      email: req.body.email
    };

    res.status(201).json({
      message: 'User created successfully',
      data: newUser
    });
  }
);

// ============================================================================
// ERROR HANDLING
// ============================================================================

app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path
  });
});

app.use((err, req, res, next) => {
  console.error('Error:', err.message);

  const isDevelopment = process.env.NODE_ENV === 'development';
  const errorResponse = {
    error: 'Internal server error',
    ...(isDevelopment && { message: err.message })
  };

  res.status(err.status || 500).json(errorResponse);
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

if (require.main === module) {
  // Initialize and start
  initializeApp().then(() => {
    app.listen(PORT, () => {
      console.log(`\n✓ Server running on port ${PORT} in ${NODE_ENV} mode`);
      console.log(`✓ Secrets loaded from: ${process.env.NODE_ENV === 'production' ? 'AWS Secrets Manager' : 'Local/Environment'}`);
      console.log('\n');
    });
  });
}

module.exports = app;

