/**
 * Secure Express.js Application
 * Implements OWASP Top 10 protections and security best practices
 */

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const winston = require('winston');

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============================================================================
// LOGGING SETUP (OWASP A09:2021 - Logging & Monitoring)
// ============================================================================

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json(),
  ),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Security Headers (OWASP A05:2021 - Misconfiguration)
app.use(helmet());
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    scriptSrc: ["'self'"],
    imgSrc: ["'self'", "data:", "https:"],
    connectSrc: ["'self'"],
  },
}));

// 2. HTTPS Enforcement (OWASP A02:2021 - Cryptographic Failures)
if (NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      return res.redirect(301, `https://${req.header('host')}${req.url}`);
    }
    next();
  });
}

// 3. CORS Configuration (OWASP A04:2021 - Broken Access Control)
const corsOptions = {
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
  optionsSuccessStatus: 200,
};
app.use(cors(corsOptions));

// 4. Rate Limiting (OWASP A07:2021 - Broken Authentication)
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => NODE_ENV === 'development', // Skip rate limiting in dev
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // max 5 attempts per IP
  skipSuccessfulRequests: true,
  message: 'Too many login attempts, please try again later.',
});

app.use(generalLimiter);

// 5. Body Parser with Size Limits (OWASP A03:2021 - Injection)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// ============================================================================
// REQUEST LOGGING MIDDLEWARE
// ============================================================================

app.use((req, res, next) => {
  logger.info({
    method: req.method,
    path: req.path,
    ip: req.ip,
    timestamp: new Date().toISOString(),
    userAgent: req.get('user-agent'),
  });
  next();
});

// ============================================================================
// AUTHENTICATION MIDDLEWARE (OWASP A07:2021 - Broken Authentication)
// ============================================================================

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    logger.warn({
      event: 'missing_auth_token',
      path: req.path,
      ip: req.ip,
      timestamp: new Date().toISOString(),
    });
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET || 'dev-secret', (err, user) => {
    if (err) {
      logger.warn({
        event: 'invalid_token',
        error: err.message,
        ip: req.ip,
        timestamp: new Date().toISOString(),
      });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// ============================================================================
// PUBLIC ENDPOINTS
// ============================================================================

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
  });
});

// ============================================================================
// PROTECTED ENDPOINTS
// ============================================================================

/**
 * Get list of users (minimal data exposure)
 * Query parameters: limit (1-100)
 */
app.get('/users',
  authenticateToken,
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Return minimal user data (OWASP A01:2021 - Data Protection)
    // Email is excluded to prevent PII exposure
    const users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];

    res.json(users);
  }
);

/**
 * Get current user's own data (with email)
 * Only accessible to authenticated users viewing their own data
 */
app.get('/users/me', authenticateToken, (req, res) => {
  // In production, fetch from database with proper authorization
  const user = {
    id: req.user.id,
    name: req.user.name,
    email: req.user.email,
  };

  res.json(user);
});

/**
 * Get specific user by ID (with authorization check)
 */
app.get('/users/:id',
  authenticateToken,
  query('fields')
    .optional()
    .isIn(['name', 'email', 'id'])
    .withMessage('Invalid field requested'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const userId = parseInt(req.params.id, 10);
    if (isNaN(userId)) {
      return res.status(400).json({ error: 'Invalid user ID' });
    }

    // Authorization check: users can only access their own data or if they're admin
    if (req.user.id !== userId && req.user.role !== 'admin') {
      logger.warn({
        event: 'unauthorized_access_attempt',
        attemptedUserId: userId,
        actualUserId: req.user.id,
        ip: req.ip,
        timestamp: new Date().toISOString(),
      });
      return res.status(403).json({ error: 'Unauthorized' });
    }

    // Return appropriate data based on access level
    const user = {
      id: userId,
      name: 'User Name',
      email: req.user.id === userId ? 'user@example.com' : undefined,
    };

    res.json(user);
  }
);

// ============================================================================
// LOGIN ENDPOINT (Example - for demo purposes)
// ============================================================================

app.post('/login',
  authLimiter, // Stricter rate limiting for auth
  express.json(),
  (req, res) => {
    // NOTE: This is a simplified example. In production:
    // 1. Validate credentials against database
    // 2. Use bcrypt for password hashing verification
    // 3. Implement MFA if required
    // 4. Log all authentication attempts

    const { email, password } = req.body;

    if (!email || !password) {
      return res.status(400).json({ error: 'Email and password required' });
    }

    // Validate email format
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      return res.status(400).json({ error: 'Invalid email format' });
    }

    // TODO: Verify credentials securely
    // This is placeholder logic
    if (password.length < 8) {
      logger.warn({
        event: 'login_failed',
        reason: 'weak_password',
        email,
        ip: req.ip,
        timestamp: new Date().toISOString(),
      });
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    // Generate JWT token
    const user = { id: 1, name: 'Alice', email, role: 'user' };
    const token = jwt.sign(user, process.env.JWT_SECRET || 'dev-secret', {
      expiresIn: '1h',
    });

    logger.info({
      event: 'login_successful',
      email,
      ip: req.ip,
      timestamp: new Date().toISOString(),
    });

    res.json({ token, expiresIn: '1h' });
  }
);

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

// Handle 404 (must be before error handler)
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  // Log error securely (without sensitive data in production)
  logger.error({
    message: err.message,
    status: err.status || 500,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    ip: req.ip,
    // Only include stack trace in development
    stack: NODE_ENV === 'development' ? err.stack : undefined,
  });

  // Build error response
  const isDevelopment = NODE_ENV === 'development';
  const errorResponse = {
    error: isDevelopment ? err.message : 'Internal Server Error',
    status: err.status || 500,
  };

  // Only expose stack trace in development
  if (isDevelopment) {
    errorResponse.stack = err.stack;
  }

  res.status(err.status || 500).json(errorResponse);
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const server = app.listen(PORT, () => {
  logger.info({
    event: 'server_started',
    port: PORT,
    environment: NODE_ENV,
    timestamp: new Date().toISOString(),
  });
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info({
    event: 'server_shutdown',
    timestamp: new Date().toISOString(),
  });
  server.close(() => {
    console.log('Server terminated');
  });
});

module.exports = app;

