### Step 3: Update package.json Scripts

```json
{
  "scripts": {
    "start": "node app-secure.js",
    "dev": "NODE_ENV=development nodemon app-secure.js",
    "security-check": "npm audit && eslint . --plugin security"
  }
}
```

### Step 4: Migrate Endpoints

**Before (Insecure):**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**After (Secure):**
```javascript
app.get('/users',
  authenticateToken,  // Require authentication
  query('limit')      // Validate input
    .optional()
    .isInt({ min: 1, max: 100 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Return minimal data
    res.json([
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ]);
  }
);
```

### Step 5: Implement Authentication

```javascript
const jwt = require('jsonwebtoken');

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user;
    next();
  });
};

app.use(helmet());
app.use(express.json({ limit: '10kb' }));
app.use(cors(corsOptions));
```

### Step 6: Implement Rate Limiting

```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests',
});

app.use(limiter);
```

### Step 7: Add Input Validation

```javascript
const { query, body, validationResult } = require('express-validator');

app.post('/login',
  body('email').isEmail().normalizeEmail(),
  body('password').isLength({ min: 8 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Process login
  }
);
```

### Step 8: Add Error Handling

```javascript
app.use((err, req, res, next) => {
  logger.error(err);

  if (process.env.NODE_ENV === 'development') {
    return res.status(500).json({ error: err.message, stack: err.stack });
  }

  res.status(500).json({ error: 'Internal Server Error' });
});
```

### Step 9: Add Logging

```javascript
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

app.use((req, res, next) => {
  logger.info({
    method: req.method,
    path: req.path,
    ip: req.ip,
  });
  next();
});
```

