# Security Fixes - Quick Reference

## Copy-Paste Solutions for Common Issues

### 1. Add Authentication Middleware

```javascript
const jwt = require('jsonwebtoken');

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// Use on protected routes
app.get('/users', authenticateToken, (req, res) => {
  // Only authenticated users reach here
  res.json(users);
});
```

### 2. Add Security Headers (Helmet)

```javascript
const helmet = require('helmet');

app.use(helmet());

// Optional: Customize CSP
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
  },
}));
```

### 3. Add Input Validation

```javascript
const { query, body, param, validationResult } = require('express-validator');

app.get('/users/:id',
  param('id').isInt().toInt(),
  query('fields').optional().isIn(['name', 'email']),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Safe to use req.params.id and req.query.fields
  }
);
```

### 4. Add Rate Limiting

```javascript
const rateLimit = require('express-rate-limit');

// General limiter
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
});

// Auth limiter (stricter)
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
});

app.use(limiter);
app.post('/login', authLimiter, (req, res) => {
  // Login logic
});
```

### 5. Add CORS Configuration

```javascript
const cors = require('cors');

const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
};

app.use(cors(corsOptions));
```

### 6. Add Body Parser Limits

```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));
```

### 7. Add Error Handling

```javascript
// Global error handler (must be last middleware)
app.use((err, req, res, next) => {
  console.error(err);

  const isDev = process.env.NODE_ENV === 'development';
  const response = {
    error: isDev ? err.message : 'Internal Server Error',
    status: err.status || 500,
  };

  if (isDev) response.stack = err.stack;

  res.status(response.status).json(response);
});
```

### 8. Add Environment Variables

```javascript
require('dotenv').config();

const PORT = process.env.PORT || 3000;
const JWT_SECRET = process.env.JWT_SECRET;
const NODE_ENV = process.env.NODE_ENV || 'development';

if (!JWT_SECRET) {
  throw new Error('JWT_SECRET not set in environment');
}
```

### 9. Add Logging

```javascript
const winston = require('winston');

const logger = winston.createLogger({
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'app.log' }),
  ],
});

app.use((req, res, next) => {
  logger.info({ method: req.method, path: req.path, ip: req.ip });
  next();
});
```

### 10. Add HTTPS Enforcement

```javascript
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(`https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  });
}
```

