  res.json({
    id: req.user.id,
    name: req.user.name,
    email: req.user.email  // ✓ Only their own email
  });
});
```

### Scenario 9: Unvalidated Redirect

**Attack:** Redirect to malicious site

**Prevention:**
```javascript
const ALLOWED_REDIRECT_HOSTS = ['example.com', 'app.example.com'];

app.get('/redirect', (req, res) => {
  const { url } = req.query;

  // Validate against whitelist
  const parsed = new URL(url);
  if (!ALLOWED_REDIRECT_HOSTS.includes(parsed.hostname)) {
    return res.status(400).json({ error: 'Invalid redirect URL' });
  }

  res.redirect(url);
});
```

### Scenario 10: Insecure Deserialization

**Attack:** Exploit JSON deserialization

**Prevention:**
```javascript
