// Secured version of the application with security best practices implemented
// Addresses OWASP Top 10 vulnerabilities and common security issues

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const hpp = require('hpp');
const cors = require('cors');
const validator = require('validator');
const compression = require('compression');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE - Best Practices Implementation
// ============================================================================

// 1. HELMET: Sets various HTTP headers for security
// Prevents XSS, clickjacking, MIME-sniffing, etc.
app.use(helmet());

// 2. COMPRESSION: Reduces response payload size
app.use(compression());

// 3. CORS: Control who can access your API
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization']
};
app.use(cors(corsOptions));

// 4. BODY PARSER LIMITS: Prevent payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 5. DATA SANITIZATION: Prevent NoSQL injection
app.use(mongoSanitize());

// 6. XSS PROTECTION: Sanitize user input
app.use(xss());

// 7. HPP (HTTP Parameter Pollution): Protect against parameter pollution
app.use(hpp({
  whitelist: ['sort', 'fields', 'page', 'limit'] // Allow certain params
}));

// 8. RATE LIMITING: Prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// Strict rate limit for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many login attempts, please try again later.',
  skipSuccessfulRequests: true,
});

// ============================================================================
// SECURITY: Logging and Monitoring
// ============================================================================

// Simple logging middleware (use Morgan in production)
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// ============================================================================
// SECURITY: Health Check Endpoint
// ============================================================================

app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ status: 'error' });
  }
});

// ============================================================================
// SECURITY: Input Validation Helper Function
// ============================================================================

const validateUserInput = (id) => {
  // Validate that id is a positive integer
  if (!validator.isInt(String(id), { min: 1 })) {
    return { valid: false, error: 'Invalid user ID format' };
  }
  return { valid: true };
};

// ============================================================================
// SECURITY: Users Endpoint with Proper Implementation
// ============================================================================

// Mock database - In production, use proper database with parameterized queries
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// GET all users - with pagination to prevent data exposure
app.get('/api/users', (req, res) => {
  try {
    // Input validation for query parameters
    const page = validator.isInt(req.query.page || '1', { min: 1 }) ? 
                 parseInt(req.query.page) : 1;
    const limit = validator.isInt(req.query.limit || '10', { min: 1, max: 100 }) ? 
                  parseInt(req.query.limit) : 10;

    if (limit > 100) {
      return res.status(400).json({ 
        error: 'Limit cannot exceed 100' 
      });
    }

    // Pagination implementation
    const start = (page - 1) * limit;
    const paginatedUsers = users.slice(start, start + limit);

    // Don't expose sensitive information
    const sanitizedUsers = paginatedUsers.map(user => ({
      id: user.id,
      name: user.name,
      // email: user.email // Consider if this should be exposed
    }));

    res.status(200).json({
      success: true,
      count: sanitizedUsers.length,
      total: users.length,
      page: page,
      data: sanitizedUsers
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ 
      error: 'Internal server error. Please try again later.' 
    });
  }
});

// GET single user by ID - with input validation
app.get('/api/users/:id', (req, res) => {
  try {
    // INPUT VALIDATION: Prevent injection attacks
    const validation = validateUserInput(req.params.id);
    if (!validation.valid) {
      return res.status(400).json({ 
        error: validation.error 
      });
    }

    const userId = parseInt(req.params.id);
    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({ 
        error: 'User not found' 
      });
    }

    // Sanitize response - don't expose all data
    res.status(200).json({
      success: true,
      data: {
        id: user.id,
        name: user.name
      }
    });
  } catch (error) {
    console.error('Error fetching user:', error);
    res.status(500).json({ 
      error: 'Internal server error. Please try again later.' 
    });
  }
});

// ============================================================================
// SECURITY: Error Handling Middleware
// ============================================================================

app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Don't expose error details to client in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack })
  });
});

// ============================================================================
// SECURITY: 404 Handler
// ============================================================================

app.use((req, res) => {
  res.status(404).json({
    error: 'Endpoint not found',
    path: req.path
  });
});

// ============================================================================
// SECURITY: Environment Configuration
// ============================================================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Only listen if not being imported as a module
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
  });
}

module.exports = app;

