// Example implementation with authentication
// This shows how to add JWT-based authentication to secure your endpoints

const express = require('express');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');
const router = express.Router();

// ============================================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================================

/**
 * Verify JWT token
 * SECURITY: Always verify tokens before processing requests
 */
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ 
      error: 'Access token required',
      code: 'NO_TOKEN'
    });
  }

  jwt.verify(token, process.env.ACCESS_TOKEN_SECRET, (err, user) => {
    if (err) {
      console.error('Token verification failed:', err.message);
      return res.status(403).json({ 
        error: 'Invalid or expired token',
        code: 'INVALID_TOKEN'
      });
    }

    req.user = user;
    next();
  });
};

/**
 * Authorization middleware - Check user role
 * SECURITY: Implement role-based access control
 */
const authorize = (requiredRoles = []) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Unauthorized' });
    }

    if (requiredRoles.length > 0 && !requiredRoles.includes(req.user.role)) {
      return res.status(403).json({ 
        error: 'Forbidden - Insufficient permissions',
        requiredRoles: requiredRoles,
        userRole: req.user.role
      });
    }

    next();
  };
};

// ============================================================================
// LOGIN ENDPOINT - SECURE AUTHENTICATION
// ============================================================================

/**
 * Login endpoint
 * SECURITY: Use HTTPS, rate limiting, secure password hashing
 */
router.post('/login', async (req, res) => {
  try {
    const { email, password } = req.body;

    // Input validation
    if (!email || !password) {
      return res.status(400).json({ 
        error: 'Email and password required' 
      });
    }

    // Find user (example - use real database)
    const user = findUserByEmail(email); // Simulated function

    if (!user) {
      // SECURITY: Don't reveal if user exists
      return res.status(401).json({ 
        error: 'Invalid credentials' 
      });
    }

    // Verify password using bcrypt
    // SECURITY: NEVER store plaintext passwords
    const validPassword = await bcrypt.compare(password, user.passwordHash);

    if (!validPassword) {
      return res.status(401).json({ 
        error: 'Invalid credentials' 
      });
    }

    // Generate tokens
    const accessToken = jwt.sign(
      { 
        id: user.id, 
        email: user.email,
        role: user.role 
      },
      process.env.ACCESS_TOKEN_SECRET,
      { expiresIn: '15m' } // Short expiration
    );

    const refreshToken = jwt.sign(
      { id: user.id },
      process.env.REFRESH_TOKEN_SECRET,
      { expiresIn: '7d' }
    );

    // Store refresh token in secure httpOnly cookie
    res.cookie('refreshToken', refreshToken, {
      httpOnly: true,      // Prevent JS access (XSS protection)
      secure: true,        // HTTPS only
      sameSite: 'strict',  // CSRF protection
      maxAge: 7 * 24 * 60 * 60 * 1000 // 7 days
    });

    res.status(200).json({
      success: true,
      accessToken: accessToken,
      user: {
        id: user.id,
        email: user.email,
        name: user.name
      }
    });

  } catch (error) {
    console.error('Login error:', error);
    res.status(500).json({ 
      error: 'Internal server error' 
    });
  }
});

// ============================================================================
// TOKEN REFRESH ENDPOINT
// ============================================================================

/**
 * Refresh access token
 * SECURITY: Implement token rotation for better security
 */
router.post('/refresh-token', (req, res) => {
  try {
    const refreshToken = req.cookies.refreshToken;

    if (!refreshToken) {
      return res.status(401).json({ 
        error: 'Refresh token required' 
      });
    }

    jwt.verify(refreshToken, process.env.REFRESH_TOKEN_SECRET, (err, user) => {
      if (err) {
        return res.status(403).json({ 
          error: 'Invalid refresh token' 
        });
      }

      // Generate new access token
      const newAccessToken = jwt.sign(
        { id: user.id, role: user.role },
        process.env.ACCESS_TOKEN_SECRET,
        { expiresIn: '15m' }
      );

      res.json({ accessToken: newAccessToken });
    });

  } catch (error) {
    console.error('Token refresh error:', error);
    res.status(500).json({ 
      error: 'Internal server error' 
    });
  }
});

// ============================================================================
// REGISTER ENDPOINT - SECURE USER CREATION
// ============================================================================

/**
 * User registration
 * SECURITY: Validate input, hash passwords, check for duplicates
 */
router.post('/register', async (req, res) => {
  try {
    const { email, password, name } = req.body;

    // Input validation
    const validator = require('validator');
    if (!validator.isEmail(email)) {
      return res.status(400).json({ 
        error: 'Invalid email format' 
      });
    }

    if (password.length < 8) {
      return res.status(400).json({ 
        error: 'Password must be at least 8 characters' 
      });
    }

    if (!validator.isLength(name, { min: 1, max: 100 })) {
      return res.status(400).json({ 
        error: 'Name must be between 1 and 100 characters' 
      });
    }

    // Check if user exists
    if (findUserByEmail(email)) {
      return res.status(409).json({ 
        error: 'Email already registered' 
      });
    }

    // Hash password
    // SECURITY: Use bcrypt with salt rounds >= 10
    const passwordHash = await bcrypt.hash(password, 12);

    // Create user
    const newUser = {
      id: generateUserId(),
      email: email.toLowerCase(),
      passwordHash: passwordHash,
      name: name.trim(),
      role: 'user',
      createdAt: new Date()
    };

    // Save to database
    saveUser(newUser); // Simulated function

    res.status(201).json({
      success: true,
      message: 'User registered successfully',
      user: {
        id: newUser.id,
        email: newUser.email,
        name: newUser.name
      }
    });

  } catch (error) {
    console.error('Registration error:', error);
    res.status(500).json({ 
      error: 'Internal server error' 
    });
  }
});

