      expect(response.headers['content-security-policy']).toBeDefined();
    });

    test('Should include X-Frame-Options header (clickjacking protection)', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['x-frame-options']).toBe('DENY');
    });

    test('Should include X-Content-Type-Options header (MIME-sniffing prevention)', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['x-content-type-options']).toBe('nosniff');
    });

    test('Should include Strict-Transport-Security header (HSTS)', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['strict-transport-security']).toBeDefined();
    });
  });

  // ============================================================================
  // INPUT VALIDATION TESTS
  // ============================================================================

  describe('Input Validation', () => {
    test('Should reject invalid user ID (non-numeric)', async () => {
      const response = await request(app)
        .get('/api/users/invalid_id');
      expect(response.status).toBe(400);
      expect(response.body.error).toBeDefined();
    });

    test('Should reject negative user ID', async () => {
      const response = await request(app)
        .get('/api/users/-1');
      expect(response.status).toBe(400);
    });

    test('Should reject SQL injection attempt in query', async () => {
      const response = await request(app)
        .get('/api/users')
        .query({ id: "1' OR '1'='1" });
      expect(response.status).toBe(400);
    });

    test('Should reject NoSQL injection attempt', async () => {
      const response = await request(app)
        .get('/api/users')
        .query({ page: JSON.stringify({ $ne: null }) });
      expect(response.status).toBe(400);
    });

    test('Should reject limit parameter > 100', async () => {
      const response = await request(app)
        .get('/api/users')
        .query({ limit: 1000 });
      expect(response.status).toBe(400);
      expect(response.body.error).toContain('cannot exceed 100');
    });
  });

  // ============================================================================
  // RATE LIMITING TESTS
  // ============================================================================

  describe('Rate Limiting', () => {
    test('Should allow requests within rate limit', async () => {
      const response = await request(app).get('/api/users');
      expect(response.status).toBeLessThan(429);
    });

    test('Should return 429 after exceeding rate limit', async () => {
      // Make multiple requests rapidly
      for (let i = 0; i < 101; i++) {
        await request(app).get('/api/users');
      }

      const response = await request(app).get('/api/users');
      expect(response.status).toBe(429);
    });
  });

  // ============================================================================
