        expect(user.password).toBeUndefined();
      }
    });
  });

  // ============================================================================
  // INJECTION TESTS - SQL/NoSQL
  // ============================================================================

  describe('Injection Prevention', () => {
    test('Should handle SQL injection in user ID', async () => {
      const sqlInjection = "1; DROP TABLE users; --";
      const response = await request(app)
        .get(`/api/users/${sqlInjection}`);

      expect(response.status).toBe(400);
    });

    test('Should handle NoSQL injection patterns', async () => {
      const payload = JSON.stringify({ $ne: null });
      const response = await request(app)
        .get('/api/users')
        .query({ id: payload });

      expect(response.status).toBe(400);
    });

