**Implementation:**

```javascript
// secrets-manager.js
const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager({ region: process.env.AWS_REGION });

class SecretsManager {
  constructor() {
    this.cache = {};
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    // Check cache first
    if (this.cache[secretName] && Date.now() - this.cache[secretName].timestamp < this.cacheTTL) {
      return this.cache[secretName].value;
    }

    try {
      const data = await secretsManager.getSecretValue({ SecretId: secretName }).promise();

      let secret;
      if ('SecretString' in data) {
        secret = JSON.parse(data.SecretString);
      } else {
        secret = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.cache[secretName] = {
        value: secret,
        timestamp: Date.now()
      };

      return secret;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  // Clear cache on demand
  clearCache(secretName) {
    if (secretName) {
      delete this.cache[secretName];
    } else {
      this.cache = {};
    }
  }
}

module.exports = new SecretsManager();
```

