      console.error('AppRole authentication with Vault failed:', error.message);
      throw error;
    }
  }

  /**
   * Ensure we have a valid token
   */
  async ensureAuthenticated() {
    if (!this.token) {
      // Try JWT first, fall back to AppRole
      try {
        await this.authenticateWithJWT();
      } catch {
        await this.authenticateWithAppRole();
      }
    }
  }

  /**
   * Load secrets from Vault
   */
  async loadSecrets() {
    const now = Date.now();

    // Return cached secrets if still valid
    if (
      this.cachedSecrets &&
      now - this.lastUpdated < this.cacheDuration
    ) {
      return this.cachedSecrets;
    }

    try {
      await this.ensureAuthenticated();

      const response = await axios.get(
        `${this.vaultUrl}/v1/${this.secretPath}`,
        {
          headers: {
            'X-Vault-Token': this.token,
          },
        }
      );

      this.cachedSecrets = response.data.data.data;
      this.lastUpdated = now;

      return this.cachedSecrets;
    } catch (error) {
      console.error('Failed to load secrets from Vault:', error.message);
      throw new Error('Unable to load application secrets');
    }
  }

  /**
   * Get a specific secret
   */
  async get(key, defaultValue = undefined) {
    const secrets = await this.loadSecrets();
    return secrets[key] || defaultValue;
  }

  /**
   * Validate required secrets
   */
  async validateRequired(requiredSecrets) {
    const secrets = await this.loadSecrets();
    const missing = requiredSecrets.filter(key => !(key in secrets));

    if (missing.length > 0) {
      throw new Error(`Missing required secrets in Vault: ${missing.join(', ')}`);
    }
  }

  /**
   * Renew Vault token
   */
  async renewToken() {
    try {
      await axios.post(
        `${this.vaultUrl}/v1/auth/token/renew-self`,
        {},
        {
          headers: {
            'X-Vault-Token': this.token,
          },
        }
      );
    } catch (error) {
      console.error('Failed to renew Vault token:', error.message);
      this.token = null; // Force re-authentication
      await this.ensureAuthenticated();
    }
  }

  /**
   * Clear cached secrets
   */
  clearCache() {
    this.cachedSecrets = null;
    this.lastUpdated = null;
  }
}

