/**
 * Secure Application Example using AWS Secrets Manager
 * Best practices for secrets management
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const secretsManager = require('./secure_config'); // AWS Secrets Manager

const app = express();

// Initialize application with secrets
let config = {};

/**
 * Initialize application - validate and load secrets
 */
async function initializeApp() {
  try {
    // Validate required secrets are available
    const requiredSecrets = [
      'DATABASE_URL',
      'JWT_SECRET',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
    ];

    await secretsManager.validateRequired(requiredSecrets);

    // Load all secrets
    config = await secretsManager.loadSecrets();

    console.log('✓ Application secrets loaded successfully');
  } catch (error) {
    console.error('✗ Failed to initialize application:', error.message);
    process.exit(1);
  }
}

/**
 * Middleware to ensure secrets are loaded
 */
function ensureSecretsLoaded(req, res, next) {
  if (!config || Object.keys(config).length === 0) {
    return res.status(500).json({
      error: 'Application is not properly configured',
    });
  }
  next();
}

/**
 * Health check endpoint - NO sensitive data
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
  });
});

/**
 * Protected endpoint using secrets
 */
app.get('/protected', ensureSecretsLoaded, (req, res) => {
  // Example: Use JWT_SECRET from secrets manager
  const jwtSecret = config.JWT_SECRET; // Safe - only used in-memory

  res.json({
    message: 'This endpoint requires valid JWT token',
    // Never expose secrets in response
  });
});

/**
 * Database connection example
 */
async function initializeDatabase() {
  const databaseUrl = await secretsManager.get('DATABASE_URL');

  // Connect to database
  console.log('Connecting to database...');
  // db.connect(databaseUrl);
}

/**
 * Start the application
 */
async function start() {
  try {
    // Apply security middleware
    app.use(helmet());

    // Rate limiting
    const limiter = rateLimit({
      windowMs: 15 * 60 * 1000,
      max: 100,
    });
    app.use(limiter);

    // Initialize secrets
    await initializeApp();

    // Initialize database with secrets
    await initializeDatabase();

    // Start server
    const PORT = process.env.PORT || 3000;
    app.listen(PORT, () => {
      console.log(`Server running on port ${PORT}`);
    });
  } catch (error) {
    console.error('Failed to start application:', error.message);
    process.exit(1);
  }
}

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully...');
  process.exit(0);
});

// Start the app
if (require.main === module) {
  start();
}

module.exports = app;
