cat > SECRETS_TOOLS_COMPARISON.md << 'EOF'
# SECRETS MANAGEMENT TOOLS COMPARISON

## Overview

| Feature | AWS Secrets Manager | HashiCorp Vault | Azure Key Vault | GCP Secret Manager |
|---------|-------------------|-----------------|-----------------|-------------------|
| **Pricing** | Pay-per-secret | Self-hosted free / Cloud paid | Pay-per-operation | Pay-per-secret |
| **Ease of Use** | ⭐⭐⭐⭐ Easy | ⭐⭐⭐ Moderate | ⭐⭐⭐⭐ Easy | ⭐⭐⭐⭐ Easy |
| **Audit Logging** | ✅ Via CloudTrail | ✅ Built-in | ✅ Built-in | ✅ Built-in |
| **Rotation** | ✅ Automatic | ✅ Automatic | ✅ Automatic | ❌ Manual |
| **On-Premises** | ❌ No | ✅ Yes | ❌ No | ❌ No |
| **Multi-Cloud** | Limited | ✅ Yes | Limited | Limited |
| **Access Control** | ✅ IAM | ✅ RBAC | ✅ RBAC | ✅ IAM |
| **Secret Types** | Strings, DB, API Keys | All types | All types | Strings |
| **Encryption** | ✅ At-rest & transit | ✅ At-rest & transit | ✅ At-rest & transit | ✅ At-rest & transit |

---

## AWS Secrets Manager

### Best For
- AWS-native applications
- Organizations already using AWS
- Need tight integration with AWS services

### Pros
- ✅ Native AWS integration
- ✅ Automatic database credential rotation
- ✅ CloudTrail audit logging
- ✅ Cross-account access
- ✅ Cost-effective (under $1/month per secret)

### Cons
- ❌ AWS-only
- ❌ No on-premises support
- ❌ Limited to AWS services

### Code Example

```javascript
const AWS = require('aws-sdk');
const client = new AWS.SecretsManager();

async function getSecret(secretName) {
  try {
    const data = await client.getSecretValue({
      SecretId: secretName
    }).promise();
    return JSON.parse(data.SecretString);
  } catch (error) {
    console.error('Failed to retrieve secret:', error);
    throw error;
  }
}

// Usage
const secret = await getSecret('app/production/secrets');
const dbPassword = secret.DATABASE_PASSWORD;
```

### Cost Estimate
- Per secret: $0.40/month
- API requests: $0.05 per 10,000
- Example: 100 secrets + 100k requests/month = $40-50/month

---

## HashiCorp Vault

### Best For
- Multi-cloud or on-premises deployments
- Complex access control requirements
- Organizations needing maximum flexibility

### Pros
- ✅ Multi-cloud support
- ✅ On-premises deployment option
- ✅ Powerful RBAC
- ✅ Secret rotation automation
- ✅ Open-source version available
- ✅ Policy-as-code
- ✅ Encryption as a Service

### Cons
- ❌ Steeper learning curve
- ❌ Self-hosted requires maintenance
- ❌ More operational overhead

### Code Example

```javascript
const axios = require('axios');

class VaultClient {
  constructor(token, vaultUrl) {
    this.token = token;
    this.vaultUrl = vaultUrl;
  }

  async getSecret(path) {
    try {
      const response = await axios.get(
        `${this.vaultUrl}/v1/${path}`,
        {
          headers: {
            'X-Vault-Token': this.token
          }
        }
      );
      return response.data.data.data;
    } catch (error) {
      console.error('Failed to retrieve secret:', error);
      throw error;
    }
  }

  async updateSecret(path, data) {
    return await axios.post(
      `${this.vaultUrl}/v1/${path}`,
      { data },
      {
        headers: {
          'X-Vault-Token': this.token
        }
      }
    );
  }
}

// Usage
const vault = new VaultClient(process.env.VAULT_TOKEN, process.env.VAULT_URL);
const secret = await vault.getSecret('secret/data/app');
```

### Cost Estimate
- Open-source: Free (self-hosted)
- Vault Cloud: $0.50-1.50 per 1M requests
- On-premises: Infrastructure costs

---

## Azure Key Vault

### Best For
- Azure-native applications
- Organizations using Microsoft stack
- Compliance with Azure-specific requirements

### Pros
- ✅ Native Azure integration
- ✅ FIPS 140-2 compliant
- ✅ Managed HSM available
- ✅ Role-based access control
- ✅ Integration with CI/CD pipelines

### Cons
- ❌ Azure-only
- ❌ Limited secret types
- ❌ No automatic rotation for all types

### Code Example

```javascript
const { SecretClient } = require("@azure/keyvault-secrets");
const { DefaultAzureCredential } = require("@azure/identity");

const credential = new DefaultAzureCredential();
const client = new SecretClient(
  `https://<vault-name>.vault.azure.net/`,
  credential
);

async function getSecret(secretName) {
  const secret = await client.getSecret(secretName);
  return secret.value;
}

// Usage
const dbPassword = await getSecret('database-password');
```

---

## GCP Secret Manager

### Best For
- GCP-native applications
- Google Cloud ecosystem users
- Workload Identity integration

### Pros
- ✅ Simple API
- ✅ Native GCP integration
- ✅ Workload Identity support
- ✅ Stackdriver logging
- ✅ Cost-effective

### Cons
- ❌ GCP-only
- ❌ No automatic rotation
- ❌ Limited secret types

### Code Example

```javascript
const secretManager = require("@google-cloud/secret-manager");

const client = new secretManager.SecretManagerServiceClient();

async function accessSecret(projectId, secretId) {
  const name = client.secretVersionPath(projectId, secretId, 'latest');
  const [version] = await client.accessSecretVersion({ name });
  return version.payload.data.toString();
}

// Usage
const secret = await accessSecret(
  process.env.GCP_PROJECT_ID,
  'app-db-password'
);
```

---

## Decision Matrix

### Use AWS Secrets Manager If:
```
- Your app runs on AWS
- You need simplicity
- You want managed service
- You have compliance with AWS
- Budget is important
```

### Use HashiCorp Vault If:
```
- Multi-cloud deployment
- On-premises infrastructure
- Complex access policies
- Self-hosted preference
- Advanced secret rotation needs
```

### Use Azure Key Vault If:
```
- Your app runs on Azure
- Microsoft stack integration
- HSM/FIPS compliance needed
- Azure CI/CD integration
```

### Use GCP Secret Manager If:
```
- Your app runs on GCP
- Workload Identity important
- Simple secrets needs
- GCP native integration
```

---

## Implementation Priority

### Phase 1: Stop the Bleeding (Week 1)
1. Rotate all exposed credentials
2. Remove .env files from Git
3. Implement GitLeaks/TruffleHog scanning

### Phase 2: Quick Win (Week 2)
1. Implement AWS Secrets Manager OR HashiCorp Vault
2. Update app to use secrets manager
3. Remove all .env file loading

### Phase 3: Hardening (Week 3-4)
1. Implement secret rotation policies
2. Add audit logging
3. Train development team

### Phase 4: Excellence (Ongoing)
1. Automate rotation
2. Multi-region failover
3. Disaster recovery testing

---

## CI/CD Integration

### GitHub Actions

```yaml
name: Deploy

on: [push]

jobs:
  deploy:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v3

      - name: Configure AWS credentials
        uses: aws-actions/configure-aws-credentials@v2
        with:
          role-to-assume: arn:aws:iam::ACCOUNT_ID:role/github-actions
          aws-region: us-east-1

      - name: Get secrets from AWS
        run: |
          aws secretsmanager get-secret-value \
            --secret-id app/production/secrets \
            --query 'SecretString' \
            --output text > secrets.json

      - name: Deploy
        run: npm run deploy
```

### GitLab CI/CD

```yaml
deploy:
  image: node:18
  stage: deploy
  script:
    - aws secretsmanager get-secret-value 
        --secret-id $SECRET_ID 
        --query SecretString 
        --output text > secrets.json
    - npm run deploy
  only:
    - main
```

---

## Testing with Secrets

### Unit Tests

```javascript
describe('Secret Management', () => {
  it('should validate required secrets on startup', async () => {
    const secretsManager = require('./secrets');

    await expect(
      secretsManager.validateRequired([
        'DATABASE_URL',
        'JWT_SECRET'
      ])
    ).resolves.not.toThrow();
  });

  it('should not expose secrets in error messages', async () => {
    const secretsManager = require('./secrets');
    const secret = await secretsManager.get('SECRET_KEY');

    expect(console.log).not.toHaveBeenCalledWith(
      expect.stringContaining(secret)
    );
  });
});
```

### Integration Tests

```javascript
describe('Secret Rotation', () => {
  it('should handle secret rotation gracefully', async () => {
    const oldSecret = await getSecret('app/secrets');
    await rotateSecret('app/secrets');
    const newSecret = await getSecret('app/secrets');

    expect(newSecret).not.toEqual(oldSecret);
    expect(app).toStillBeRunning();
  });
});
```

---

## Monitoring and Alerting

### CloudWatch Alarms

```javascript
const cloudwatch = new AWS.CloudWatch();

await cloudwatch.putMetricAlarm({
  AlarmName: 'SecretAccessAnomaly',
  MetricName: 'SecretAccessCount',
  Namespace: 'AWS/SecretsManager',
  Statistic: 'Sum',
  Period: 300,
  EvaluationPeriods: 1,
  Threshold: 100,
  ComparisonOperator: 'GreaterThanThreshold',
  AlarmActions: ['arn:aws:sns:...']
}).promise();
```

### Vault Audit Logging

```hcl
audit {
  file {
    path = "/vault/logs/audit.log"
  }
}

listener "tcp" {
  address       = "127.0.0.1:8200"
  tls_cert_file = "/vault/tls/vault.crt"
  tls_key_file  = "/vault/tls/vault.key"
}
```

