// SECURE VERSION OF app.js
// Implements security best practices for production deployment

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const { query, body, validationResult } = require('express-validator');
const uuid = require('uuid');

// Initialize express app
const app = express();

// ===== ENVIRONMENT CONFIGURATION =====
const nodeEnv = process.env.NODE_ENV || 'development';
const port = process.env.PORT || 3000;
const jwtSecret = process.env.JWT_SECRET;

// Validate required environment variables in production
if (nodeEnv === 'production') {
  if (!jwtSecret) {
    throw new Error('JWT_SECRET environment variable is required in production');
  }
  if (!process.env.ALLOWED_ORIGINS) {
    throw new Error('ALLOWED_ORIGINS environment variable is required in production');
  }
}

// ===== SECURITY MIDDLEWARE =====

// 1. Add request ID for tracking
app.use((req, res, next) => {
  req.id = uuid.v4();
  res.setHeader('X-Request-ID', req.id);
  next();
});

// 2. Helmet - Set security headers
app.use(helmet());
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", "data:", "https:"],
    connectSrc: ["'self'"],
    fontSrc: ["'self'"],
    objectSrc: ["'none'"],
    mediaSrc: ["'self'"],
    frameSrc: ["'none'"],
  },
}));

// 3. CORS - Strict configuration
const corsOptions = {
  origin: nodeEnv === 'production'
    ? process.env.ALLOWED_ORIGINS.split(',')
    : ['http://localhost:3000', 'http://localhost:3001'],
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400,
  optionsSuccessStatus: 200,
};
app.use(cors(corsOptions));

// 4. Rate limiting - Global
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: 'Too many requests from this IP, please try again later',
  skip: (req) => nodeEnv === 'development' && req.ip === '::1',
});
app.use(globalLimiter);

// 5. Rate limiting - Auth endpoints (stricter)
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Only 5 attempts per 15 minutes
  skipSuccessfulRequests: true, // Don't count successful requests
});

// 6. Request parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// ===== AUTHENTICATION MIDDLEWARE =====

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({
      error: 'Access token required',
      requestId: req.id,
    });
  }

  jwt.verify(token, jwtSecret, (err, user) => {
    if (err) {
      return res.status(403).json({
        error: 'Invalid or expired token',
        requestId: req.id,
      });
    }
    req.user = user;
    next();
  });
};

// ===== LOGGING (Simple - use winston/pino in production) =====

const logRequest = (req, eventType, metadata = {}) => {
  const logData = {
    timestamp: new Date().toISOString(),
    requestId: req.id,
    event: eventType,
    method: req.method,
    path: req.path,
    ip: req.ip,
    userId: req.user?.id || 'anonymous',
    ...metadata,
  };

  if (nodeEnv === 'development') {
    console.log(JSON.stringify(logData));
  }
  // In production, send to centralized logging: ELK, Datadog, CloudWatch, etc.
};

// ===== ROUTES =====

// Health check endpoint (public)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: nodeEnv,
    uptime: process.uptime(),
  });
});

// Login endpoint
app.post('/login',
  authLimiter,
  body('username')
    .trim()
    .notEmpty().withMessage('Username required')
    .isLength({ min: 3, max: 50 }).withMessage('Username must be 3-50 characters')
    .matches(/^[a-zA-Z0-9_-]+$/).withMessage('Username contains invalid characters'),
  body('password')
    .notEmpty().withMessage('Password required')
    .isLength({ min: 8 }).withMessage('Password must be at least 8 characters'),
  async (req, res, next) => {
    try {
      // Check validation errors
