# Edit .env with your actual values
```

### Step 4: Replace app.js with app-secure.js
```bash
cp app.js app-old.js
cp app-secure.js app.js
```

### Step 5: Update package.json scripts
```json
{
  "scripts": {
    "start": "node app.js",
    "dev": "NODE_ENV=development nodemon app.js",
    "test": "NODE_ENV=test jest",
    "audit": "npm audit --audit-level=high"
  }
}
```

---

## Security Implementation Details

### 1. Environment Configuration

**Problem:** Hardcoded values and secrets exposed

**Solution:**
```javascript
// config.js
require('dotenv').config();

const config = {
  nodeEnv: process.env.NODE_ENV || 'development',
  port: process.env.PORT || 3000,
  jwtSecret: process.env.JWT_SECRET,
  allowedOrigins: process.env.ALLOWED_ORIGINS?.split(',') || [],
};

// Validate in production
if (config.nodeEnv === 'production') {
  if (!config.jwtSecret) {
    throw new Error('JWT_SECRET is required in production');
  }
  if (!config.allowedOrigins.length) {
    throw new Error('ALLOWED_ORIGINS is required in production');
  }
}

module.exports = config;
```

### 2. Security Headers with Helmet

**Problem:** Application vulnerable to common web attacks

**Solution:**
```javascript
const helmet = require('helmet');
const app = express();

// Apply all helmet defaults
app.use(helmet());

// Customize CSP for your app
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", "data:", "https:"],
    connectSrc: ["'self'"],
    fontSrc: ["'self'"],
    objectSrc: ["'none'"],
  },
}));

// HSTS for HTTPS enforcement
app.use(helmet.hsts({
  maxAge: 31536000,
  includeSubDomains: true,
  preload: true,
}));
```

### 3. Authentication with JWT

**Problem:** No authentication mechanism

**Solution:**
```javascript
const jwt = require('jsonwebtoken');

// Middleware
const authenticate = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Token required' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    res.status(403).json({ error: 'Invalid token' });
  }
};

// Generate token on login
app.post('/login', async (req, res) => {
  const user = await verifyCredentials(req.body);

  if (!user) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const token = jwt.sign(
    { id: user.id, role: user.role },
    process.env.JWT_SECRET,
    { expiresIn: '1h' }
  );

  res.json({ token });
});

// Protected routes
app.get('/users', authenticate, (req, res) => {
  res.json({ data: users });
});
```

### 4. Input Validation

**Problem:** No validation of user input

**Solution:**
```javascript
const { query, body, validationResult, param } = require('express-validator');

// Validation middleware
const validateUser = [
  body('email')
    .isEmail().withMessage('Valid email required')
    .normalizeEmail(),
  body('password')
    .isLength({ min: 8 }).withMessage('Min 8 characters')
    .matches(/[A-Z]/).withMessage('Must contain uppercase')
    .matches(/[a-z]/).withMessage('Must contain lowercase')
    .matches(/[0-9]/).withMessage('Must contain number'),
];

// Validation error handler
const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

// Use in routes
app.post('/register', validateUser, validate, async (req, res) => {
  // req.body is validated and sanitized
  const user = await createUser(req.body);
  res.json(user);
});

// Query validation
app.get('/users',
  authenticate,
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('search').optional().trim().escape(),
  validate,
  (req, res) => {
    // Safe to use req.query
  }
);
```

### 5. Rate Limiting

**Problem:** No protection against brute force/DoS

**Solution:**
```javascript
const rateLimit = require('express-rate-limit');

// General rate limit
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests
  standardHeaders: true,
  legacyHeaders: false,
});

// Strict limit for auth
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Only 5 login attempts
  skipSuccessfulRequests: true, // Don't count successful logins
  message: 'Too many login attempts, try again later',
});

app.use(generalLimiter);
app.post('/login', authLimiter, (req, res) => {
  // Login route
});

// Custom storage for distributed systems
const RedisStore = require('rate-limit-redis');
const redis = require('redis');

const client = redis.createClient();

const limiter = rateLimit({
  store: new RedisStore({
    client: client,
    prefix: 'rl:', // Rate limit prefix
  }),
  windowMs: 15 * 60 * 1000,
  max: 100,
});
```

### 6. CORS Configuration

**Problem:** Open to cross-origin attacks

**Solution:**
```javascript
const cors = require('cors');

// Strict CORS configuration
const corsOptions = {
  origin: (origin, callback) => {
    const whitelist = process.env.ALLOWED_ORIGINS?.split(',') || [];

    if (!origin || whitelist.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('CORS not allowed'));
    }
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400,
  optionsSuccessStatus: 200,
};

// Apply globally
app.use(cors(corsOptions));

// Or per route
app.get('/public', cors(), (req, res) => {
  res.json({ public: true });
});
```

### 7. Error Handling

**Problem:** Stack traces exposed to clients

**Solution:**
```javascript
const logger = require('pino')();

// Error handler middleware (place at end)
app.use((err, req, res, next) => {
  // Log error with context
  logger.error({
    message: err.message,
    stack: err.stack,
    path: req.path,
    userId: req.user?.id,
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });

  // Send generic response to client
  const isDev = process.env.NODE_ENV === 'development';

  res.status(err.statusCode || 500).json({
    error: isDev ? err.message : 'Internal server error',
    requestId: req.id,
    ...(isDev && { stack: err.stack }),
  });
});

// Route error handling
app.get('/users/:id', authenticate, async (req, res, next) => {
  try {
    const user = await User.findById(req.params.id);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  } catch (error) {
    next(error); // Pass to error handler
  }
});
```

### 8. Database Security

**Problem:** SQL/NoSQL injection vulnerabilities

**Solution:**
```javascript
// Use parameterized queries (NOT string concatenation!)

// ❌ VULNERABLE:
