});

// With Mongoose
const user = await User.findById(req.params.id);
```

### 9. Password Hashing

**Problem:** Plaintext passwords stored

**Solution:**
```javascript
const bcrypt = require('bcryptjs');

// Hashing on registration
app.post('/register', async (req, res) => {
  const { password } = req.body;

