  res.json({ token });
});
```

### 10. Request Size Limits

**Problem:** Memory exhaustion from large requests

**Solution:**
```javascript
// Limit body size
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

