### **VULNERABILITIES IDENTIFIED**

#### **1. ⚠️ CRITICAL: Missing Authentication & Authorization (OWASP A01:2021)**
**Severity:** CRITICAL

**Issue:**
```javascript
app.get('/users', (req, res) => {
  res.json([...]);  // No authentication required!
});
```

**Problems:**
- `/users` endpoint exposes user data without any authentication
- No authorization checks - any unauthenticated user can access sensitive data
- No rate limiting to prevent data harvesting/enumeration attacks

**Recommendation:**

```javascript
const express = require('express');
const jwt = require('jsonwebtoken');
const rateLimit = require('express-rate-limit');

const app = express();

// Middleware for JWT authentication
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
};

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

app.get('/users', authenticateToken, (req, res) => {
  // Only authenticated users can access this
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

