#### **Step 2: Use AWS Secrets Manager (Recommended for AWS Environments)**

**Implementation:**

```javascript
// config/secrets.js
const AWS = require('aws-sdk');

const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1',
});

let cachedSecrets = null;
const CACHE_TTL = 3600000; // 1 hour
let cacheTime = 0;

async function getSecrets() {
  // Return cached secrets if still valid
  if (cachedSecrets && Date.now() - cacheTime < CACHE_TTL) {
    return cachedSecrets;
  }

  try {
    const secretName = process.env.SECRETS_NAME || 'prod/app-secrets';

    const data = await secretsManager.getSecretValue({
      SecretId: secretName,
    }).promise();

    let secrets;
    if ('SecretString' in data) {
      secrets = JSON.parse(data.SecretString);
    } else {
      // Handle binary secrets
      secrets = Buffer.from(data.SecretBinary, 'base64').toString();
    }

    cachedSecrets = secrets;
    cacheTime = Date.now();
    return secrets;
  } catch (error) {
    console.error('Error retrieving secrets:', error);
    throw new Error('Failed to retrieve application secrets');
  }
}

module.exports = { getSecrets };
```

**Usage in app.js:**

```javascript
// app.js
const { getSecrets } = require('./config/secrets');

let config = {};

app.listen = async (port, callback) => {
  try {
    config = await getSecrets();
    console.log('Secrets loaded successfully');
    return require('http').Server.prototype.listen.call(this, port, callback);
  } catch (error) {
    console.error('Failed to start server:', error);
    process.exit(1);
  }
};
```

