#### **Step 4: Use Azure Key Vault (For Azure Environments)**

```javascript
// config/azure-vault.js
const { SecretClient } = require("@azure/keyvault-secrets");
const { DefaultAzureCredential } = require("@azure/identity");

const credential = new DefaultAzureCredential();
const client = new SecretClient(
  `https://${process.env.VAULT_NAME}.vault.azure.net/`,
  credential
);

async function getSecretsFromAzure() {
  const secrets = {};
  const secretNames = [
    'DATABASE-URL',
    'JWT-SECRET',
    'AWS-ACCESS-KEY-ID',
    'AWS-SECRET-ACCESS-KEY',
  ];

  for (const name of secretNames) {
    try {
      const secret = await client.getSecret(name);
      secrets[name.replace(/-/g, '_')] = secret.value;
    } catch (error) {
      console.error(`Failed to retrieve ${name}:`, error);
      throw error;
    }
  }

  return secrets;
}

module.exports = { getSecretsFromAzure };
```

