#### **Step 5: Use Google Cloud Secret Manager**

```javascript
// config/gcp-secrets.js
const secretManager = require('@google-cloud/secret-manager');

async function getSecretsFromGCP() {
  const client = new secretManager.SecretManagerServiceClient();
  const projectId = process.env.GCP_PROJECT_ID;

  const secretNames = [
    'database-url',
    'jwt-secret',
    'stripe-secret-key',
    'anthropic-api-key',
  ];

  const secrets = {};

  for (const name of secretNames) {
    const secretPath = client.secretVersionPath(
      projectId,
      name,
      'latest'
    );

    const [version] = await client.accessSecretVersion({ name: secretPath });
    secrets[name.replace(/-/g, '_')] = 
      version.payload.data.toString('utf8');
  }

  return secrets;
}

module.exports = { getSecretsFromGCP };
```

