### Option 1: **AWS Secrets Manager** (RECOMMENDED for AWS environments)

```javascript
// secure-config.js
const AWS = require('aws-sdk');
const client = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

class SecretsManager {
  constructor() {
    this.cache = new Map();
    this.cacheExpiry = 3600000; // 1 hour in milliseconds
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() < cached.expiry) {
      return cached.value;
    }

    try {
      const data = await client.getSecretValue({
        SecretId: secretName
      }).promise();

      const secretValue = data.SecretString 
        ? JSON.parse(data.SecretString) 
        : data.SecretBinary;

      // Cache with expiry
      this.cache.set(secretName, {
        value: secretValue,
        expiry: Date.now() + this.cacheExpiry
      });

      return secretValue;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);
      throw error;
    }
  }

  // Rotate credentials
  async rotateSecret(secretName) {
    try {
      await client.rotateSecret({
        SecretId: secretName,
        RotationLambdaARN: process.env.ROTATION_LAMBDA_ARN,
        RotationRules: {
          AutomaticallyAfterDays: 30
        }
      }).promise();

      // Invalidate cache
      this.cache.delete(secretName);
    } catch (error) {
      console.error(`Failed to rotate secret ${secretName}:`, error);
      throw error;
    }
  }
}

module.exports = new SecretsManager();
```

