// gcp-secrets.js
const secretManager = require('@google-cloud/secret-manager');

class GCPSecretsManager {
  constructor() {
    this.client = new secretManager.SecretManagerServiceClient();
    this.project = process.env.GCP_PROJECT_ID;
  }

  async getSecret(secretName, version = 'latest') {
    try {
      const name = this.client.secretVersionPath(
        this.project,
        secretName,
        version
      );

      const [version_] = await this.client.accessSecretVersion({ name });
      const secretString = version_.payload.data.toString('utf-8');

      return JSON.parse(secretString);
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);
      throw error;
    }
  }

  async createSecret(secretName, secretValue) {
    const parent = this.client.projectPath(this.project);

    // Create secret
    const [secret] = await this.client.createSecret({
      parent,
      secretId: secretName,
      secret: {
        replication: {
          automatic: {}
        }
      }
    });

    // Add version
    await this.client.addSecretVersion({
      parent: secret.name,
      payload: {
        data: Buffer.from(JSON.stringify(secretValue))
      }
    });

    return secret;
  }
}

module.exports = new GCPSecretsManager();
