// Secure version of app.js with security best practices
// This version addresses OWASP Top 10 vulnerabilities

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('mongo-sanitize');
const xss = require('xss-clean');
const cors = require('cors');
const path = require('path');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE - Apply before routes
// ============================================================================

// 1. HELMET.JS - Sets various HTTP headers for protection (A06:2021 - Vulnerable and Outdated Components)
app.use(helmet());

// 2. CORS - Restrict cross-origin requests (A01:2021 - Broken Access Control)
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600
};
app.use(cors(corsOptions));

// 3. RATE LIMITING - Prevent brute force and DoS (A07:2021 - Identification and Authentication Failures)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});
app.use(limiter);

// 4. INPUT SANITIZATION - Prevent injection attacks
app.use(express.json({ limit: '10kb' })); // Limit payload size (A01:2021 - Broken Access Control)
app.use(mongoSanitize()); // Prevent NoSQL injection (A03:2021 - Injection)
app.use(xss()); // Prevent XSS attacks (A03:2021 - Injection)

// 5. LOGGING - For security auditing
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// ============================================================================
