class SecretsManager {
  constructor(backend = 'aws') {
    this.backend = backend;
    this.secrets = null;
  }

  async initialize() {
    switch (this.backend) {
      case 'aws':
        this.secrets = await loadSecretsFromAWS();
        break;
      case 'vault':
        this.secrets = await loadSecretsFromVault();
        break;
      case 'gcp':
        this.secrets = await loadSecretsFromGCP();
        break;
      case 'env':
        this.secrets = this.loadFromEnv();
        break;
      default:
        throw new Error(`Unknown secrets backend: ${this.backend}`);
    }

    // Validate all required secrets are present
    this.validate();
  }

  loadFromEnv() {
    return {
      JWT_SECRET: process.env.JWT_SECRET,
      DB_PASSWORD: process.env.DB_PASSWORD,
      API_KEY: process.env.API_KEY,
      STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
      SESSION_SECRET: process.env.SESSION_SECRET
    };
  }

  validate() {
    const required = [
      'JWT_SECRET',
      'DB_PASSWORD',
      'API_KEY',
      'SESSION_SECRET'
    ];

    const missing = required.filter(key => !this.secrets[key]);

    if (missing.length > 0) {
      throw new Error(
        `Missing required secrets: ${missing.join(', ')}`
      );
    }
  }

  get(key) {
    if (!this.secrets[key]) {
      throw new Error(`Secret '${key}' not found`);
    }
    return this.secrets[key];
  }

  has(key) {
    return !!this.secrets[key];
  }

  // Prevent accidental logging of secrets
  toString() {
    return '[SecretsManager]';
  }

  toJSON() {
    return { _type: 'SecretsManager', backend: this.backend };
  }
}

