  } catch (error) {
    logger.error(error);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

// ============ ERROR HANDLING ============
app.use((err, req, res, next) => {
  logger.error({ message: err.message, stack: err.stack, path: req.path });
