      if (req.user.role !== 'admin') {
        logger.warn({
          event: 'unauthorized_users_access',
          userId: req.user.id,
          role: req.user.role,
          ip: req.ip
        });
        return res.status(403).json({ error: 'Insufficient permissions.' });
      }

      // Validate input
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        logger.warn({
          event: 'invalid_query_parameters',
          userId: req.user.id,
          errors: errors.array()
        });
        return res.status(400).json({ errors: errors.array() });
      }

      const { page = 1, limit = 10, search = '' } = req.query;

      // Mock data (in production, query database with parameterized queries)
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Filter based on search (if provided)
      const filtered = search
        ? allUsers.filter(u => u.name.includes(search) || u.email.includes(search))
        : allUsers;

      // Pagination
      const startIndex = (page - 1) * limit;
      const endIndex = startIndex + limit;
      const paginatedUsers = filtered.slice(startIndex, endIndex);

      logger.info({
        event: 'users_retrieved',
        userId: req.user.id,
        count: paginatedUsers.length,
        page,
        limit
      });

      res.json({
        data: paginatedUsers,
        pagination: {
          page,
          limit,
          total: filtered.length,
          pages: Math.ceil(filtered.length / limit)
        }
      });
    } catch (error) {
      logger.error({
        message: 'Error retrieving users',
        userId: req.user.id,
        error: error.message
      });
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

/**
 * Get User by ID
 * Requires authentication
 */
app.get('/users/:id',
  authenticateToken,
  (req, res) => {
    try {
      const { id } = req.params;

      // Validate numeric ID
      if (!Number.isInteger(parseInt(id))) {
        return res.status(400).json({ error: 'Invalid user ID.' });
      }

      // Mock data
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = allUsers.find(u => u.id === parseInt(id));

      if (!user) {
        return res.status(404).json({ error: 'User not found.' });
      }

      // Users can only see their own data unless they're admins
      if (req.user.id !== parseInt(id) && req.user.role !== 'admin') {
        logger.warn({
          event: 'unauthorized_user_access',
          userId: req.user.id,
          targetUserId: id,
          ip: req.ip
        });
        return res.status(403).json({ error: 'You do not have permission to view this user.' });
      }

      res.json(user);
    } catch (error) {
      logger.error({ message: 'Error retrieving user', error: error.message });
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// ==================== ERROR HANDLING ====================

// 404 Handler
app.use((req, res) => {
  res.status(404).json({ error: 'Endpoint not found.' });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  logger.error({
    message: 'Unhandled error',
    error: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    userId: req.user?.id
  });

  // Don't expose internal error details in production
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal server error'
    : err.message;

  res.status(err.status || 500).json({ error: message });
});

// ==================== SERVER STARTUP ====================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Validate required environment variables
const requiredEnvVars = ['JWT_SECRET', 'ADMIN_PASSWORD'];
for (const envVar of requiredEnvVars) {
  if (!process.env[envVar]) {
    console.error(`ERROR: ${envVar} environment variable not set`);
    process.exit(1);
  }
}

// Start server
if (NODE_ENV === 'production') {
  try {
    const key = fs.readFileSync(process.env.SSL_KEY_PATH);
    const cert = fs.readFileSync(process.env.SSL_CERT_PATH);
    https.createServer({ key, cert }, app).listen(PORT, () => {
      logger.info(`Secure server running on port ${PORT} in ${NODE_ENV} mode`);
    });
  } catch (error) {
    logger.error('Failed to start HTTPS server', error);
    process.exit(1);
  }
} else {
  app.listen(PORT, () => {
    logger.info(`Server running on port ${PORT} in ${NODE_ENV} mode`);
  });
}

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully...');
  process.exit(0);
});

module.exports = app;
