# Vulnerability Comparison: Original vs Secure Version

## Side-by-Side Code Comparison

### 1. AUTHENTICATION & AUTHORIZATION

#### ❌ VULNERABLE (Original)
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```
**Problems:**
- No authentication check
- No authorization check
- Anyone can access this endpoint

---

#### ✅ SECURE (Fixed)
```javascript
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn({ event: 'unauthorized_access_attempt', path: req.path });
    return res.status(401).json({ error: 'Access denied. No token provided.' });
  }

  try {
    const user = jwt.verify(token, process.env.JWT_SECRET);
    req.user = user;
    next();
  } catch (error) {
    logger.warn({ event: 'invalid_token_attempt', error: error.message });
    return res.status(403).json({ error: 'Invalid or expired token.' });
  }
};

app.get('/users', authenticateToken, (req, res) => {
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Insufficient permissions.' });
  }
  // ... endpoint logic
});
```
**Improvements:**
- ✅ JWT token validation
- ✅ Role-based authorization
- ✅ Security logging
- ✅ Clear error messages

---

### 2. INPUT VALIDATION

#### ❌ VULNERABLE (Original)
```javascript
app.get('/users', (req, res) => {
  // No validation of query parameters
  const { page, limit, search } = req.query;

  // Vulnerable to:
  // - SQL injection: /users?search='; DROP TABLE users; --
  // - XSS: /users?search=<script>alert(1)</script>
  // - Type confusion: /users?page=abc
  // - Buffer overflow: /users?search=<huge payload>
});
```

---

#### ✅ SECURE (Fixed)
```javascript
app.get('/users',
  authenticateToken,
  query('page').optional().isInt({ min: 1, max: 1000 }).toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('search').optional().trim().isLength({ max: 50 }).escape(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { page = 1, limit = 10, search = '' } = req.query;
    // All parameters are now validated and safe to use
  }
);
```
**Improvements:**
- ✅ Integer validation for page/limit
- ✅ Type checking
- ✅ Range validation (min/max bounds)
- ✅ String length limits
- ✅ HTML escaping for search parameter
- ✅ Error reporting

---

### 3. SECURITY HEADERS

#### ❌ VULNERABLE (Original)
```javascript
const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

// No security headers configured!
// Vulnerable to: XSS, Clickjacking, MIME sniffing, etc.
```

---

#### ✅ SECURE (Fixed)
```javascript
const helmet = require('helmet');

app.use(helmet()); // Sets multiple security headers automatically

// Headers set by helmet:
// Strict-Transport-Security: max-age=31536000; includeSubDomains
// X-Content-Type-Options: nosniff
// X-Frame-Options: DENY
// X-XSS-Protection: 1; mode=block
// Content-Security-Policy: default-src 'self'
// Referrer-Policy: no-referrer

app.disable('x-powered-by'); // Hide server info

app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});
```

---

### 4. RATE LIMITING & DOS PROTECTION

#### ❌ VULNERABLE (Original)
```javascript
const app = express();

// No rate limiting!
// Vulnerable to: Brute force attacks, DDoS, credential stuffing
```

---

#### ✅ SECURE (Fixed)
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit to 100 requests per window
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10, // strict limit for auth endpoints
});

app.use(limiter); // Apply to all routes

app.post('/login', strictLimiter, (req, res) => {
  // Brute force protection
});
```

---

### 5. ERROR HANDLING

#### ❌ VULNERABLE (Original)
```javascript
app.get('/users', (req, res) => {
  res.json([...]);
  // No error handling
  // Stack traces exposed on error
  // No logging
});
```

---

#### ✅ SECURE (Fixed)
```javascript
app.get('/users', authenticateToken, (req, res) => {
  try {
    // ... protected logic
    res.json({ data: users });
  } catch (error) {
    logger.error({
      message: 'Error retrieving users',
      userId: req.user.id,
      error: error.message
    });

    // Don't expose stack trace in production
    const message = process.env.NODE_ENV === 'production'
      ? 'Internal server error'
      : error.message;

    res.status(500).json({ error: message });
  }
});

// Global error handler
app.use((err, req, res, next) => {
  logger.error({
    message: 'Unhandled error',
    stack: err.stack,
    url: req.url
  });

  const message = process.env.NODE_ENV === 'production'
    ? 'Internal server error'
    : err.message;

  res.status(err.status || 500).json({ error: message });
});
```

---

### 6. CORS CONFIGURATION

#### ❌ VULNERABLE (Original)
```javascript
const app = express();

// No CORS setup
// Either: completely blocked or overly permissive
// Vulnerable to cross-origin attacks
```

---

#### ✅ SECURE (Fixed)
```javascript
const cors = require('cors');

app.use(cors({
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400 // Cache preflight for 24h
}));
```
**Benefits:**
- ✅ Whitelist-based origin checking
- ✅ Restricts HTTP methods
- ✅ Restricts headers
- ✅ Environment-configurable

---

### 7. SENSITIVE DATA EXPOSURE

#### ❌ VULNERABLE (Original)
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' }, // Email exposed!
    { id: 2, name: 'Bob', email: 'bob@example.com' },    // Easy to harvest
  ]);
  // No rate limiting on data access
  // No pagination
  // All data returned at once
});
```

---

#### ✅ SECURE (Fixed)
```javascript
app.get('/users', authenticateToken, (req, res) => {
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Insufficient permissions.' });
  }

  // Only authorized admins can access
  // Pagination to limit data exposure
  const startIndex = (page - 1) * limit;
  const paginatedUsers = allUsers.slice(startIndex, startIndex + limit);

  // Only return necessary fields
  const sanitized = paginatedUsers.map(user => ({
    id: user.id,
    name: user.name,
    email: req.user.role === 'admin' ? user.email : undefined
  }));

  res.json({
    data: sanitized,
    pagination: { page, limit, total: allUsers.length }
  });
});
```

---

### 8. SECRETS MANAGEMENT

#### ❌ VULNERABLE (Original)
```javascript
app.listen(3000, () => { // Hardcoded port
  console.log('Server running on port 3000');
});

// No environment variables
// Secrets hardcoded
// Configuration in code
```

---

#### ✅ SECURE (Fixed)
```javascript
require('dotenv').config();

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Validate required secrets
const requiredEnvVars = ['JWT_SECRET', 'ADMIN_PASSWORD'];
for (const envVar of requiredEnvVars) {
  if (!process.env[envVar]) {
    console.error(`ERROR: ${envVar} environment variable not set`);
    process.exit(1);
  }
}

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});
```

