    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { page = 1, limit = 10, search = '' } = req.query;

    // Your logic here with validated parameters
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
    ]);
  }
);
```

---

#### 4. **HIGH: Missing Security Headers** (OWASP A05:2021)
**Severity:** HIGH

**Issue:** No security headers configured. Application is vulnerable to various attacks.

**RECOMMENDED FIX:**
```javascript
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

const app = express();

// Security headers
app.use(helmet());

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests, please try again later.'
});

app.use(limiter);

// Disable X-Powered-By header
app.disable('x-powered-by');

// Content Security Policy
app.use((req, res, next) => {
  res.setHeader('Content-Security-Policy', "default-src 'self'");
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  next();
});
```

---

#### 5. **MEDIUM: Lack of Logging and Monitoring** (OWASP A09:2021)
**Severity:** MEDIUM

**Issue:** No logging for security events, making incident detection and forensics impossible.

**RECOMMENDED FIX:**
```javascript
const winston = require('winston');

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'api' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

// Middleware to log all requests
app.use((req, res, next) => {
  const startTime = Date.now();

  res.on('finish', () => {
    logger.info({
      method: req.method,
      url: req.url,
      status: res.statusCode,
      duration: Date.now() - startTime,
      ip: req.ip,
      userId: req.user?.id
    });
  });

  next();
});

// Error logging middleware
app.use((err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    method: req.method,
    url: req.url,
    userId: req.user?.id
  });

  res.status(500).json({ error: 'Internal server error' });
});
```

---

#### 6. **MEDIUM: No Error Handling** (OWASP A06:2021)
**Severity:** MEDIUM

**Issue:** No try-catch blocks or error handling. Stack traces could be exposed.

**RECOMMENDED FIX:**
```javascript
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      environment: process.env.NODE_ENV
    });
  } catch (error) {
    logger.error({ message: 'Health check error', error });
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  logger.error(err);

  // Don't expose internal error details in production
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(err.status || 500).json({ error: message });
});
```

---

#### 7. **MEDIUM: No Environment Configuration** 
**Severity:** MEDIUM

**Issue:** Hardcoded values and no environment variable usage.

**RECOMMENDED FIX:**
```javascript
require('dotenv').config();

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

if (!process.env.JWT_SECRET) {
  console.error('ERROR: JWT_SECRET environment variable not set');
  process.exit(1);
}

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});
```

