/**
 * Production-Ready Secure Express Application
 * This file demonstrates security best practices for the original app.js
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const morgan = require('morgan');
const https = require('https');
const fs = require('fs');
require('dotenv').config();

const app = express();

// ============================================================================
// 1. ENVIRONMENT & CONFIGURATION
// ============================================================================

const config = {
  port: process.env.PORT || 3000,
  nodeEnv: process.env.NODE_ENV || 'development',
  jwtSecret: process.env.JWT_SECRET || 'your-secret-key-change-in-production',
  allowedOrigins: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
};

// Validate production config
if (config.nodeEnv === 'production') {
  const requiredVars = ['JWT_SECRET', 'DATABASE_URL'];
  const missing = requiredVars.filter(v => !process.env[v]);
  if (missing.length > 0) {
    throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
  }
}

// ============================================================================
// 2. SECURITY MIDDLEWARE - HELMET (Security Headers)
// ============================================================================

app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true,
  },
}));

// ============================================================================
// 3. CORS - Cross-Origin Resource Sharing
// ============================================================================

const corsOptions = {
  origin: config.allowedOrigins,
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
  optionsSuccessStatus: 200,
};

app.use(cors(corsOptions));

// ============================================================================
// 4. BODY PARSER WITH SIZE LIMITS
// ============================================================================

app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// ============================================================================
// 5. LOGGING (Morgan + Winston)
// ============================================================================

// Simple logging for demo (use winston in production)
app.use(morgan('combined'));

// Custom security event logging
app.use((req, res, next) => {
  const startTime = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - startTime;
    const logLevel = res.statusCode >= 400 ? 'WARN' : 'INFO';

    console.log(`[${logLevel}] ${req.method} ${req.path} - ${res.statusCode} (${duration}ms) - IP: ${req.ip}`);

    // Log failed authentication attempts
    if (res.statusCode === 401 || res.statusCode === 403) {
      console.log(`[SECURITY] Unauthorized access attempt: ${req.method} ${req.path} from ${req.ip}`);
    }
  });

  next();
});

// ============================================================================
// 6. RATE LIMITING
// ============================================================================

const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per window
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => config.nodeEnv !== 'production', // Disable in development
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 attempts per window
  skipSuccessfulRequests: true,
  message: 'Too many authentication attempts, please try again later.',
});

app.use(generalLimiter);

// ============================================================================
// 7. AUTHENTICATION MIDDLEWARE
// ============================================================================

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    console.log(`[SECURITY] Missing authentication token from ${req.ip}`);
    return res.status(401).json({ 
      error: 'Access token required',
      code: 'MISSING_TOKEN' 
    });
  }

  jwt.verify(token, config.jwtSecret, (err, user) => {
    if (err) {
      console.log(`[SECURITY] Invalid token from ${req.ip}: ${err.message}`);
      return res.status(403).json({ 
        error: 'Invalid or expired token',
        code: 'INVALID_TOKEN' 
      });
    }

    // Attach user to request
    req.user = user;
    next();
  });
};

// ============================================================================
// 8. AUTHORIZATION MIDDLEWARE
// ============================================================================

const requireAdmin = (req, res, next) => {
  if (!req.user || !req.user.isAdmin) {
    console.log(`[SECURITY] Unauthorized admin access attempt from ${req.ip} (user: ${req.user?.id})`);
    return res.status(403).json({ 
      error: 'Admin privileges required',
      code: 'INSUFFICIENT_PERMISSIONS' 
    });
  }
  next();
};

// ============================================================================
// 9. PUBLIC ENDPOINTS (No Authentication)
// ============================================================================

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: config.nodeEnv 
  });
});

// ============================================================================
// 10. PROTECTED ENDPOINTS (Authentication Required)
// ============================================================================

/**
 * GET /users - Retrieve users (Admin only)
 * Query parameters (optional):
 *   - id: User ID (integer)
 *   - name: User name (string)
 * 
 * Authentication: Bearer token required
 */
app.get('/users',
  authenticateToken,
  requireAdmin,
  [
    query('id').optional().isInt({ min: 1 }).toInt(),
    query('name').optional().isString().trim().isLength({ min: 1, max: 50 }).escape(),
  ],
  (req, res) => {
    // Validate input
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Invalid input parameters',
        details: errors.array() 
      });
    }

    // Mock database
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
    ];

    // Filter by ID if provided
    if (req.query.id) {
      const user = users.find(u => u.id === req.query.id);
      if (!user) {
        return res.status(404).json({ error: 'User not found' });
      }
      users = [user];
    }

    // Filter by name if provided
    if (req.query.name) {
      users = users.filter(u => 
        u.name.toLowerCase().includes(req.query.name.toLowerCase())
      );
    }

    res.json({
      success: true,
      data: users,
      count: users.length,
    });
  }
);

/**
 * GET /users/:id - Get user by ID (Authenticated users can view their own data)
 */
app.get('/users/:id',
  authenticateToken,
  [
    query('id').isInt({ min: 1 }).toInt(),
  ],
  (req, res) => {
    const userId = parseInt(req.params.id, 10);

    // Check authorization: user can only view their own data unless admin
    if (req.user.id !== userId && !req.user.isAdmin) {
      console.log(`[SECURITY] Unauthorized user data access attempt: user ${req.user.id} tried to access user ${userId}`);
      return res.status(403).json({ 
        error: 'Forbidden: You can only view your own profile',
        code: 'INSUFFICIENT_PERMISSIONS' 
      });
    }

    // Mock database lookup
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
    ];

    const user = users.find(u => u.id === userId);
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json({
      success: true,
      data: user,
    });
  }
);

/**
 * POST /login - Authenticate user and receive JWT token
 */
app.post('/login',
  authLimiter,
  [
    query('username').notEmpty().isString().trim().escape(),
    query('password').notEmpty().isString(),
  ],
  (req, res) => {
    // Validate input
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Invalid input parameters',
        details: errors.array() 
      });
    }

    // Mock authentication (in production: hash comparison, database lookup)
    const { username, password } = req.body;

    // NEVER log passwords
    console.log(`[AUTH] Login attempt for user: ${username}`);

    if (username === 'admin' && password === 'password123') {
      const user = { id: 1, username: 'admin', isAdmin: true };
      const token = jwt.sign(user, config.jwtSecret, { expiresIn: '1h' });

      return res.json({
        success: true,
        token,
        expiresIn: 3600,
      });
    }

    // Generic error message (don't reveal if user exists)
    console.log(`[SECURITY] Failed login attempt for user: ${username} from ${req.ip}`);
    res.status(401).json({ 
      error: 'Invalid credentials',
      code: 'AUTH_FAILED' 
    });
  }
);

// ============================================================================
// 11. INPUT VALIDATION HELPER
// ============================================================================

const validateEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};

// ============================================================================
// 12. ERROR HANDLING MIDDLEWARE (Must be last)
// ============================================================================

// 404 Handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    path: req.path,
    method: req.method,
  });
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error (security-sensitive details only in logs, not response)
  console.error(`[ERROR] ${err.message}`, {
    stack: config.nodeEnv === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip,
  });

  // Determine status code
  const status = err.status || err.statusCode || 500;

  // Generic error response (don't expose internals)
  const response = {
    error: status === 500 ? 'Internal Server Error' : err.message,
    code: err.code || 'UNKNOWN_ERROR',
  };

  // Only include details in development
  if (config.nodeEnv === 'development') {
    response.details = err.message;
    response.stack = err.stack;
  }

  res.status(status).json(response);
});

// ============================================================================
// 13. SERVER STARTUP
// ============================================================================

const PORT = config.port;

if (config.nodeEnv === 'production' && process.env.SSL_KEY_PATH && process.env.SSL_CERT_PATH) {
  // HTTPS server for production
  const options = {
    key: fs.readFileSync(process.env.SSL_KEY_PATH),
    cert: fs.readFileSync(process.env.SSL_CERT_PATH),
  };
  https.createServer(options, app).listen(PORT, () => {
    console.log(`🔒 Secure server running on port ${PORT}`);
  });
} else {
  // HTTP server for development
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT} (${config.nodeEnv} mode)`);
  });
}

module.exports = app;

