# Before & After Security Comparison

## Original app.js vs Secure app-secure.js

### 1. AUTHENTICATION

**BEFORE (Vulnerable):**
```javascript
app.get('/users', (req, res) => {
  // NO authentication - anyone can access
  res.json([...]);
});
```

**AFTER (Secure):**
```javascript
app.get('/users',
  authenticateToken,  // Middleware verifies JWT
  requireAdmin,       // Middleware checks role
  (req, res) => {
    // Only authenticated admins can access
    res.json({...});
  }
);

// Authentication middleware
const authenticateToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Token required' });

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user;
    next();
  });
};
```

**Impact:** Prevents unauthorized access ✅

---

### 2. INPUT VALIDATION

**BEFORE (Vulnerable):**
```javascript
app.get('/users', (req, res) => {
  // Query parameters not validated
  // Susceptible to injection attacks
  res.json([...]);
});
```

**AFTER (Secure):**
```javascript
app.get('/users',
  authenticateToken,
  requireAdmin,
  [
    query('id').optional().isInt({ min: 1 }).toInt(),
    query('name').optional().isString().trim().isLength({ min: 1, max: 50 }).escape(),
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ error: 'Invalid input', details: errors.array() });
    }
    res.json({...});
  }
);
```

**Impact:** Prevents injection attacks ✅

---

### 3. SECURITY HEADERS

**BEFORE (Vulnerable):**
```javascript
// No security headers set
const app = express();
app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// Response headers:
// ❌ No Content-Security-Policy
// ❌ No X-Frame-Options
// ❌ No X-Content-Type-Options
// ❌ No HSTS
```

**AFTER (Secure):**
```javascript
const helmet = require('helmet');

app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// Response headers:
// ✅ Content-Security-Policy: default-src 'self'
// ✅ X-Frame-Options: DENY
// ✅ X-Content-Type-Options: nosniff
// ✅ Strict-Transport-Security: max-age=31536000
// ✅ X-XSS-Protection: 1; mode=block
```

**Impact:** Prevents XSS, clickjacking, MIME sniffing attacks ✅

---

### 4. RATE LIMITING

**BEFORE (Vulnerable):**
```javascript
// No rate limiting
// Brute force attacks possible
app.get('/users', (req, res) => {
  res.json([...]);
});

app.listen(3000);  // Can be hammered with requests
```

**AFTER (Secure):**
```javascript
const rateLimit = require('express-rate-limit');

const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,  // 15 minutes
  max: 100,                   // 100 requests per window
  message: 'Too many requests, try again later',
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,  // Stricter limit for auth
  skipSuccessfulRequests: true,
});

app.use(generalLimiter);
app.post('/login', authLimiter, handleLogin);
```

**Impact:** Prevents brute force and DoS attacks ✅

---

### 5. REQUEST SIZE LIMITS

**BEFORE (Vulnerable):**
```javascript
const express = require('express');
const app = express();

// Default body parser (unlimited size)
// Susceptible to large payload attacks
app.post('/data', (req, res) => {
  res.json({ received: req.body });
});
```

**AFTER (Secure):**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Large payloads now rejected with 413 Payload Too Large
```

**Impact:** Prevents request smuggling and memory exhaustion ✅

---

### 6. ERROR HANDLING

**BEFORE (Vulnerable):**
```javascript
// Default error handling
app.get('/users', (req, res) => {
  res.json([...]);
});

// If error occurs:
// ❌ Stack trace exposed
// ❌ Internal details leaked
// ❌ No error code for debugging
// ❌ No log for security monitoring
```

**AFTER (Secure):**
```javascript
// Global error handler
app.use((err, req, res, next) => {
  console.error(`[ERROR] ${err.message}`, {
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip,
  });

  const status = err.status || 500;
  const response = {
    error: status === 500 ? 'Internal Server Error' : err.message,
    code: err.code || 'UNKNOWN_ERROR',
  };

  res.status(status).json(response);
});

// Result:
// ✅ Generic error message in production
// ✅ Detailed logging server-side only
// ✅ No stack traces exposed
// ✅ Consistent error format
```

**Impact:** Prevents information disclosure ✅

---

### 7. HTTPS/TLS

**BEFORE (Vulnerable):**
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// ❌ Running on HTTP
// ❌ Traffic unencrypted
// ❌ MITM attacks possible
// ❌ Tokens/passwords exposed in transit
```

**AFTER (Secure):**
```javascript
const https = require('https');
const fs = require('fs');

if (process.env.NODE_ENV === 'production' && 
    process.env.SSL_KEY_PATH && 
    process.env.SSL_CERT_PATH) {

  const options = {
    key: fs.readFileSync(process.env.SSL_KEY_PATH),
    cert: fs.readFileSync(process.env.SSL_CERT_PATH),
  };

  https.createServer(options, app).listen(PORT, () => {
    console.log(`🔒 Secure server running on port ${PORT}`);
  });
}

// ✅ HTTPS enabled in production
// ✅ Traffic encrypted
// ✅ MITM attacks prevented
// ✅ Tokens/passwords protected
```

**Impact:** Encrypts all traffic ✅

---

### 8. CORS CONFIGURATION

**BEFORE (Vulnerable):**
```javascript
// No CORS configuration
// Default Express behavior may be too permissive
// Any origin might be able to access

app.get('/users', (req, res) => {
  res.json([...]);
});
```

**AFTER (Secure):**
```javascript
const cors = require('cors');

const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
};

app.use(cors(corsOptions));

// ✅ Only whitelisted origins allowed
// ✅ Configurable per environment
// ✅ Credentials properly handled
```

**Impact:** Prevents unauthorized cross-origin access ✅

---

### 9. DATA EXPOSURE

**BEFORE (Vulnerable):**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },  // ❌ Email exposed
    { id: 2, name: 'Bob', email: 'bob@example.com' },      // ❌ Email exposed
  ]);
});

// ❌ No access control
// ❌ All data exposed to anyone
// ❌ Email harvesting possible
```

**AFTER (Secure):**
```javascript
app.get('/users',
  authenticateToken,
  requireAdmin,  // ✅ Authorization check
  (req, res) => {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
    ];

    // ✅ Return only necessary fields
    const sanitizedUsers = users.map(u => ({
      id: u.id,
      name: u.name,
      // email intentionally omitted unless required
    }));

    res.json({
      success: true,
      data: sanitizedUsers,
      count: sanitizedUsers.length,
    });
  }
);
```

**Impact:** Prevents data exposure and privacy violations ✅

---

### 10. LOGGING & MONITORING

**BEFORE (Vulnerable):**
```javascript
// Minimal logging
app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// ❌ No security event tracking
// ❌ No audit trail
// ❌ Attacks go undetected
// ❌ No incident investigation data
```

**AFTER (Secure):**
```javascript
const morgan = require('morgan');

app.use(morgan('combined'));

app.use((req, res, next) => {
  const startTime = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - startTime;
    const logLevel = res.statusCode >= 400 ? 'WARN' : 'INFO';

    console.log(`[${logLevel}] ${req.method} ${req.path} - ${res.statusCode} (${duration}ms) - IP: ${req.ip}`);

    // ✅ Log security events
    if (res.statusCode === 401 || res.statusCode === 403) {
      console.log(`[SECURITY] Unauthorized access: ${req.method} ${req.path} from ${req.ip}`);
    }
  });

  next();
});

// ✅ Comprehensive logging
// ✅ Security event tracking
// ✅ Audit trail available
// ✅ Attack detection possible
```

**Impact:** Enables incident detection and response ✅

---

### 11. ENVIRONMENT CONFIGURATION

**BEFORE (Vulnerable):**
```javascript
const express = require('express');
const app = express();

// Hard-coded configuration
app.listen(3000);  // ❌ Port hard-coded

// Would need to change code to deploy differently
// Secrets exposed in repository
// Difficult to manage multiple environments
```

**AFTER (Secure):**
```javascript
require('dotenv').config();

const config = {
  port: process.env.PORT || 3000,
  nodeEnv: process.env.NODE_ENV || 'development',
  jwtSecret: process.env.JWT_SECRET,
  dbUrl: process.env.DATABASE_URL,
  allowedOrigins: process.env.ALLOWED_ORIGINS?.split(','),
};

if (process.env.NODE_ENV === 'production') {
  const requiredVars = ['JWT_SECRET', 'DATABASE_URL'];
  const missing = requiredVars.filter(v => !process.env[v]);
  if (missing.length > 0) {
    throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
  }
}

// ✅ Configuration from environment
// ✅ Different configs per environment
// ✅ Secrets not in repository
// ✅ Required config validation
```

**Impact:** Prevents secret exposure and configuration errors ✅

---

## Security Metrics

