 * 3. Deploy with AWS SDK configured
 */

const AWSSecretsManager = () => {
  const AWS = require('aws-sdk');
  const client = new AWS.SecretsManager({ region: process.env.AWS_REGION || 'us-east-1' });

  const secretCache = new Map();
  const CACHE_TTL = 3600000; // 1 hour

  return {
    /**
     * Get secret from AWS Secrets Manager with caching
     */
    async getSecret(secretName) {
      const cacheKey = secretName;
      const cached = secretCache.get(cacheKey);

      // Return cached secret if not expired
      if (cached && Date.now() - cached.timestamp < CACHE_TTL) {
        console.log(`[SECRETS] Cache hit for ${secretName}`);
        return cached.value;
      }

      try {
        console.log(`[SECRETS] Fetching ${secretName} from AWS Secrets Manager`);

        const response = await client.getSecretValue({ SecretId: secretName }).promise();

        let secretValue;
        if ('SecretString' in response) {
          secretValue = JSON.parse(response.SecretString);
        } else {
          secretValue = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
        }

        // Cache the secret
        secretCache.set(cacheKey, {
          value: secretValue,
          timestamp: Date.now(),
          version: response.VersionId,
        });

        console.log(`[SECRETS] Successfully retrieved ${secretName}`);
        return secretValue;

      } catch (error) {
        console.error(`[SECRETS] Failed to retrieve ${secretName}:`, error.message);
        throw new Error(`CRITICAL: Cannot load secret ${secretName} from AWS`);
      }
    },

    /**
     * Clear cache to force refresh
     */
    clearCache(secretName) {
      if (secretName) {
        secretCache.delete(secretName);
        console.log(`[SECRETS] Cleared cache for ${secretName}`);
      } else {
        secretCache.clear();
        console.log(`[SECRETS] Cleared all secret caches`);
      }
    },

    /**
     * Watch for secret changes and reload
     */
    watchSecret(secretName, onUpdate) {
      setInterval(async () => {
