// Secure version of the application with security best practices implemented

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const cors = require('cors');
const app = express();

// ========== SECURITY MIDDLEWARE ==========

// 1. HELMET - Sets various HTTP headers to protect against common vulnerabilities
app.use(helmet());

// 2. CORS - Restrict cross-origin requests
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
};
app.use(cors(corsOptions));

// 3. RATE LIMITING - Prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});
app.use(limiter);

// 4. BODY PARSER - Parse incoming request bodies with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 5. DATA SANITIZATION - Prevent NoSQL injection and XSS attacks
app.use(mongoSanitize()); // Removes $ and . from user inputs
app.use(xss()); // Sanitizes user inputs

// ========== AUTHENTICATION MIDDLEWARE ==========

// Simple API key authentication (in production, use OAuth2, JWT, etc.)
