## Security Middleware Stack

### Minimal Setup (Essential)
```javascript
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
require('dotenv').config();

const app = express();

// 1. Security headers
app.use(helmet());

// 2. CORS
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(','),
  credentials: true
}));

// 3. Rate limiting
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
}));

// 4. Body parsing with limits
app.use(express.json({ limit: '10kb' }));
```

### Production Setup (Recommended)
```javascript
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { authenticateToken } = require('./middleware/auth');
require('dotenv').config();

const app = express();

// Security headers
app.use(helmet());

// CORS with whitelist
app.use(cors({
  origin: (origin, callback) => {
    const allowed = process.env.ALLOWED_ORIGINS?.split(',');
    if (!origin || allowed.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('CORS blocked'));
    }
  }
}));

// Request logging
app.use(morgan('combined'));

// Rate limiting
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests'
}));

// Payload limits
app.use(express.json({ limit: '10kb' }));

// Authentication
app.use(authenticateToken);

// Error handling
app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({ 
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal Server Error' 
      : err.message 
  });
});
```

## Common Vulnerability Fixes

### Fix 1: Add Authentication
```javascript
// BEFORE (Vulnerable)
app.get('/users', (req, res) => {
  res.json(users);
});

// AFTER (Secure)
const { authenticateToken } = require('./middleware/auth');

app.get('/users', authenticateToken, (req, res) => {
  res.json(users);
});
```

### Fix 2: Add Input Validation
```javascript
// BEFORE (Vulnerable)
app.get('/users', (req, res) => {
  const userId = req.query.userId; // No validation!
  res.json(getUser(userId));
});

// AFTER (Secure)
const { query, validationResult } = require('express-validator');

app.get('/users', [
  query('userId').isInt().toInt()
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  res.json(getUser(req.query.userId));
});
```

### Fix 3: Add Rate Limiting to Auth
```javascript
// BEFORE (Vulnerable to brute force)
app.post('/login', (req, res) => {
  // Unlimited login attempts!
});

// AFTER (Secure)
const rateLimit = require('express-rate-limit');

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 attempts per 15 minutes
  skipSuccessfulRequests: true
});

app.post('/login', authLimiter, (req, res) => {
  // Protected from brute force
});
```

### Fix 4: Add Error Handling
```javascript
// BEFORE (Vulnerable - leaks errors)
app.get('/users', (req, res) => {
  try {
    res.json(getUsers());
  } catch (err) {
    res.status(500).json(err); // Sends stack trace!
  }
});

// AFTER (Secure - hides errors)
app.get('/users', (req, res, next) => {
  try {
    res.json(getUsers());
  } catch (err) {
    console.error(err); // Log for debugging
    res.status(500).json({ 
      error: 'Internal Server Error' 
    });
  }
});
```

### Fix 5: Add HTTPS Redirect
```javascript
// BEFORE
app.listen(3000);

// AFTER
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure) {
    return res.redirect(301, `https://${req.get('host')}${req.originalUrl}`);
  }
  next();
});

app.listen(3000);
```

