- `/users` endpoint exposes sensitive user data (emails) without any authentication
- No role-based access control (RBAC)
- No API key validation
- Sensitive PII is publicly accessible

**Risk:** Unauthorized access to user database

**Recommended Fix:**
```javascript
const express = require('express');
const jwt = require('jsonwebtoken');
const app = express();

// Middleware: JWT Authentication
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
}

// Middleware: Role-based authorization
function authorize(requiredRole) {
  return (req, res, next) => {
    if (!req.user || req.user.role !== requiredRole) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
}

// Protected endpoint
app.get('/users', authenticateToken, authorize('admin'), (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

