### 2. **MISSING INPUT VALIDATION & SANITIZATION** ⚠️ HIGH
**OWASP Top 10: A03:2021 – Injection**

**Issue:**
- No validation on query parameters or request body
- No sanitization of user inputs
- Query parameters could be exploited for injection attacks
- If app was extended with POST/PUT endpoints, data wouldn't be validated

**Risk:** SQL Injection, NoSQL Injection, XSS, command injection

**Recommended Fix:**
```javascript
const express = require('express');
const { query, body, validationResult } = require('express-validator');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const app = express();

// Input sanitization middleware
app.use(mongoSanitize()); // Prevents NoSQL injection
app.use(xss()); // Prevents XSS attacks

// Validation middleware for query parameters
app.get('/users', 
  query('filter').optional().trim().escape().isLength({ max: 50 }),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('offset').optional().isInt({ min: 0 }).toInt(),
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { limit = 10, offset = 0 } = req.query;
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  }
);

// Example POST endpoint with validation
app.post('/users',
  body('name').trim().notEmpty().isLength({ min: 2, max: 100 }),
  body('email').isEmail().normalizeEmail(),
  body('age').optional().isInt({ min: 0, max: 150 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Safe to use req.body
    res.status(201).json({ success: true });
  }
);
```

