```javascript
// secrets-manager.js
const AWS = require('aws-sdk');

class SecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = {};
    this.cacheExpiry = 3600000; // 1 hour
  }

  async getSecrets(secretName, useCache = true) {
    const cacheKey = secretName;

    // Return cached secrets if still valid
    if (useCache && this.cache[cacheKey]) {
      const { data, timestamp } = this.cache[cacheKey];
      if (Date.now() - timestamp < this.cacheExpiry) {
        console.log(`[SECRETS] Returning cached secrets for ${secretName}`);
        return data;
      }
    }

    try {
      console.log(`[SECRETS] Fetching ${secretName} from AWS Secrets Manager`);
      const data = await this.client.getSecretValue({
        SecretId: secretName
      }).promise();

      let secretValue;
      if ('SecretString' in data) {
        secretValue = JSON.parse(data.SecretString);
      } else {
        secretValue = Buffer.from(data.SecretBinary, 'base64');
      }

      // Cache the result
      this.cache[cacheKey] = {
        data: secretValue,
        timestamp: Date.now()
      };

      return secretValue;
    } catch (error) {
      console.error(`[ERROR] Failed to retrieve secret ${secretName}:`, error.message);

      // If secret can't be loaded, fail fast
      if (process.env.NODE_ENV === 'production') {
        throw new Error(`Cannot load required secrets: ${error.message}`);
      }

      // In development, return defaults
      console.warn('[WARNING] Using fallback secrets from environment');
      return null;
    }
  }

  // Invalidate cache (useful after rotation)
  invalidateCache(secretName) {
    if (secretName) {
      delete this.cache[secretName];
    } else {
      this.cache = {};
    }
  }
}

module.exports = new SecretsManager();
```

