const AWS = require('aws-sdk');
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ],
});

class AWSSecretsManager {
  constructor(options = {}) {
    this.region = options.region || process.env.AWS_REGION || 'us-east-1';
    this.cacheExpiry = options.cacheExpiry || 3600000; // 1 hour default
    this.cache = new Map();

    this.client = new AWS.SecretsManager({
      region: this.region
    });
  }

  /**
   * Get secret from AWS Secrets Manager
   * @param {string} secretId - Secret identifier
   * @param {boolean} useCache - Whether to use cache
   * @returns {Promise<Object>} Secret value
   */
  async getSecret(secretId, useCache = true) {
    try {
      // Check cache first
      if (useCache && this.cache.has(secretId)) {
        const cached = this.cache.get(secretId);
        if (Date.now() - cached.timestamp < this.cacheExpiry) {
          logger.debug(`[CACHE HIT] Secret: ${secretId}`);
          return cached.value;
        }
        this.cache.delete(secretId);
      }

      logger.info(`[SECRETS] Fetching secret from AWS: ${secretId}`);

      const response = await this.client.getSecretValue({
        SecretId: secretId
      }).promise();

      let secret;
      if ('SecretString' in response) {
        secret = JSON.parse(response.SecretString);
      } else {
        secret = Buffer.from(response.SecretBinary, 'base64');
      }

      // Cache the result
      if (useCache) {
        this.cache.set(secretId, {
          value: secret,
          timestamp: Date.now()
        });
      }

      logger.info(`[SECRETS] Successfully loaded secret: ${secretId}`);
      return secret;
    } catch (error) {
      logger.error(`[ERROR] Failed to retrieve secret ${secretId}: ${error.message}`);
      throw new Error(`Cannot load secret ${secretId}: ${error.message}`);
    }
  }

  /**
   * Get multiple secrets in parallel
   * @param {string[]} secretIds - Array of secret identifiers
   * @returns {Promise<Object>} Object with all secrets
   */
  async getSecrets(secretIds) {
    try {
      const promises = secretIds.map(id => 
        this.getSecret(id, true)
      );
      const results = await Promise.all(promises);

      const secrets = {};
      secretIds.forEach((id, index) => {
        secrets[id] = results[index];
      });

      return secrets;
    } catch (error) {
      logger.error(`[ERROR] Failed to retrieve multiple secrets: ${error.message}`);
      throw error;
    }
  }

  /**
   * Invalidate cache for a secret (useful after rotation)
   * @param {string} secretId - Secret identifier (null = all)
   */
  invalidateCache(secretId = null) {
    if (secretId) {
      this.cache.delete(secretId);
      logger.info(`[CACHE] Invalidated cache for: ${secretId}`);
    } else {
      this.cache.clear();
      logger.info(`[CACHE] Cleared all cached secrets`);
    }
  }

  /**
   * Validate secret has required fields
   * @param {Object} secret - Secret object
   * @param {string[]} requiredFields - Required field names
   * @returns {boolean}
   */
  validateSecret(secret, requiredFields = []) {
    if (!secret || typeof secret !== 'object') {
      throw new Error('Secret must be an object');
    }

    const missing = requiredFields.filter(field => !(field in secret));
    if (missing.length > 0) {
      throw new Error(`Secret missing required fields: ${missing.join(', ')}`);
    }

    return true;
  }
}

