/**
 * Secure secrets loading from AWS Secrets Manager
 * - Encrypted at rest with KMS
 * - Access controlled via IAM
 * - Audit logged to CloudTrail
 * - Can be rotated automatically
 */

const AWS = require('aws-sdk');

class AWSSecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager({ region: process.env.AWS_REGION });
    this.cache = new Map();
    this.cacheExpiry = 3600000; // 1 hour
  }

  async getSecret(secretId, useCache = true) {
    // Check cache first
    if (useCache && this.cache.has(secretId)) {
      const cached = this.cache.get(secretId);
      if (Date.now() - cached.timestamp < this.cacheExpiry) {
        return cached.value;
      }
      this.cache.delete(secretId);
    }

    try {
      // Fetch from AWS Secrets Manager
      const response = await this.client.getSecretValue({
        SecretId: secretId
      }).promise();

      let secret;
      if ('SecretString' in response) {
        secret = JSON.parse(response.SecretString);
      } else {
        secret = Buffer.from(response.SecretBinary, 'base64');
      }

      // Cache in memory
      this.cache.set(secretId, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      throw new Error(`Cannot load secret: ${error.message}`);
    }
  }

  invalidateCache(secretId) {
    if (secretId) {
      this.cache.delete(secretId);
    } else {
      this.cache.clear();
    }
  }
}

module.exports = new AWSSecretsManager();
