### **SOLUTION 1: AWS SECRETS MANAGER**

**Recommended for:** AWS-based deployments

```javascript
// config/secrets.js
const AWS = require('aws-sdk');
const client = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

let secretsCache = {};
const CACHE_DURATION = 5 * 60 * 1000; // 5 minutes
let lastFetch = 0;

async function getSecrets() {
  const now = Date.now();

  // Return cached secrets if fresh
  if (secretsCache && (now - lastFetch) < CACHE_DURATION) {
    return secretsCache;
  }

  try {
    const secretName = process.env.SECRETS_NAME || 'app-secrets';

    const data = await client.getSecretValue({
      SecretId: secretName
    }).promise();

    // SecretString is a JSON string, SecretBinary is binary
    const secretString = data.SecretString || Buffer.from(data.SecretBinary, 'base64').toString();
    secretsCache = JSON.parse(secretString);
    lastFetch = now;

    return secretsCache;
  } catch (error) {
    console.error('Failed to retrieve secrets:', error.message);
    throw new Error('Cannot load application secrets');
  }
}

module.exports = { getSecrets };
```

