/**
 * SECURE SECRETS MANAGER - Abstraction Layer
 * 
 * This module provides a unified interface for loading secrets from different
 * sources based on the environment:
 * - Production: AWS Secrets Manager
 * - Development: .env files
 * - Test: In-memory or test values
 */

const AWS = require('aws-sdk');

// Initialize AWS SDK with region
const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

// Cache for secrets (not in production - too risky)
let secretsCache = {};
const CACHE_DURATION = 3600000; // 1 hour in milliseconds
let cacheTime = {};

/**
 * Retrieve a secret from the appropriate source
 * @param {string} secretName - Name of the secret
 * @returns {Promise<any>} - The secret value
 */
async function getSecret(secretName) {
  const env = process.env.NODE_ENV || 'development';

  // Production: Use AWS Secrets Manager
  if (env === 'production') {
    return getSecretFromAWS(secretName);
  }

  // Development: Use .env files
  if (env === 'development') {
    return getSecretFromEnv(secretName);
  }

  // Test: Use test values or environment
  if (env === 'test') {
    return getSecretFromEnv(secretName) || `test-${secretName}`;
  }

  throw new Error(`Unknown environment: ${env}`);
}

/**
 * Retrieve secret from AWS Secrets Manager with caching
 */
async function getSecretFromAWS(secretName) {
  try {
    // Check cache first
    const cached = secretsCache[secretName];
    if (cached && Date.now() - cacheTime[secretName] < CACHE_DURATION) {
      console.log(`[CACHE HIT] Retrieved ${secretName} from cache`);
      return cached;
    }

    console.log(`[AWS] Retrieving secret: ${secretName}`);

    const data = await secretsManager
      .getSecretValue({ SecretId: secretName })
      .promise();

    let secretValue;
    if ('SecretString' in data) {
      try {
        secretValue = JSON.parse(data.SecretString);
      } catch (e) {
        // If not JSON, treat as plain string
        secretValue = data.SecretString;
      }
    } else {
      secretValue = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
    }

    // Cache the secret
    secretsCache[secretName] = secretValue;
    cacheTime[secretName] = Date.now();

    return secretValue;
  } catch (error) {
    console.error(`Failed to retrieve secret from AWS: ${secretName}`, error);
    throw new Error(
      `Failed to retrieve secret: ${secretName}. ` +
      `Ensure the secret exists in AWS Secrets Manager and your IAM role has permission.`
    );
  }
}

/**
 * Retrieve secret from environment variables (.env file)
 */
function getSecretFromEnv(secretName) {
  const value = process.env[secretName];

  if (!value) {
    const env = process.env.NODE_ENV || 'development';
    if (env === 'production') {
      throw new Error(
        `Missing required secret in production: ${secretName}. ` +
        `This secret must be configured in AWS Secrets Manager.`
      );
    }
    console.warn(`[WARNING] Missing secret in .env file: ${secretName}`);
    return null;
  }

  return value;
}

/**
 * Retrieve multiple secrets at once
 */
async function getSecrets(secretNames) {
  const secrets = {};

  for (const name of secretNames) {
    secrets[name] = await getSecret(name);
  }

  return secrets;
}

/**
 * Validate that all required secrets are available
 */
async function validateSecrets(requiredSecrets) {
  const missing = [];

  for (const secret of requiredSecrets) {
    try {
      await getSecret(secret);
    } catch (error) {
      missing.push(secret);
    }
  }

  if (missing.length > 0) {
    throw new Error(
      `Missing required secrets: ${missing.join(', ')}. ` +
      `Please configure these in your environment or AWS Secrets Manager.`
    );
  }
}

/**
 * Clear the secrets cache (useful for testing or secret rotation)
 */
function clearSecretCache() {
  secretsCache = {};
  cacheTime = {};
  console.log('[INFO] Secrets cache cleared');
}

module.exports = {
  getSecret,
  getSecrets,
  validateSecrets,
  clearSecretCache
};

/**
 * SECURE APPLICATION WITH PROPER SECRETS MANAGEMENT
 * 
 * This version implements:
 * - AWS Secrets Manager for production
 * - .env file support for local development
 * - Proper error handling
 * - Security headers and middleware
 * - No hardcoded secrets
