          .getSecretValue({ SecretId: secretName })
          .promise();

        const secretValue = 'SecretString' in data 
          ? JSON.parse(data.SecretString)
          : Buffer.from(data.SecretBinary, 'base64').toString('ascii');

        return { [secretName]: secretValue };
      } catch (error) {
        console.error(`Failed to load secret ${secretName}:`, error.message);
        throw error;
      }
    });

    const loadedSecrets = await Promise.all(secretPromises);
    secrets = Object.assign({}, ...loadedSecrets);

