**Recommended Fix:**
```javascript
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');

// Security headers and HTTPS enforcement
app.use(helmet());

// Rate limiting for sensitive endpoints
const usersLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per window
  message: 'Too many requests, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
});

app.get('/users', authenticateToken, usersLimiter, (req, res) => {
  // Only return necessary fields based on user role
  const users = getUsersList();

  // Data minimization: only include necessary fields
  if (req.user.isAdmin) {
    res.json(users); // Admins see all data
  } else {
    // Regular users only see anonymized data
    res.json(users.map(u => ({
      id: u.id,
      name: u.name
      // email is NOT included
    })));
