 * Protected: Requires authentication
 * Authorization: Admins see all data, users see anonymized data
 */
app.get('/users',
  authenticateToken,
  generalLimiter,
  (req, res, next) => {
    try {
      // Audit log for sensitive operation
      logger.info({
        event: 'USERS_LIST_ACCESSED',
        userId: req.user.id,
        isAdmin: req.user.isAdmin,
        timestamp: new Date().toISOString(),
      });

      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
        { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
      ];

      // Data minimization: Only return necessary fields based on user role
      if (req.user.isAdmin) {
        return res.json(users); // Admins see all data
      } else {
        // Regular users only see anonymized data (no emails)
        const anonymizedUsers = users.map(u => ({
          id: u.id,
          name: u.name,
          role: u.role,
        }));
        return res.json(anonymizedUsers);
      }
    } catch (err) {
      next(err);
    }
  }
);

/**
 * Get specific user by ID endpoint
 * Protected: Requires authentication
 * Validation: ID must be a positive integer
 */
app.get('/users/:id',
  authenticateToken,
  param('id')
    .isInt({ min: 1 })
    .withMessage('Invalid user ID - must be a positive integer'),
  (req, res, next) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        logger.warn(`Invalid user ID parameter: ${req.params.id}`);
        return res.status(400).json({ errors: errors.array() });
      }

      const userId = parseInt(req.params.id, 10);
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
        { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        logger.warn(`User not found: ${userId}`);
        return res.status(404).json({ error: 'User not found' });
      }

      // Check authorization: users can only view their own data
      if (!req.user.isAdmin && req.user.id !== userId) {
        logger.warn(`Unauthorized access attempt by user ${req.user.id} to user ${userId}`);
        return res.status(403).json({ error: 'Insufficient permissions' });
      }

      logger.info({
        event: 'USER_VIEWED',
        requestedUserId: userId,
        requestingUserId: req.user.id,
      });

      res.json(user);
    } catch (err) {
      next(err);
    }
  }
);

/**
 * Create new user endpoint
 * Protected: Requires authentication and admin privileges
 * Validation: Input validation on name and email
 */
app.post('/users',
  strictLimiter,
  authenticateToken,
  requireAdmin,
  express.json(),
  query('name')
    .trim()
    .notEmpty()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be 1-100 characters')
    .escape(), // Prevent XSS
  query('email')
    .isEmail()
    .normalizeEmail()
    .withMessage('Invalid email format'),
  (req, res, next) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        logger.warn(`Validation error on user creation`, errors.array());
        return res.status(400).json({ errors: errors.array() });
      }

      const { name, email } = req.query;

      // Simulate user creation
      const newUser = {
        id: Date.now(), // Simple ID generation
        name,
        email,
        role: 'user',
        createdAt: new Date().toISOString(),
        createdBy: req.user.id,
      };

      logger.info({
        event: 'USER_CREATED',
        userId: newUser.id,
        createdBy: req.user.id,
      });

      res.status(201).json(newUser);
    } catch (err) {
      next(err);
    }
  }
);

// ============================================================================
// ERROR HANDLING
// ============================================================================

/**
 * Global error handling middleware
 * Catches all errors and returns appropriate response
 */
app.use((err, req, res, next) => {
  // Log error on server side
  logger.error({
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    userId: req.user?.id || 'anonymous',
  });

  // Send generic error to client (don't expose internals)
  const statusCode = err.statusCode || 500;
  const response = {
    error: process.env.NODE_ENV === 'production'
      ? 'An error occurred processing your request'
      : err.message,
  };

  // Only include stack trace in development
  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

/**
 * 404 handler
 */
app.use((req, res) => {
  logger.warn(`Not found: ${req.method} ${req.path}`);
  res.status(404).json({ error: 'Not found' });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  logger.info('SIGINT received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

module.exports = app;

