/**
 * SECURE VERSION - app.js
 * 
 * This version implements security best practices addressing:
 * - Authentication & Authorization (OWASP A01:2021)
 * - Input Validation (OWASP A03:2021)
 * - Security Misconfiguration (OWASP A05:2021)
 * - Logging & Monitoring (OWASP A09:2021)
 */

require('dotenv').config();
const express = require('express');
const jwt = require('jsonwebtoken');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { v4: uuidv4 } = require('uuid');
const { query, param, validationResult } = require('express-validator');

const app = express();

// ============================================================================
// REQUEST ID MIDDLEWARE (for tracking)
// ============================================================================
app.use((req, res, next) => {
  req.id = uuidv4();
  res.setHeader('X-Request-ID', req.id);
  next();
});

// ============================================================================
// SECURITY HEADERS (OWASP A05:2021)
// ============================================================================
app.use(helmet());

// ============================================================================
// INPUT PARSING WITH SIZE LIMITS (OWASP A05:2021)
// ============================================================================
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// ============================================================================
// CORS CONFIGURATION (OWASP A05:2021)
// ============================================================================
const corsOptions = {
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  exposedHeaders: ['X-Request-ID'],
  maxAge: 600,
};

app.use(cors(corsOptions));

// ============================================================================
// RATE LIMITING (OWASP A04:2021)
// ============================================================================
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => {
    // Skip rate limiting for health checks in production
    return process.env.NODE_ENV === 'production' && req.path === '/health';
  },
});

const strictLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 10,
  skipSuccessfulRequests: false,
});

app.use(globalLimiter);

// ============================================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================================
const authenticateToken = (req, res, next) => {
  try {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1];

    if (!token) {
      return res.status(401).json({
        error: 'Access token required',
        requestId: req.id,
      });
    }

    jwt.verify(token, process.env.ACCESS_TOKEN_SECRET, (err, user) => {
      if (err) {
        return res.status(403).json({
          error: 'Invalid or expired token',
          requestId: req.id,
        });
      }
      req.user = user;
      next();
    });
  } catch (err) {
    logSecurityEvent('AUTH_ERROR', { error: err.message }, req);
    res.status(500).json({
      error: 'Authentication failed',
      requestId: req.id,
    });
  }
};

// ============================================================================
// LOGGING & MONITORING (OWASP A09:2021)
// ============================================================================
const logSecurityEvent = (eventType, details, req) => {
  const logEntry = {
    timestamp: new Date().toISOString(),
    requestId: req.id,
    eventType,
    path: req.path,
    method: req.method,
    ip: req.ip,
    userAgent: req.get('user-agent'),
    userId: req.user?.id,
    ...details,
  };

  if (eventType.includes('ERROR') || eventType.includes('FAILED')) {
    console.error('[SECURITY]', JSON.stringify(logEntry));
  } else {
    console.warn('[SECURITY]', JSON.stringify(logEntry));
  }
};

// ============================================================================
// ENDPOINTS
// ============================================================================

/**
 * Health Check Endpoint
 * No authentication required but rate limited
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    requestId: req.id,
  });
});

/**
 * Get Users Endpoint
 * Requires authentication, validates input, applies strict rate limiting
 */
app.get('/users', authenticateToken, strictLimiter, (req, res) => {
  try {
    logSecurityEvent('USER_LIST_ACCESSED', {
      userId: req.user.id,
      role: req.user.role,
    }, req);

    // Data sanitization - only expose necessary fields based on role
    let users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];

    // Only admins get email addresses
    if (req.user.role === 'admin') {
      users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];
    }

    res.json({
      data: users,
      requestId: req.id,
    });
  } catch (err) {
    logSecurityEvent('USER_LIST_ERROR', { error: err.message }, req);
    res.status(500).json({
      error: 'Internal Server Error',
      requestId: req.id,
    });
  }
});

/**
 * Get User by ID Endpoint
 * Input validation example (OWASP A03:2021)
 */
app.get('/users/:id',
  authenticateToken,
  strictLimiter,
  param('id')
    .isInt({ min: 1 })
    .withMessage('User ID must be a positive integer'),
  (req, res) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        logSecurityEvent('VALIDATION_FAILED', {
          endpoint: '/users/:id',
          errors: errors.array(),
        }, req);
        return res.status(400).json({ errors: errors.array() });
      }

      const userId = parseInt(req.params.id, 10);

      logSecurityEvent('USER_RETRIEVED', {
        userId: req.user.id,
        targetUserId: userId,
      }, req);

      // Simulated user lookup
      const user = userId === 1 
        ? { id: 1, name: 'Alice' }
        : userId === 2
        ? { id: 2, name: 'Bob' }
        : null;

      if (!user) {
        return res.status(404).json({
          error: 'User not found',
          requestId: req.id,
        });
      }

      res.json({
        data: user,
        requestId: req.id,
      });
    } catch (err) {
      logSecurityEvent('USER_RETRIEVAL_ERROR', { error: err.message }, req);
      res.status(500).json({
        error: 'Internal Server Error',
        requestId: req.id,
      });
    }
  }
);

/**
 * Login Endpoint (Example)
 * Generates JWT token for authentication
 */
app.post('/login', express.json(), async (req, res) => {
  try {
    const { username, password } = req.body;

    // Validate input
    if (!username || !password) {
      logSecurityEvent('LOGIN_FAILED', {
        reason: 'Missing credentials',
        username,
      }, req);
      return res.status(400).json({
        error: 'Username and password required',
        requestId: req.id,
      });
    }

    // IMPORTANT: This is a simplified example
    // In production, use bcrypt for password hashing and database lookups
    if (username === 'admin' && password === process.env.ADMIN_PASSWORD) {
      const user = {
        id: 1,
        username: 'admin',
        role: 'admin',
      };

      const token = jwt.sign(user, process.env.ACCESS_TOKEN_SECRET, {
        expiresIn: '1h',
      });

      logSecurityEvent('LOGIN_SUCCESS', { username }, req);

      return res.json({
        token,
        expiresIn: 3600,
        requestId: req.id,
      });
    }

    logSecurityEvent('LOGIN_FAILED', {
      reason: 'Invalid credentials',
      username,
    }, req);

    res.status(401).json({
      error: 'Invalid credentials',
      requestId: req.id,
    });
  } catch (err) {
    logSecurityEvent('LOGIN_ERROR', { error: err.message }, req);
    res.status(500).json({
      error: 'Internal Server Error',
      requestId: req.id,
    });
  }
});

// ============================================================================
// 404 HANDLER
// ============================================================================
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    requestId: req.id,
  });
});

// ============================================================================
// GLOBAL ERROR HANDLER (OWASP A01:2021)
// ============================================================================
app.use((err, req, res, next) => {
  const statusCode = err.statusCode || 500;
  const message = statusCode === 500
    ? 'Internal Server Error'
    : err.message;

  console.error('[ERROR]', {
    timestamp: new Date().toISOString(),
    requestId: req.id,
    statusCode,
    message: err.message,
    path: req.path,
    // Don't log stack trace to client, only to server logs
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
  });

  res.status(statusCode).json({
    error: message,
    requestId: req.id,
  });
});

// ============================================================================
// UNHANDLED REJECTION & EXCEPTION HANDLERS
// ============================================================================
process.on('unhandledRejection', (reason, promise) => {
  console.error('[UNHANDLED_REJECTION]', {
    timestamp: new Date().toISOString(),
    reason,
    promise,
  });
});

process.on('uncaughtException', (err) => {
  console.error('[UNCAUGHT_EXCEPTION]', {
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: err.stack,
  });
  process.exit(1);
});

// ============================================================================
// SERVER STARTUP
// ============================================================================
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Validate required environment variables
if (NODE_ENV === 'production') {
  const requiredEnvVars = ['ACCESS_TOKEN_SECRET', 'ADMIN_PASSWORD'];
  const missing = requiredEnvVars.filter(v => !process.env[v]);
  if (missing.length > 0) {
    console.error('Missing required environment variables:', missing);
    process.exit(1);
  }
}

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
  console.log(`Request ID header: X-Request-ID`);
});

module.exports = app;
