### Phase 2: IMPLEMENT SECRETS MANAGER

#### Option A: AWS Secrets Manager (Recommended for AWS users)

```javascript
const AWS = require('aws-sdk');

const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

let secretsCache = null;

async function getSecret(secretName) {
  // Cache secrets to avoid repeated API calls
  if (secretsCache && secretsCache[secretName]) {
    return secretsCache[secretName];
  }

  try {
    const response = await secretsManager.getSecretValue({
      SecretId: secretName
    }).promise();

    if (!secretsCache) {
      secretsCache = {};
    }

    if ('SecretString' in response) {
      secretsCache[secretName] = JSON.parse(response.SecretString);
      return secretsCache[secretName];
    } else {
      // Binary secret
      return response.SecretBinary;
    }
  } catch (error) {
    console.error(`Failed to retrieve secret ${secretName}:`, error);
    throw error;
  }
}

// Usage
const dbSecret = await getSecret('prod/database/credentials');
const awsKeys = await getSecret('prod/aws/credentials');
const stripeKey = await getSecret('prod/stripe/api-key');
