### Phase 4: SECURE APP.JS IMPLEMENTATION

```javascript
require('dotenv').config({ path: `.env.${process.env.NODE_ENV || 'development'}` });

const express = require('express');
const helmet = require('helmet');

const app = express();
app.use(helmet());

// ============ SECRETS MANAGEMENT ============

class SecretsManager {
  constructor() {
    this.secrets = {};
    this.initialized = false;
  }

  async initialize() {
    if (this.initialized) return;

    const environment = process.env.NODE_ENV || 'development';

    if (environment === 'production') {
      // Production: Use AWS Secrets Manager
      await this.initializeFromAWS();
    } else if (environment === 'staging') {
      // Staging: Use Vault
      await this.initializeFromVault();
    } else {
      // Development: Use .env.local (not committed)
      this.initializeFromDotEnv();
    }

    this.initialized = true;
  }

  async initializeFromAWS() {
    const AWS = require('aws-sdk');
    const secretsManager = new AWS.SecretsManager();

    const requiredSecrets = [
      'prod/database/url',
      'prod/stripe/key',
      'prod/jwt/secret',
    ];

    for (const secretName of requiredSecrets) {
      try {
        const response = await secretsManager.getSecretValue({
          SecretId: secretName
        }).promise();

        this.secrets[secretName] = JSON.parse(response.SecretString);
      } catch (error) {
        throw new Error(`Failed to load secret ${secretName}: ${error.message}`);
      }
    }
  }

  async initializeFromVault() {
    const vault = require('node-vault')({
      endpoint: process.env.VAULT_ADDR,
      token: process.env.VAULT_TOKEN
    });

    const requiredSecrets = [
      'secret/data/staging/database',
      'secret/data/staging/stripe',
    ];

    for (const path of requiredSecrets) {
