/**
 * SECURE VERSION OF app.js
 * Implements security best practices and OWASP Top 10 protections
 */

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const winston = require('winston');
const mongoSanitize = require('express-mongo-sanitize');

const app = express();

// ============================================================================
// LOGGING SETUP
// ============================================================================
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'app' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

// ============================================================================
// SECURITY MIDDLEWARE - PART 1: HEADERS & BASIC PROTECTION
// ============================================================================

// Helmet: Set various HTTP headers
app.use(helmet());

// Additional custom security headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Content-Security-Policy', "default-src 'self'");
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  next();
});

// Enforce HTTPS in production
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure) {
    logger.warn(`Redirecting insecure request to ${req.path}`);
    return res.redirect(`https://${req.headers.host}${req.url}`);
  }
  next();
});

// ============================================================================
// SECURITY MIDDLEWARE - PART 2: DATA PARSING & VALIDATION
// ============================================================================

// Body parser with size limits to prevent DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Sanitize against NoSQL injection
app.use(mongoSanitize());

// ============================================================================
// SECURITY MIDDLEWARE - PART 3: CORS
// ============================================================================

const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'HEAD', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400, // 24 hours
  optionsSuccessStatus: 200
};

app.use(cors(corsOptions));
app.options('*', cors(corsOptions));

// ============================================================================
// SECURITY MIDDLEWARE - PART 4: RATE LIMITING
// ============================================================================

// General rate limiter for all endpoints
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    logger.warn(`Rate limit exceeded for IP: ${req.ip}`);
    res.status(429).json({
      error: 'Too many requests. Please try again later.'
    });
  }
});

app.use(limiter);

// Stricter rate limiter for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // 5 requests per 15 minutes
  skipSuccessfulRequests: true,
  message: 'Too many failed attempts, please try again later.'
});

// ============================================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================================

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn(`Missing token for ${req.path}`);
    return res.status(401).json({
      error: 'Access token required'
    });
  }

  jwt.verify(token, process.env.JWT_SECRET || 'dev-secret', (err, user) => {
    if (err) {
      logger.warn(`Invalid token: ${err.message}`);
      return res.status(403).json({
        error: 'Invalid or expired token'
      });
    }

    req.user = user;
    next();
  });
};

// ============================================================================
// ERROR HANDLING MIDDLEWARE (must be before routes)
// ============================================================================

const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ============================================================================
// ROUTES WITH SECURITY
// ============================================================================

/**
 * GET /health
 * Public endpoint to check server health
 */
app.get('/health', asyncHandler(async (req, res) => {
  logger.info('Health check');
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
}));

/**
 * GET /users
 * Protected endpoint to retrieve users
 * Query parameters: limit (1-100), offset (0+), search (max 50 chars)
 */
app.get('/users',
  authenticateToken,
