    .optional()
    .isIn(['name', 'email', 'id'])
    .withMessage('Sort field must be one of: name, email, id'),
  query('order')
    .optional()
    .isIn(['asc', 'desc'])
    .withMessage('Order must be asc or desc'),
  handleValidationErrors,
  (req, res) => {
    const { page = 1, limit = 10, sort = 'id', order = 'asc' } = req.query;

    logger.info(`User ${req.user.id} retrieved users list (page: ${page}, limit: ${limit})`);

    // Mock database data
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com', role: 'admin' },
    ];

    // Apply sorting
    const sorted = allUsers.sort((a, b) => {
      const aVal = a[sort];
      const bVal = b[sort];
      return order === 'asc'
        ? aVal > bVal ? 1 : -1
        : aVal < bVal ? 1 : -1;
    });

    // Apply pagination
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;
    const paginatedUsers = sorted.slice(startIndex, endIndex);

    res.json({
      data: paginatedUsers.map(sanitizeUser),
      pagination: {
        page,
        limit,
        total: allUsers.length,
        totalPages: Math.ceil(allUsers.length / limit)
      }
    });
  }
);

/**
 * Get specific user endpoint
 * Requires authentication
 * Users can only see their own data or admins can see all
 */
app.get('/users/:id',
  authenticateToken,
  query('id').optional().isInt().toInt(),
  handleValidationErrors,
  (req, res) => {
    const userId = parseInt(req.params.id);

    // Authorization: users can only access their own data
    if (req.user.role !== 'admin' && req.user.id !== userId) {
      logger.warn(`Unauthorized access attempt by user ${req.user.id} to user ${userId}`);
      return res.status(403).json({
        error: 'You do not have permission to access this user',
        code: 'FORBIDDEN'
      });
    }

    logger.info(`User ${req.user.id} accessed user ${userId}`);

    // Mock database lookup
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
    ];

    const user = users.find(u => u.id === userId);
    if (!user) {
      return res.status(404).json({
        error: 'User not found',
        code: 'USER_NOT_FOUND'
      });
    }

    res.json(sanitizeUser(user));
  }
);

// ============================================================================
// 7. ERROR HANDLING
// ============================================================================

/**
 * 404 handler
 */
app.use((req, res) => {
  logger.warn(`404 - Route not found: ${req.method} ${req.path}`);
  res.status(404).json({
    error: 'Not found',
    code: 'NOT_FOUND',
    path: req.path
  });
});

/**
 * Global error handler
 * IMPORTANT: Never send stack traces to clients in production
 */
app.use((err, req, res, next) => {
  logger.error(`Error: ${err.message}`, { stack: err.stack });

  const status = err.status || 500;
  const message = NODE_ENV === 'production'
    ? 'Internal server error'
    : err.message;

  res.status(status).json({
    error: message,
    code: 'INTERNAL_ERROR',
    ...(NODE_ENV !== 'production' && { stack: err.stack })
  });
});

// ============================================================================
// 8. SERVER STARTUP
// ============================================================================

const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, closing server gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  logger.info('SIGINT received, closing server gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

