# Security Quick Reference Guide

## Common Vulnerabilities & Fixes

### 1. SQL Injection

**VULNERABLE:**
```javascript
app.get('/users/:id', (req, res) => {
  const query = `SELECT * FROM users WHERE id = ${req.params.id}`;
  db.query(query, (err, result) => {
    res.json(result);
  });
});
```

**SECURE:**
```javascript
app.get('/users/:id', (req, res) => {
  const query = 'SELECT * FROM users WHERE id = $1';
  db.query(query, [req.params.id], (err, result) => {
    res.json(result);
  });
});
```

---

### 2. XSS (Cross-Site Scripting)

**VULNERABLE:**
```javascript
app.get('/search', (req, res) => {
  const searchTerm = req.query.q;
  res.send(`<h1>Search results for: ${searchTerm}</h1>`);
});
```

**SECURE:**
```javascript
const DOMPurify = require('isomorphic-dompurify');
const escapeHtml = require('escape-html');

app.get('/search', (req, res) => {
  const searchTerm = escapeHtml(req.query.q);
  res.send(`<h1>Search results for: ${searchTerm}</h1>`);
});
```

---

### 3. CSRF (Cross-Site Request Forgery)

**VULNERABLE:**
```javascript
app.post('/delete-user/:id', (req, res) => {
  // No CSRF token validation
  db.query('DELETE FROM users WHERE id = $1', [req.params.id]);
  res.json({ success: true });
});
```

**SECURE:**
```javascript
const csrf = require('csurf');
const session = require('express-session');

app.use(session({ secret: 'keyboard cat', resave: false, saveUninitialized: true }));
app.use(csrf());

app.post('/delete-user/:id', (req, res) => {
  // CSRF token is validated automatically
  db.query('DELETE FROM users WHERE id = $1', [req.params.id]);
  res.json({ success: true });
});
```

---

### 4. Password Storage

**VULNERABLE:**
```javascript
app.post('/register', (req, res) => {
  const password = req.body.password;
  // Storing plaintext password - NEVER do this!
  db.query('INSERT INTO users (username, password) VALUES ($1, $2)',
    [req.body.username, password]);
});
```

**SECURE:**
```javascript
const bcrypt = require('bcrypt');

app.post('/register', async (req, res) => {
  const password = req.body.password;
  const salt = await bcrypt.genSalt(10);
  const hashedPassword = await bcrypt.hash(password, salt);

  db.query('INSERT INTO users (username, password) VALUES ($1, $2)',
    [req.body.username, hashedPassword]);
});

// Verification:
const isValidPassword = await bcrypt.compare(plainTextPassword, hashedPasswordFromDB);
```

---

### 5. Sensitive Data in Logs

**VULNERABLE:**
```javascript
app.use((req, res, next) => {
  console.log('Request body:', req.body); // Logs passwords!
  next();
});
```

**SECURE:**
```javascript
const logger = (req, res, next) => {
  const sanitized = {
    method: req.method,
    path: req.path,
    // Don't log sensitive fields
    body: {
      ...req.body,
      password: '[REDACTED]',
      ssn: '[REDACTED]',
      creditCard: '[REDACTED]'
    }
  };
  console.log('Request:', sanitized);
  next();
};

app.use(logger);
```

---

### 6. File Upload Vulnerabilities

**VULNERABLE:**
```javascript
app.post('/upload', (req, res) => {
  const file = req.files.upload;
  file.mv(`./uploads/${file.name}`); // Could upload executable!
  res.send('File uploaded');
});
```

**SECURE:**
```javascript
const path = require('path');
const crypto = require('crypto');

const ALLOWED_EXTENSIONS = ['.jpg', '.png', '.pdf'];
const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB

app.post('/upload', (req, res) => {
  const file = req.files.upload;

  // Check file size
  if (file.size > MAX_FILE_SIZE) {
    return res.status(400).json({ error: 'File too large' });
  }

  // Check file extension
  const ext = path.extname(file.name).toLowerCase();
  if (!ALLOWED_EXTENSIONS.includes(ext)) {
    return res.status(400).json({ error: 'File type not allowed' });
  }

  // Generate safe filename
  const filename = crypto.randomBytes(16).toString('hex') + ext;
  const filepath = path.join(__dirname, 'uploads', filename);

  // Validate path to prevent directory traversal
  if (!filepath.startsWith(path.join(__dirname, 'uploads'))) {
    return res.status(400).json({ error: 'Invalid file path' });
  }

  file.mv(filepath, (err) => {
    if (err) return res.status(500).json({ error: err.message });
    res.json({ filename });
  });
});
```

