### 7. Broken Authentication

**VULNERABLE:**
```javascript
app.get('/users/:id', (req, res) => {
  // No authentication required
  const user = db.query('SELECT * FROM users WHERE id = $1', [req.params.id]);
  res.json(user);
});
```

**SECURE:**
```javascript
const jwt = require('jsonwebtoken');

const authenticateToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];

  if (!token) return res.status(401).json({ error: 'No token' });

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user;
    next();
  });
};

app.get('/users/:id', authenticateToken, (req, res) => {
  // Check authorization: user can only see their own data
  if (req.user.id !== parseInt(req.params.id) && req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }

  const user = db.query('SELECT * FROM users WHERE id = $1', [req.params.id]);
  res.json(user);
});
```

---

### 8. Sensitive Data Exposure

**VULNERABLE:**
```javascript
app.get('/user/profile', (req, res) => {
  const user = db.query('SELECT * FROM users WHERE id = $1', [req.user.id]);
  res.json(user); // Exposes password_hash, SSN, credit card, etc.
});
```

**SECURE:**
```javascript
app.get('/user/profile', (req, res) => {
  const user = db.query('SELECT * FROM users WHERE id = $1', [req.user.id]);

  // Only return safe fields
  res.json({
    id: user.id,
    username: user.username,
    email: user.email,
    profile: {
      firstName: user.first_name,
      lastName: user.last_name,
      avatar: user.avatar_url
    }
  });
});
```

---

### 9. Broken Access Control

**VULNERABLE:**
```javascript
app.delete('/users/:id', authenticateToken, (req, res) => {
  // Any authenticated user can delete any user!
  db.query('DELETE FROM users WHERE id = $1', [req.params.id]);
  res.json({ success: true });
});
```

**SECURE:**
```javascript
app.delete('/users/:id', authenticateToken, (req, res) => {
  const userId = parseInt(req.params.id);

  // Only admin can delete users
  if (req.user.role !== 'admin') {
    logger.warn(`Unauthorized delete attempt by user ${req.user.id}`);
    return res.status(403).json({ error: 'Only admins can delete users' });
  }

  // Prevent self-deletion (optional but good practice)
  if (req.user.id === userId) {
    return res.status(400).json({ error: 'Cannot delete own account' });
  }

  db.query('DELETE FROM users WHERE id = $1', [userId]);
  res.json({ success: true });
});
```

---

### 10. Environment Variable Exposure

**VULNERABLE:**
```javascript
// Hardcoded secrets - NEVER do this!
const JWT_SECRET = 'my-super-secret-key';
const DB_PASSWORD = 'postgres123';
```

**SECURE:**
```bash
# .env file (never commit this!)
JWT_SECRET=<long-random-string-min-32-chars>
DB_PASSWORD=<random-strong-password>
DATABASE_URL=postgresql://user:password@localhost/dbname
```

