```javascript
const AWS = require('aws-sdk');

class SecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = {};
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    // Check cache first
    if (this.cache[secretName] && Date.now() - this.cache[secretName].time < this.cacheTTL) {
      return this.cache[secretName].value;
    }

    try {
      const data = await this.client.getSecretValue({
        SecretId: secretName
      }).promise();

      let secret;
      if ('SecretString' in data) {
        secret = JSON.parse(data.SecretString);
      } else {
        secret = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }

      // Cache with TTL
      this.cache[secretName] = {
        value: secret,
        time: Date.now()
      };

      return secret;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error);

      // NEVER fall back to .env in production
      if (process.env.NODE_ENV === 'production') {
        throw new Error(`CRITICAL: Cannot retrieve required secret: ${secretName}`);
      }

      // Development fallback only
      return process.env[secretName];
    }
  }

  // Invalidate cache on secret rotation
  invalidateCache(secretName) {
    delete this.cache[secretName];
  }
}

// Usage in app.js
const secretsManager = new SecretsManager();

async function initializeApp() {
  try {
    const appSecrets = await secretsManager.getSecret('app/production/secrets');

    const JWT_SECRET = appSecrets.jwtSecret;
    const DB_URL = appSecrets.databaseUrl;

    // Validate critical secrets
    if (!JWT_SECRET || JWT_SECRET.length < 32) {
      throw new Error('Invalid JWT_SECRET');
    }

    // Start app with loaded secrets
    startServer(JWT_SECRET, DB_URL);
  } catch (error) {
    logger.error('Failed to initialize app:', error);
    process.exit(1);
  }
}

initializeApp();
