// Secure version of app.js with security hardening recommendations

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('mongo-sanitize');
const xss = require('xss-clean');
const cors = require('cors');
const validator = require('validator');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE SETUP
// ============================================================================

// 1. HELMET - Sets various HTTP headers for security
// Protects against: clickjacking, MIME type sniffing, XSS, etc.
app.use(helmet());

// 2. CORS - Restrict cross-origin requests
// Configure only trusted origins
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
};
app.use(cors(corsOptions));

// 3. BODY PARSER - Parse incoming request bodies with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 4. DATA SANITIZATION - Protect against NoSQL injection and XSS
app.use(mongoSanitize()); // Removes $ and . from user inputs
app.use(xss()); // Cleans XSS attacks

// 5. RATE LIMITING - Prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

// Apply rate limiting to all requests
app.use(limiter);

// More strict rate limiter for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 login attempts per 15 minutes
  skipSuccessfulRequests: true,
  message: 'Too many login attempts, please try again later.'
});

// ============================================================================
// INPUT VALIDATION MIDDLEWARE
// ============================================================================

// Middleware to validate query parameters
const validateQueryParams = (req, res, next) => {
  // Validate common query parameters
  if (req.query.limit && !validator.isInt(req.query.limit, { min: 1, max: 100 })) {
    return res.status(400).json({ error: 'Invalid limit parameter' });
  }
  if (req.query.offset && !validator.isInt(req.query.offset, { min: 0 })) {
    return res.status(400).json({ error: 'Invalid offset parameter' });
  }
  next();
};

// ============================================================================
// SECURITY HEADERS MIDDLEWARE
// ============================================================================

app.use((req, res, next) => {
  // Prevent browsers from MIME sniffing
  res.setHeader('X-Content-Type-Options', 'nosniff');

  // Enable XSS protection
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Clickjacking protection
  res.setHeader('X-Frame-Options', 'SAMEORIGIN');

  // Referrer policy
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

  // Content Security Policy (CSP)
  res.setHeader(
    'Content-Security-Policy',
    "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data: https:; font-src 'self'"
  );

  next();
});

// ============================================================================
// ROUTES WITH SECURITY HARDENING
// ============================================================================

/**
 * Health check endpoint
 * Security: Minimal information disclosure
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * Users endpoint with security enhancements
 * 
 * SECURITY IMPROVEMENTS:
 * 1. Input validation for query parameters
 * 2. Limit response size to prevent information disclosure
 * 3. Rate limiting applied
 * 4. No sensitive information in response (passwords, tokens, etc.)
 */
app.get('/users', validateQueryParams, (req, res) => {
  try {
    // Validate and sanitize query parameters
    const limit = Math.min(
      Math.max(parseInt(req.query.limit) || 10, 1), 
      100
    );
    const offset = Math.max(parseInt(req.query.offset) || 0, 0);

    // Mock data - in real app, sanitize database queries
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Pagination
    const paginatedUsers = allUsers.slice(offset, offset + limit);

    // Remove sensitive fields
    const sanitizedUsers = paginatedUsers.map(user => ({
      id: user.id,
      name: user.name,
      email: user.email
      // DO NOT include: password, token, secret, etc.
    }));

    res.json({
      data: sanitizedUsers,
      total: allUsers.length,
      limit,
      offset
    });
  } catch (error) {
    // Don't expose error details to client
    console.error('Error in /users endpoint:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Example secure user search endpoint
 * SECURITY: Input validation, parameterized queries, error handling
 */
app.get('/users/:id', (req, res) => {
  try {
    // Validate ID is a positive integer
    const userId = parseInt(req.params.id);
    if (!Number.isInteger(userId) || userId < 1) {
      return res.status(400).json({ error: 'Invalid user ID' });
    }

    // Mock data - in real app, use parameterized queries to prevent SQL injection
    const mockUsers = {
      1: { id: 1, name: 'Alice', email: 'alice@example.com' },
      2: { id: 2, name: 'Bob', email: 'bob@example.com' },
    };

    const user = mockUsers[userId];
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  } catch (error) {
    console.error('Error fetching user:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ============================================================================
// ERROR HANDLING
// ============================================================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Global error handler - Never expose stack traces to client
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  const statusCode = err.statusCode || 500;
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(statusCode).json({
    error: 'Internal server error',
    // Only send stack trace in development
    ...(isDevelopment && { stack: err.stack })
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

// Ensure we're not running in production without HTTPS
if (process.env.NODE_ENV === 'production') {
  if (!process.env.HTTPS_ENABLED && process.env.TRUST_PROXY !== 'true') {
    console.warn('WARNING: Running production without HTTPS enabled');
  }
}

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

// Enhanced version with Authentication & Authorization Example
// Shows how to add secure auth to the original app

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const validator = require('validator');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Security headers
app.use(helmet());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
});
app.use(limiter);

// Specific limiter for authentication
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true
});

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));

// ============================================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================================

// Mock user database (in production, use real database with hashed passwords)
const users = {
  'user1': {
    id: 1,
    username: 'user1',
    // Password should be bcrypt hashed in production
    password: 'hashed_password_here',
    role: 'user'
  }
};

// Authenticate token
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET || 'your-secret-key', (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// Authorization middleware - role-based
const authorize = (...allowedRoles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    if (!allowedRoles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
};

// ============================================================================
// PUBLIC ROUTES (No auth required)
// ============================================================================

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * Login endpoint - Secure authentication
 * SECURITY:
 * - Rate limited to prevent brute force
 * - Input validation
 * - Secure token generation
 * - No credential echo in response
 */
app.post('/login', authLimiter, (req, res) => {
  try {
    const { username, password } = req.body;

    // Input validation
    if (!username || !password) {
      return res.status(400).json({ error: 'Username and password required' });
    }

    if (!validator.isAlphanumeric(username) || username.length > 50) {
      return res.status(400).json({ error: 'Invalid username format' });
    }

    // Find user (in production, query database)
    const user = users[username];

    if (!user) {
      // Don't reveal if user exists to prevent username enumeration
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    // In production: use bcrypt.compare(password, user.password)
    if (password !== user.password) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    // Generate JWT token
    const token = jwt.sign(
      {
        id: user.id,
        username: user.username,
        role: user.role
      },
      process.env.JWT_SECRET || 'your-secret-key',
      { expiresIn: '1h' } // Token expires in 1 hour
    );

    res.json({
      token,
      user: {
        id: user.id,
        username: user.username,
        role: user.role
        // NEVER include: password, secret, or sensitive fields
      }
    });
  } catch (error) {
    console.error('Login error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ============================================================================
// PROTECTED ROUTES (Authentication required)
// ============================================================================

/**
 * Get all users - Requires authentication
 * SECURITY:
 * - Token validation required
 * - Role-based access control
 * - Input validation for pagination
 * - Limited response fields
 */
app.get('/users', authenticateToken, (req, res) => {
  try {
    // Validate pagination parameters
    const limit = Math.min(Math.max(parseInt(req.query.limit) || 10, 1), 100);
    const offset = Math.max(parseInt(req.query.offset) || 0, 0);

    // Mock data
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
    ];

    // Filter sensitive fields
    const sanitizedUsers = allUsers
      .slice(offset, offset + limit)
      .map(user => ({
        id: user.id,
        name: user.name,
        email: user.email
        // Exclude: password, token, internal notes
      }));

    res.json({
      data: sanitizedUsers,
      total: allUsers.length,
      requester: req.user.username // For audit logging
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Get specific user by ID - Requires authentication
 * SECURITY:
 * - Token validation
 * - ID validation (integer, > 0)
 * - Authorization check (users can only see own info or admins see all)
 */
app.get('/users/:id', authenticateToken, (req, res) => {
  try {
    const userId = parseInt(req.params.id);

    // Validate ID
    if (!Number.isInteger(userId) || userId < 1) {
      return res.status(400).json({ error: 'Invalid user ID' });
    }

    // Authorization: user can see their own profile, or admin can see all
    if (req.user.id !== userId && req.user.role !== 'admin') {
      return res.status(403).json({ error: 'Cannot access other users' });
    }

    // Mock data lookup
    const mockUsers = {
      1: { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      2: { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
    };

    const user = mockUsers[userId];
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  } catch (error) {
    console.error('Error fetching user:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ============================================================================
// ADMIN-ONLY ROUTES (Requires admin role)
// ============================================================================

/**
 * Create new user - Admin only
 * SECURITY:
 * - Token validation
 * - Admin authorization
 * - Input validation
 * - Secure password handling
 */
app.post('/users', authenticateToken, authorize('admin'), (req, res) => {
  try {
    const { username, email, password, role } = req.body;

    // Input validation
    if (!username || !email || !password) {
      return res.status(400).json({ error: 'Missing required fields' });
    }

    // Validate formats
    if (!validator.isEmail(email)) {
      return res.status(400).json({ error: 'Invalid email format' });
    }

    if (!validator.isAlphanumeric(username) || username.length < 3 || username.length > 50) {
      return res.status(400).json({ error: 'Invalid username format' });
    }

    if (password.length < 12) {
      return res.status(400).json({ error: 'Password must be at least 12 characters' });
    }

    // Validate role
    const validRoles = ['user', 'admin'];
    if (!validRoles.includes(role)) {
      return res.status(400).json({ error: 'Invalid role' });
    }

    // In production:
    // 1. Hash password with bcrypt: const hashed = await bcrypt.hash(password, 10)
    // 2. Save to database with transaction
    // 3. Return created user (without password)

    res.status(201).json({
      id: 3,
      username,
      email,
      role,
      created_at: new Date().toISOString()
    });
  } catch (error) {
    console.error('Error creating user:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Delete user - Admin only
 * SECURITY:
 * - Token validation
 * - Admin authorization
 * - ID validation
 * - Audit logging
 */
app.delete('/users/:id', authenticateToken, authorize('admin'), (req, res) => {
  try {
    const userId = parseInt(req.params.id);

    if (!Number.isInteger(userId) || userId < 1) {
      return res.status(400).json({ error: 'Invalid user ID' });
    }

    // Audit log: who deleted whom and when
    console.log(`User ${req.user.id} deleted user ${userId} at ${new Date().toISOString()}`);

    // In production: soft delete (set deleted_at timestamp) to preserve audit trail

    res.json({ message: 'User deleted', deleted_user_id: userId });
  } catch (error) {
    console.error('Error deleting user:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ============================================================================
// ERROR HANDLING
// ============================================================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  const isDevelopment = process.env.NODE_ENV === 'development';
  const statusCode = err.statusCode || 500;

  res.status(statusCode).json({
    error: 'Internal server error',
    ...(isDevelopment && { message: err.message })
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

// Check for required environment variables in production
if (process.env.NODE_ENV === 'production') {
  if (!process.env.JWT_SECRET) {
    throw new Error('JWT_SECRET environment variable is required in production');
  }
}

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

