// Secure version of app.js with security best practices implemented
// This addresses all identified vulnerabilities

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const validator = require('validator');
const { v4: uuidv4 } = require('uuid');
const app = express();

// ============================================================================
// 1. SECURITY MIDDLEWARE - Defense in Depth
// ============================================================================

// Helmet.js: Sets various HTTP headers for security
app.use(helmet());

// Content Security Policy
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
  },
}));

// Rate limiting to prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use(limiter);

// Parse JSON with size limits to prevent large payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// ============================================================================
// 2. INPUT VALIDATION & SANITIZATION MIDDLEWARE
// ============================================================================

// Custom middleware to sanitize query parameters and prevent injection
const sanitizeInput = (req, res, next) => {
  // Sanitize query parameters
  Object.keys(req.query).forEach(key => {
    if (typeof req.query[key] === 'string') {
      // Remove potential injection attempts
      req.query[key] = validator.escape(req.query[key]);
      req.query[key] = validator.trim(req.query[key]);
    }
  });

  // Sanitize body if present
  if (req.body && typeof req.body === 'object') {
    Object.keys(req.body).forEach(key => {
      if (typeof req.body[key] === 'string') {
        req.body[key] = validator.escape(req.body[key]);
        req.body[key] = validator.trim(req.body[key]);
      }
    });
  }

  next();
};

app.use(sanitizeInput);

// ============================================================================
// 3. AUTHENTICATION & AUTHORIZATION (STUB - Implement as needed)
// ============================================================================

// Simple API key authentication middleware (example)
const authenticate = (req, res, next) => {
  const apiKey = req.headers['x-api-key'];

  if (!apiKey) {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'API key is required'
    });
  }

  // Validate API key (should be checked against a database/vault)
  if (!validateApiKey(apiKey)) {
    return res.status(403).json({
      error: 'Forbidden',
      message: 'Invalid API key'
    });
  }

  next();
};

// Stub function - implement with proper credential verification
function validateApiKey(key) {
  // IMPORTANT: In production, verify against a secure store (database, vault, etc.)
  // NEVER hardcode credentials
  // This is just a placeholder
  const validKeys = process.env.VALID_API_KEYS?.split(',') || [];
  return validKeys.includes(key);
}

// ============================================================================
// 4. SECURE ROUTES
// ============================================================================

// Health check endpoint - minimal data exposure
app.get('/health', (req, res) => {
  // Only expose safe information
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString()
  });
});

// Protected endpoint - requires authentication
app.get('/users', authenticate, (req, res) => {
  try {
    // Validate query parameters
    const limit = req.query.limit ? parseInt(req.query.limit, 10) : 10;
    const page = req.query.page ? parseInt(req.query.page, 10) : 1;

    // Input validation
    if (isNaN(limit) || isNaN(page) || limit < 1 || page < 1) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Invalid pagination parameters'
      });
    }

    // Prevent excessively large requests
    if (limit > 100) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Limit cannot exceed 100'
      });
    }

    // Mock database with secure data structure
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Implement pagination
    const startIdx = (page - 1) * limit;
    const endIdx = startIdx + limit;
    const paginatedUsers = mockUsers.slice(startIdx, endIdx);

    // Return safe response
    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: mockUsers.length
      }
    });

  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'An unexpected error occurred'
    });
  }
});

// Endpoint to demonstrate secure ID parameter validation
app.get('/users/:id', authenticate, (req, res) => {
  try {
    const userId = req.params.id;

    // Validate ID format - only allow positive integers
    if (!validator.isInt(userId, { min: 1 })) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Invalid user ID format'
      });
    }

    // Mock database query (parameterized - preventing SQL injection)
    const user = getUserById(parseInt(userId, 10));

    if (!user) {
      return res.status(404).json({
        error: 'Not Found',
        message: 'User does not exist'
      });
    }

    // Return sanitized user data
    res.json({ data: user });

  } catch (error) {
    console.error('Error fetching user:', error);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'An unexpected error occurred'
    });
  }
});

// ============================================================================
// 5. ERROR HANDLING
// ============================================================================

// 404 Handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource does not exist'
  });
});

// Global error handler - IMPORTANT: Never expose stack traces in production
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  res.status(err.status || 500).json({
    error: err.name || 'Internal Server Error',
    message: process.env.NODE_ENV === 'production' 
      ? 'An unexpected error occurred' 
      : err.message
  });
});

// ============================================================================
// 6. HELPER FUNCTIONS
// ============================================================================

function getUserById(id) {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  return users.find(u => u.id === id);
}

// ============================================================================
// 7. SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

