  next();
};

app.get('/users', authenticate, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Recommendation:** Implement JWT or OAuth2 for production applications.

---

### 2. **MISSING INPUT VALIDATION (HIGH)**
**Issue:** Query parameters and path parameters are not validated.

```javascript
// ❌ VULNERABLE CODE - No validation
app.get('/users', (req, res) => {
  // If malicious input is added later, no checks exist
});
```

**Potential Attacks:**
- NoSQL/SQL Injection (if database is added)
- Path Traversal
- Type coercion attacks

**Fix:**
```javascript
// ✅ SECURE CODE
const validator = require('validator');

app.get('/users/:id', (req, res) => {
  const userId = req.params.id;

  // Validate that ID is a positive integer
  if (!validator.isInt(userId, { min: 1 })) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Invalid user ID format'
    });
  }

  const id = parseInt(userId, 10);
  // ... rest of handler
});
```

---

### 3. **NO SECURITY HEADERS (HIGH)**
**Issue:** Application doesn't set security-related HTTP headers.

**Vulnerable to:**
- Click-jacking attacks
- MIME type sniffing
- XSS attacks
- Insufficient transport security

**Fix:**
```javascript
// ✅ SECURE CODE
const helmet = require('helmet');

app.use(helmet());
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
  },
}));
```

**Headers Added:**
- `X-Frame-Options`: Prevents click-jacking
- `X-Content-Type-Options`: Prevents MIME type sniffing
- `Strict-Transport-Security`: Enforces HTTPS
- `Content-Security-Policy`: Prevents XSS

---

### 4. **NO RATE LIMITING (MEDIUM)**
**Issue:** No protection against brute force attacks or DoS.

**Attacks Possible:**
- Brute force attacks
- Denial of Service (DoS)
- Resource exhaustion

**Fix:**
```javascript
// ✅ SECURE CODE
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per 15 minutes
  message: 'Too many requests from this IP'
});

app.use(limiter);
```

---

### 5. **MISSING REQUEST SIZE LIMITS (MEDIUM)**
**Issue:** No limits on request body/payload size.

**Attacks Possible:**
- Large payload attacks causing memory exhaustion
- Denial of Service through oversized requests

**Fix:**
```javascript
// ✅ SECURE CODE
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));
```

---

### 6. **NO INPUT SANITIZATION (MEDIUM)**
**Issue:** User input is not escaped or sanitized.

**Scenario:**
If database queries or HTML rendering are added, injection becomes possible.

```javascript
// ❌ VULNERABLE - Even for future features
app.get('/search', (req, res) => {
  const query = req.query.q; // No sanitization
  // If later used in DB: db.query(`SELECT * FROM users WHERE name = '${query}'`); // SQL Injection!
});
```

**Fix:**
```javascript
// ✅ SECURE CODE
const validator = require('validator');

const sanitizeInput = (req, res, next) => {
  Object.keys(req.query).forEach(key => {
    if (typeof req.query[key] === 'string') {
      req.query[key] = validator.escape(req.query[key]);
      req.query[key] = validator.trim(req.query[key]);
    }
  });
  next();
};

app.use(sanitizeInput);
```

---

### 7. **INADEQUATE ERROR HANDLING (MEDIUM)**
**Issue:** Generic error handling doesn't expose stack traces, but no try-catch for potential errors.

**Risk:** 
- Information disclosure in error messages
- Application crashes without graceful handling

**Fix:**
```javascript
// ✅ SECURE CODE
app.get('/users', authenticate, (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    res.json({ data: users });
  } catch (error) {
    console.error('Error:', error); // Log to secure location
    res.status(500).json({
      error: 'Internal Server Error',
      message: process.env.NODE_ENV === 'production' 
        ? 'An unexpected error occurred' 
        : error.message
    });
  }
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(err.status || 500).json({
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'production'
      ? 'An unexpected error occurred'
      : err.message
  });
});
```

---

### 8. **INFORMATION DISCLOSURE (MEDIUM)**
**Issue:** Unnecessarily exposing detailed data/information.

```javascript
// ❌ PARTIALLY VULNERABLE
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
  // This is OK, but should limit what /health exposes
});
```

**Fix:**
```javascript
// ✅ SECURE CODE
app.get('/health', (req, res) => {
  // Only expose minimal, safe information
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString()
    // Don't include: version, stack info, dependencies, etc.
  });
});
```

---

### 9. **NO HTTPS/TLS ENFORCEMENT (HIGH - In Production)**
**Issue:** No enforcement of HTTPS connections.

**Risk:** Man-in-the-middle attacks, credential interception

**Fix:**
```javascript
// ✅ SECURE CODE
const helmet = require('helmet');

app.use(helmet.hsts({
  maxAge: 31536000, // 1 year
  includeSubDomains: true,
  preload: true
}));
```

---

### 10. **MISSING LOGGING & MONITORING (MEDIUM)**
**Issue:** No audit trail or security event logging.

**Fix:**
```javascript
// ✅ SECURE CODE
const winston = require('winston');

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

// Log security events
app.use((req, res, next) => {
  logger.info({
    method: req.method,
    path: req.path,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });
  next();
});
```

