# Security Implementation Guide

## Overview
This guide provides step-by-step instructions to implement security fixes in your Express application.

---

## Phase 1: Critical Security Fixes (Week 1)

### Step 1: Install Security Dependencies

```bash
npm install express helmet express-rate-limit validator uuid dotenv winston
npm install --save-dev eslint jest supertest nodemon
```

### Step 2: Add Environment Configuration

Create `.env` file:
```bash
cp .env.example .env
```

Update `.env` with your configuration:
```env
NODE_ENV=production
PORT=3000
VALID_API_KEYS=your-secure-api-key-here
LOG_LEVEL=info
```

### Step 3: Implement Security Headers

Replace your current middleware with:

```javascript
const helmet = require('helmet');

// Add to your app
app.use(helmet());
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", "data:", "https:"],
  },
}));
app.use(helmet.hsts({
  maxAge: 31536000,
  includeSubDomains: true,
  preload: true
}));
```

### Step 4: Implement Authentication

```javascript
const authenticate = (req, res, next) => {
  const apiKey = req.headers['x-api-key'];

  if (!apiKey) {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'API key required'
    });
  }

  const validKeys = process.env.VALID_API_KEYS?.split(',') || [];
  if (!validKeys.includes(apiKey)) {
    return res.status(403).json({
      error: 'Forbidden',
      message: 'Invalid API key'
    });
  }

  next();
};

// Protect your endpoints
app.get('/users', authenticate, (req, res) => {
  // ... endpoint logic
});
```

### Step 5: Implement Rate Limiting

```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);
```

### Step 6: Add Input Validation

```javascript
const validator = require('validator');

// For route parameters
app.get('/users/:id', authenticate, (req, res) => {
  if (!validator.isInt(req.params.id, { min: 1 })) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Invalid user ID'
    });
  }

  // ... rest of logic
});

// For query parameters
app.get('/users', authenticate, (req, res) => {
  const limit = req.query.limit ? parseInt(req.query.limit, 10) : 10;
  const page = req.query.page ? parseInt(req.query.page, 10) : 1;

  if (isNaN(limit) || isNaN(page) || limit < 1 || page < 1) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Invalid pagination'
    });
  }

  // ... rest of logic
});
```

### Step 7: Add Request Size Limits

```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));
```

### Step 8: Implement Error Handling

```javascript
app.use((err, req, res, next) => {
  console.error('Error:', err);

  res.status(err.status || 500).json({
    error: err.name || 'Internal Server Error',
    message: process.env.NODE_ENV === 'production'
      ? 'An unexpected error occurred'
      : err.message
  });
});

app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource does not exist'
  });
});
```

