## Issue 7: No Input Sanitization

### ❌ VULNERABLE CODE
```javascript
app.get('/search', (req, res) => {
  const query = req.query.q;
  // If later used in HTML or SQL...
  // res.send(`<h1>Results for ${query}</h1>`); // XSS!
  res.json({ query });
});
```

**Problems:**
- No escaping
- XSS vulnerability if output to HTML
- Injection vulnerability if used in SQL

**Attack:**
```bash
curl "http://localhost:3000/search?q=<script>alert('xss')</script>"
# If output to HTML, script executes
```

---

### ✅ SECURE CODE
```javascript
const validator = require('validator');

const sanitizeInput = (req, res, next) => {
  Object.keys(req.query).forEach(key => {
    if (typeof req.query[key] === 'string') {
      req.query[key] = validator.escape(req.query[key]);
      req.query[key] = validator.trim(req.query[key]);
    }
  });
  next();
};

app.use(sanitizeInput);

app.get('/search', (req, res) => {
  const query = req.query.q;
  // Now safely escaped
  res.json({ query }); // Safe to output anywhere
});
```

**Result:**
```bash
curl "http://localhost:3000/search?q=<script>alert('xss')</script>"
# Returns: {"query": "&lt;script&gt;alert(&#x27;xss&#x27;)&lt;&#x2F;script&gt;"}
# Script won't execute
```

