/**
 * OPTION A: AWS SECRETS MANAGER IMPLEMENTATION
 * 
 * Pros:
 * - Native AWS integration
 * - Automatic rotation support
 * - Audit logging via CloudTrail
 * - Fine-grained IAM permissions
 * - Encryption at rest (KMS)
 * 
 * Cons:
 * - AWS-specific (lock-in)
 * - Additional AWS costs
 * - Network latency for secret retrieval
 */

const AWS = require('aws-sdk');
const NodeCache = require('node-cache');

// Cache secrets in memory for 1 hour to reduce AWS API calls
const secretCache = new NodeCache({ stdTTL: 3600, checkperiodl: 600 });

class SecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = secretCache.get(secretName);
    if (cached) {
      console.log(`[CACHE HIT] Retrieved ${secretName} from cache`);
      return cached;
    }

    try {
      console.log(`[AWS] Fetching secret: ${secretName}`);
      const response = await this.client.getSecretValue({
        SecretId: secretName
      }).promise();

      let secret;
      if ('SecretString' in response) {
        secret = JSON.parse(response.SecretString);
      } else {
        secret = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
      }

      // Store in cache
      secretCache.set(secretName, secret);
      return secret;
    } catch (error) {
      console.error(`[ERROR] Failed to retrieve secret ${secretName}:`, error.message);
      throw new Error(`Failed to retrieve secret: ${error.message}`);
    }
  }

  async getSecrets(secretNames) {
    return Promise.all(secretNames.map(name => this.getSecret(name)));
  }
}

