    secrets.DATABASE_URL = 
      `postgres://${dbCreds.username}:${dbCreds.password}@db.internal:5432/production`;
    console.log(`[DB CREDS] Loaded with TTL: ${dbCreds.ttl}s`);

    // Get dynamic AWS credentials
    const awsCreds = await vaultManager.getAWSCredentials('app-prod');
    secrets.AWS_ACCESS_KEY_ID = awsCreds.access_key;
    secrets.AWS_SECRET_ACCESS_KEY = awsCreds.secret_key;
    console.log(`[AWS CREDS] Loaded with TTL: ${awsCreds.ttl}s`);

    console.log('[SUCCESS] All secrets loaded from Vault');
  } catch (error) {
    console.error('[FATAL] Failed to initialize secrets:', error);
    process.exit(1);
