      return response.data.ciphertext;
    } catch (error) {
      console.error(`[VAULT] Encryption failed:`, error);
      throw error;
    }
  }

  // Decrypt sensitive data
  async decrypt(transitKey, ciphertext) {
    try {
      const response = await this.vaultClient.write(`transit/decrypt/${transitKey}`, {
        ciphertext
      });
      return Buffer.from(response.data.plaintext, 'base64').toString('utf8');
    } catch (error) {
      console.error(`[VAULT] Decryption failed:`, error);
      throw error;
    }
  }
}

