// Secure version with security best practices applied

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');
const app = express();

// Security Middleware - Applied
app.use(helmet()); // Set security HTTP headers
app.use(mongoSanitize()); // Prevent NoSQL injection

// Rate limiting - Prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Parse JSON with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Mock user database
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // Return sanitized user data without sensitive info
  const publicUsers = users.map(({ id, name, email }) => ({
    id,
    name: validator.escape(name),
    email: validator.escape(email),
  }));
  res.json(publicUsers);
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);

  // Don't expose internal error details
  res.status(err.status || 500).json({
    error: {
      message: process.env.NODE_ENV === 'production' 
        ? 'Internal Server Error' 
        : err.message,
    },
  });
});

// Catch 404
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, '127.0.0.1', () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

================================================================================
COMPREHENSIVE SECURITY AUDIT OF app.js
================================================================================

EXECUTIVE SUMMARY
=================
The current app.js has CRITICAL security vulnerabilities and lacks essential 
security controls. This audit identifies 8 major issues spanning OWASP Top 10 
concerns. Risk Level: HIGH

================================================================================
FINDINGS
================================================================================

1. MISSING SECURITY HEADERS (A03:2021 – Injection)
   ────────────────────────────────────────────────
   SEVERITY: HIGH

   ISSUE:
   - No HTTP security headers are set
   - Application is vulnerable to XSS, Clickjacking, MIME-sniffing attacks
   - Missing Content Security Policy (CSP)
   - Missing X-Frame-Options
   - Missing X-Content-Type-Options

   OWASP Category: A03:2021 – Injection / A01:2021 – Broken Access Control

   RECOMMENDATION:
   Install and use helmet.js middleware to set security headers:

   ```javascript
   const helmet = require('helmet');
   app.use(helmet());
   ```

   This sets multiple headers:
   - X-Frame-Options: DENY (prevents clickjacking)
   - X-Content-Type-Options: nosniff (prevents MIME sniffing)
   - Strict-Transport-Security (enables HTTPS)
   - Content-Security-Policy (prevents XSS)


2. NO RATE LIMITING / DDoS PROTECTION
   ───────────────────────────────────
   SEVERITY: HIGH

   ISSUE:
   - Application has no rate limiting
   - Vulnerable to brute force attacks
   - Vulnerable to DDoS attacks
   - Credentials could be compromised through repeated attempts

   OWASP Category: A07:2021 – Identification and Authentication Failures

   RECOMMENDATION:
   Implement rate limiting using express-rate-limit:

   ```javascript
   const rateLimit = require('express-rate-limit');

   const limiter = rateLimit({
     windowMs: 15 * 60 * 1000,  // 15 minutes
     max: 100,                   // 100 requests per 15 minutes
     message: 'Too many requests, try again later',
     standardHeaders: true,
     legacyHeaders: false,
   });

   app.use(limiter);

   // For authentication endpoints, use stricter limits:
   const authLimiter = rateLimit({
     windowMs: 15 * 60 * 1000,
     max: 5,  // 5 failed attempts
     skipSuccessfulRequests: true,
   });

   app.post('/login', authLimiter, (req, res) => {
     // Login logic
   });
   ```


3. NO INPUT VALIDATION / SANITIZATION
   ──────────────────────────────────
   SEVERITY: CRITICAL

   ISSUE:
   - Query parameters are not validated
   - User input is not sanitized before use
   - Vulnerable to NoSQL injection if database is added
   - Vulnerable to XSS attacks if data is rendered in HTML
   - No protection against malformed requests

   OWASP Category: A03:2021 – Injection

   RECOMMENDATION:
   Implement input validation and sanitization:

   ```javascript
   const validator = require('validator');
   const mongoSanitize = require('express-mongo-sanitize');

   // Sanitize data against NoSQL injection
