  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Referrer Policy
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

  // Content Security Policy
  res.setHeader('Content-Security-Policy', "default-src 'self'");

  next();
});
```

---

### 4. **MISSING RATE LIMITING** (OWASP A04:2021 - DOS Prevention)
**Severity:** MEDIUM

**Finding:** No rate limiting on endpoints enables DOS and brute force attacks.

**Risks:**
- Denial of service attacks
- User enumeration
- Credential brute forcing (if login added later)

**Recommended Fix:**
```javascript
// Install: npm install express-rate-limit
const rateLimit = require('express-rate-limit');

// General rate limiter
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

// Strict limiter for authentication endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 attempts per 15 minutes
  skipSuccessfulRequests: true,
});

// Apply general limiter to all routes
app.use(limiter);

// Apply strict limiter to sensitive endpoints
app.get('/users', authenticateToken, strictLimiter, (req, res) => {
  // ... endpoint logic
});
```

---

### 5. **SENSITIVE DATA EXPOSURE** (OWASP A02:2021)
**Severity:** MEDIUM

**Finding:** User email addresses are exposed without encryption or masking.

**Risks:**
- Email harvesting for spam/phishing campaigns
- Privacy violation
- GDPR/CCPA compliance issues

**Recommended Fix:**
```javascript
// Option 1: Don't expose sensitive data unless necessary
app.get('/users', authenticateToken, (req, res) => {
  // Return only necessary fields
  const users = [
    { id: 1, name: 'Alice' }, // No email
    { id: 2, name: 'Bob' },
  ];
  res.json(users);
});

// Option 2: Mask sensitive data for non-admin users
app.get('/users', authenticateToken, (req, res) => {
  const users = [
    { 
      id: 1, 
      name: 'Alice', 
      email: req.user.role === 'admin' ? 'alice@example.com' : '***@example.com'
    },
    { 
      id: 2, 
      name: 'Bob', 
      email: req.user.role === 'admin' ? 'bob@example.com' : '***@example.com'
    },
  ];
  res.json(users);
});
```

---

### 6. **MISSING HTTPS/TLS** 
**Severity:** HIGH

**Finding:** Server listens on HTTP (port 3000) without HTTPS.

**Risks:**
- Man-in-the-middle attacks
- Credential/token interception
- Data tampering

**Recommended Fix:**
```javascript
const https = require('https');
const fs = require('fs');

// For production, use proper SSL certificates from a trusted CA
const options = {
  key: fs.readFileSync('path/to/private-key.pem'),
  cert: fs.readFileSync('path/to/certificate.pem')
};

https.createServer(options, app).listen(443, () => {
  console.log('Secure server running on port 443');
});

// HTTP redirect (optional)
const http = require('http');
http.createServer((req, res) => {
  res.writeHead(301, { 'Location': `https://${req.headers.host}${req.url}` });
  res.end();
}).listen(80);
```

---

### 7. **MISSING REQUEST SIZE LIMITS** 
**Severity:** MEDIUM

**Finding:** No limits on request payload size.

**Risks:**
- Denial of service via large payloads
- Memory exhaustion attacks
- Buffer overflow scenarios

**Recommended Fix:**
```javascript
const express = require('express');
const app = express();

// Limit request body size
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Or set specific limits for different content types
app.use(express.json({ 
  limit: '10kb',
  strict: true // Only accept arrays and objects
}));
```

---

### 8. **NO LOGGING/MONITORING** (OWASP A09:2021)
**Severity:** MEDIUM

**Finding:** No request logging or security event tracking.

**Risks:**
- Cannot detect attack attempts
- No audit trail for compliance
- Difficult debugging and forensics

**Recommended Fix:**
```javascript
// Install: npm install morgan winston
const morgan = require('morgan');
const winston = require('winston');

// Setup Winston logger
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'user-service' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

// Add console logging in development
if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// Setup Morgan for HTTP request logging
app.use(morgan('combined', {
  stream: {
    write: (message) => logger.info(message)
  }
}));

// Log security events
app.use((req, res, next) => {
  const originalJson = res.json;
  res.json = function(data) {
    if (res.statusCode >= 400) {
      logger.warn({
        status: res.statusCode,
        method: req.method,
        path: req.path,
        ip: req.ip,
        timestamp: new Date().toISOString()
      });
    }
    return originalJson.call(this, data);
  };
  next();
});
```

---

### 9. **MISSING CORS CONFIGURATION** (OWASP A04:2021)
**Severity:** MEDIUM

**Finding:** No CORS headers configured; could be overly permissive by default.

**Risks:**
- Unauthorized cross-origin requests
- Data leakage to malicious sites
- API misuse

**Recommended Fix:**
```javascript
// Install: npm install cors
const cors = require('cors');

// Restrict CORS to specific origins
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['https://example.com'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600 // Preflight cache duration
};

app.use(cors(corsOptions));
```

---

### 10. **NO ERROR HANDLING/INFORMATION DISCLOSURE** (OWASP A01:2021)
**Severity:** MEDIUM

**Finding:** No centralized error handling; stack traces could leak sensitive info.

**Risks:**
- Information disclosure about technology stack
- Attack surface reconnaissance
- Unhandled exceptions crash the app

**Recommended Fix:**
```javascript
// Global error handler
app.use((err, req, res, next) => {
  logger.error({
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  // Don't expose stack trace in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: {
      message: isDevelopment ? err.message : 'Internal server error',
      status: err.status || 500,
      ...(isDevelopment && { stack: err.stack })
    }
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});
```

---

### 11. **MISSING ENVIRONMENT CONFIGURATION**
**Severity:** HIGH

**Finding:** Hardcoded configuration; no use of environment variables.

**Risks:**
- Secrets exposed in version control
- Configuration cannot be changed per environment
- Difficulty managing multiple deployments

**Recommended Fix:**
```javascript
// Create .env file (NEVER commit this)
require('dotenv').config();

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const JWT_SECRET = process.env.JWT_SECRET;
const ALLOWED_ORIGINS = process.env.ALLOWED_ORIGINS?.split(',');

if (!JWT_SECRET) {
  throw new Error('JWT_SECRET environment variable is required');
}

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});
```

