     windowMs: 15 * 60 * 1000,
     max: 5,
   });

   app.get('/login', strictLimiter, (req, res) => { ... });
   ```

4. NO SECURITY HEADERS
   Severity: HIGH
   Issue: Missing essential HTTP security headers that protect against common web vulnerabilities.

   Recommended Fix:
   ```javascript
   const helmet = require('helmet');

   app.use(helmet());

   // This sets:
   // - Content-Security-Policy
   // - X-Content-Type-Options: nosniff
   // - X-Frame-Options: DENY
   // - Strict-Transport-Security
   // - X-XSS-Protection
   // etc.

   // Additional custom headers:
   app.use((req, res, next) => {
     res.setHeader('X-Content-Type-Options', 'nosniff');
     res.setHeader('X-Frame-Options', 'DENY');
     res.setHeader('X-XSS-Protection', '1; mode=block');
     res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
     next();
   });
   ```

========================================
HIGH PRIORITY ISSUES
========================================

5. NO CORS CONFIGURATION
   Severity: HIGH
   Issue: By default, Express allows any origin to make requests. This is vulnerable to CSRF and unauthorized API access.

   Recommended Fix:
   ```javascript
   const cors = require('cors');

   const corsOptions = {
     origin: function (origin, callback) {
       const whitelist = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];
       if (whitelist.indexOf(origin) !== -1 || !origin) {
         callback(null, true);
       } else {
         callback(new Error('CORS not allowed by policy'));
       }
     },
     credentials: true,
     methods: ['GET', 'POST', 'PUT', 'DELETE'],
     allowedHeaders: ['Content-Type', 'Authorization'],
     optionsSuccessStatus: 200
   };

   app.use(cors(corsOptions));
   ```

6. NO HTTPS/SSL ENFORCEMENT
   Severity: HIGH
   Issue: Application doesn't enforce HTTPS. Data in transit can be intercepted.

   Recommended Fix:
   ```javascript
   // In production environment, redirect HTTP to HTTPS
   app.use((req, res, next) => {
     if (process.env.NODE_ENV === 'production' && !req.secure) {
       return res.redirect(301, 'https://' + req.header('host') + req.url);
     }
     next();
   });

   // Or use middleware:
   const redirectHttps = (req, res, next) => {
     if (process.env.NODE_ENV === 'production' && req.header('x-forwarded-proto') !== 'https') {
       res.redirect(301, 'https://' + req.header('host') + req.url);
     } else {
       next();
     }
   };

   app.use(redirectHttps);
   ```

