// Secure version of app.js with security best practices implemented

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, body, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const morgan = require('morgan');
const fs = require('fs');
const path = require('path');

const app = express();

// ========== SECURITY MIDDLEWARE ==========

// 1. Use helmet to set security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true,
  },
}));

// 2. Set additional security headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  res.setHeader('Permissions-Policy', 'geolocation=(), microphone=(), camera=()');
  next();
});

// 3. Enforce HTTPS in production
const redirectHttps = (req, res, next) => {
  if (process.env.NODE_ENV === 'production') {
    if (!req.secure && req.header('x-forwarded-proto') !== 'https') {
      return res.redirect(301, 'https://' + req.header('host') + req.url);
    }
  }
  next();
};
app.use(redirectHttps);

// 4. CORS configuration
const corsOptions = {
  origin: function (origin, callback) {
    const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];

    if (!origin || allowedOrigins.indexOf(origin) !== -1) {
      callback(null, true);
    } else {
      callback(new Error('CORS policy: Origin not allowed'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  optionsSuccessStatus: 200,
  maxAge: 86400, // 24 hours
};
app.use(cors(corsOptions));

// 5. Request size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 6. Content-Type validation middleware
app.use((req, res, next) => {
  if (['POST', 'PUT', 'PATCH'].includes(req.method)) {
    if (!req.is('application/json')) {
      return res.status(415).json({ 
        error: 'Unsupported Media Type. Content-Type must be application/json' 
      });
    }
  }
  next();
});

// 7. Logging setup
const logsDir = path.join(__dirname, 'logs');
if (!fs.existsSync(logsDir)) {
  fs.mkdirSync(logsDir, { recursive: true });
}

const accessLogStream = fs.createWriteStream(
  path.join(logsDir, 'access.log'),
  { flags: 'a' }
);

// Morgan HTTP logging
app.use(morgan(':remote-addr - :remote-user [:date[clf]] ":method :url HTTP/:http-version" :status :res[content-length] :response-time ms', {
  stream: accessLogStream
}));

// 8. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => {
    // Skip rate limiting for health check
    return req.path === '/health';
  },
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many authentication attempts, please try again later.',
  skipSuccessfulRequests: true,
});

app.use(limiter);

// ========== AUTHENTICATION MIDDLEWARE ==========

const JWT_SECRET = process.env.JWT_SECRET || 'dev-secret-key-change-in-production';
const JWT_EXPIRY = process.env.JWT_EXPIRY || '24h';

// Authentication middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      // Log unauthorized access attempt
      console.warn({
        timestamp: new Date().toISOString(),
        event: 'unauthorized_access_attempt',
        ip: req.ip,
        path: req.path,
        error: err.message,
      });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// ========== UTILITY FUNCTIONS ==========

// Data filtering function
const filterUserData = (user, isAdmin = false) => {
  const { id, name, email, role } = user;

  if (isAdmin) {
    return { id, name, email, role };
  }

  // Regular users only get public data
  return { id, name };
};

// ========== ROUTES ==========

// Health check endpoint (no auth required, rate limit skipped)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    service: 'app.js',
    environment: process.env.NODE_ENV || 'development',
  });
});

// Login endpoint (for demonstration)
app.post('/login', 
  authLimiter,
  body('username').trim().isLength({ min: 3, max: 50 }).escape(),
  body('password').isLength({ min: 6 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { username, password } = req.body;

    // DEMO: This is a simplified example. In production, validate against database with bcrypt
    if (username === 'demo' && password === 'password123') {
      const token = jwt.sign(
        { id: 1, username: username, role: 'user' },
        JWT_SECRET,
        { expiresIn: JWT_EXPIRY }
      );

      return res.json({ 
        message: 'Login successful',
        token: token,
        expiresIn: JWT_EXPIRY,
      });
    }

    // Log failed login attempt
    console.warn({
      timestamp: new Date().toISOString(),
      event: 'failed_login',
      username: username,
      ip: req.ip,
    });

    res.status(401).json({ error: 'Invalid credentials' });
  }
);

// Get users endpoint (requires authentication)
app.get('/users',
  authenticateToken,
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('offset').optional().isInt({ min: 0 }).toInt(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const limit = req.query.limit || 10;
    const offset = req.query.offset || 0;

    // Mock users data
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com', role: 'user' },
    ];

    const isAdmin = req.user.role === 'admin';
    const filteredUsers = allUsers
      .map(user => filterUserData(user, isAdmin))
      .slice(offset, offset + limit);

    res.json({
      data: filteredUsers,
      pagination: {
        total: allUsers.length,
        limit: limit,
        offset: offset,
        hasMore: offset + limit < allUsers.length,
      },
    });
  }
);

// Get specific user endpoint
app.get('/users/:id',
  authenticateToken,
  (req, res) => {
    const userId = parseInt(req.params.id);

    if (isNaN(userId) || userId < 1) {
      return res.status(400).json({ error: 'Invalid user ID' });
    }

    // Mock user data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    // Only allow users to see their own data or admins to see all
    if (req.user.id !== userId && req.user.role !== 'admin') {
      return res.status(403).json({ error: 'Forbidden: You can only access your own profile' });
    }

    const isAdmin = req.user.role === 'admin';
    res.json(filterUserData(user, isAdmin));
  }
);

// ========== ERROR HANDLING ==========

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error({
    timestamp: new Date().toISOString(),
    event: 'error',
    method: req.method,
    url: req.url,
    ip: req.ip,
    statusCode: err.statusCode || 500,
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
  });

  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  res.status(statusCode).json({ error: message });
});

// ========== SERVER STARTUP ==========

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Validate required environment variables in production
if (NODE_ENV === 'production') {
  if (!process.env.JWT_SECRET) {
    console.error('ERROR: JWT_SECRET environment variable is not set');
    process.exit(1);
  }
}

if (NODE_ENV === 'development') {
  console.warn('⚠️  Running in DEVELOPMENT mode - using default JWT_SECRET');
}

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} environment`);
});

module.exports = app;
