    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    // Only allow users to see their own data or admins to see all
    if (req.user.id !== userId && req.user.role !== 'admin') {
      return res.status(403).json({ error: 'Forbidden: You can only access your own profile' });
    }

    const isAdmin = req.user.role === 'admin';
    res.json(filterUserData(user, isAdmin));
  }
);

// ========== ERROR HANDLING ==========

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error({
    timestamp: new Date().toISOString(),
    event: 'error',
    method: req.method,
    url: req.url,
    ip: req.ip,
    statusCode: err.statusCode || 500,
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
  });

  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  res.status(statusCode).json({ error: message });
});

// ========== SERVER STARTUP ==========

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Validate required environment variables in production
if (NODE_ENV === 'production') {
  if (!process.env.JWT_SECRET) {
    console.error('ERROR: JWT_SECRET environment variable is not set');
    process.exit(1);
  }
}

if (NODE_ENV === 'development') {
  console.warn('⚠️  Running in DEVELOPMENT mode - using default JWT_SECRET');
}

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} environment`);
});

module.exports = app;

COMPREHENSIVE SECURITY REVIEW OF app.js
========================================

CURRENT STATE ANALYSIS:
The application is a basic Express.js server with two endpoints. While the code is minimal, there are several security concerns and best practices that are missing.

========================================
CRITICAL ISSUES (Fix Immediately)
========================================

1. NO INPUT VALIDATION OR SANITIZATION
   Severity: HIGH
   Issue: The application doesn't validate or sanitize any user input from query parameters, request bodies, or headers.

   Current Code:
   app.get('/users', (req, res) => {
     res.json([...]);
   });

   VULNERABLE SCENARIO: If this endpoint is extended to accept query parameters, injection attacks are possible.

   Recommended Fix:
   ```javascript
   const express = require('express');
   const { query, validationResult } = require('express-validator');

   app.get('/users', 
     query('limit').optional().isInt({ min: 1, max: 100 }),
     query('offset').optional().isInt({ min: 0 }),
     (req, res) => {
       const errors = validationResult(req);
       if (!errors.isEmpty()) {
         return res.status(400).json({ errors: errors.array() });
       }
       res.json([...]);
     }
   );
   ```

2. NO AUTHENTICATION OR AUTHORIZATION
   Severity: CRITICAL
   Issue: All endpoints are publicly accessible with no authentication mechanism.

   Current Code:
   app.get('/users', (req, res) => { ... });

   Impact: Unauthorized users can access sensitive user data (names, emails).

   Recommended Fix:
   ```javascript
   const jwt = require('jsonwebtoken');

   // Middleware for JWT authentication
   const authenticateToken = (req, res, next) => {
     const authHeader = req.headers['authorization'];
     const token = authHeader && authHeader.split(' ')[1];

     if (!token) {
       return res.status(401).json({ error: 'Access token required' });
     }

     jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
       if (err) {
         return res.status(403).json({ error: 'Invalid or expired token' });
       }
       req.user = user;
       next();
     });
   };

   app.get('/users', authenticateToken, (req, res) => {
     res.json([...]);
   });
   ```

3. NO RATE LIMITING
   Severity: HIGH
   Issue: Application is vulnerable to DoS attacks and brute force attacks.

   Recommended Fix:
   ```javascript
   const rateLimit = require('express-rate-limit');

   const limiter = rateLimit({
     windowMs: 15 * 60 * 1000, // 15 minutes
     max: 100, // limit each IP to 100 requests per windowMs
     message: 'Too many requests, please try again later.',
     standardHeaders: true,
     legacyHeaders: false,
   });

   app.use(limiter);

   // More strict limit for sensitive endpoints
   const strictLimiter = rateLimit({
     windowMs: 15 * 60 * 1000,
     max: 5,
   });

   app.get('/login', strictLimiter, (req, res) => { ... });
   ```

4. NO SECURITY HEADERS
   Severity: HIGH
   Issue: Missing essential HTTP security headers that protect against common web vulnerabilities.

   Recommended Fix:
   ```javascript
   const helmet = require('helmet');

   app.use(helmet());

   // This sets:
   // - Content-Security-Policy
   // - X-Content-Type-Options: nosniff
   // - X-Frame-Options: DENY
   // - Strict-Transport-Security
   // - X-XSS-Protection
   // etc.

   // Additional custom headers:
   app.use((req, res, next) => {
     res.setHeader('X-Content-Type-Options', 'nosniff');
     res.setHeader('X-Frame-Options', 'DENY');
     res.setHeader('X-XSS-Protection', '1; mode=block');
     res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
     next();
   });
   ```

========================================
HIGH PRIORITY ISSUES
========================================

5. NO CORS CONFIGURATION
   Severity: HIGH
   Issue: By default, Express allows any origin to make requests. This is vulnerable to CSRF and unauthorized API access.

   Recommended Fix:
   ```javascript
   const cors = require('cors');

   const corsOptions = {
     origin: function (origin, callback) {
       const whitelist = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];
       if (whitelist.indexOf(origin) !== -1 || !origin) {
         callback(null, true);
       } else {
         callback(new Error('CORS not allowed by policy'));
       }
     },
     credentials: true,
     methods: ['GET', 'POST', 'PUT', 'DELETE'],
     allowedHeaders: ['Content-Type', 'Authorization'],
     optionsSuccessStatus: 200
   };

   app.use(cors(corsOptions));
   ```

6. NO HTTPS/SSL ENFORCEMENT
   Severity: HIGH
   Issue: Application doesn't enforce HTTPS. Data in transit can be intercepted.

   Recommended Fix:
   ```javascript
   // In production environment, redirect HTTP to HTTPS
   app.use((req, res, next) => {
     if (process.env.NODE_ENV === 'production' && !req.secure) {
       return res.redirect(301, 'https://' + req.header('host') + req.url);
     }
     next();
   });

   // Or use middleware:
   const redirectHttps = (req, res, next) => {
     if (process.env.NODE_ENV === 'production' && req.header('x-forwarded-proto') !== 'https') {
       res.redirect(301, 'https://' + req.header('host') + req.url);
     } else {
       next();
     }
   };

   app.use(redirectHttps);
   ```

7. NO REQUEST SIZE LIMITS
   Severity: MEDIUM
   Issue: Without request size limits, application is vulnerable to buffer overflow and DoS attacks.

   Recommended Fix:
   ```javascript
   app.use(express.json({ limit: '10kb' }));
   app.use(express.urlencoded({ limit: '10kb', extended: true }));

   // Also set per-route limits if needed:
   app.post('/upload', express.json({ limit: '5mb' }), (req, res) => {
     // ...
   });
   ```

8. NO LOGGING AND MONITORING
   Severity: MEDIUM
   Issue: No audit trails for security incidents, making it impossible to detect attacks.

   Recommended Fix:
   ```javascript
   const morgan = require('morgan');
   const fs = require('fs');
   const path = require('path');

   // Create log stream
   const accessLogStream = fs.createWriteStream(
     path.join(__dirname, 'logs', 'access.log'),
     { flags: 'a' }
   );

   // Use morgan for HTTP request logging
   app.use(morgan(':remote-addr - :remote-user [:date[clf]] ":method :url HTTP/:http-version" :status :res[content-length] - :response-time ms', {
     stream: accessLogStream
   }));

   // Add custom error logging
   app.use((err, req, res, next) => {
     console.error({
       timestamp: new Date().toISOString(),
       method: req.method,
       url: req.url,
       ip: req.ip,
       error: err.message,
       stack: err.stack
     });

     res.status(err.status || 500).json({
       error: process.env.NODE_ENV === 'production' 
         ? 'Internal Server Error' 
         : err.message
     });
   });
   ```

9. NO ENVIRONMENT CONFIGURATION
   Severity: MEDIUM
   Issue: Hardcoded values and no use of environment variables for sensitive configuration.

   Recommended Fix:
   ```javascript
   require('dotenv').config();

   const PORT = process.env.PORT || 3000;
   const NODE_ENV = process.env.NODE_ENV || 'development';
   const JWT_SECRET = process.env.JWT_SECRET;

   if (!JWT_SECRET && NODE_ENV === 'production') {
     throw new Error('JWT_SECRET environment variable is not set');
   }

   if (!process.env.JWT_SECRET) {
     console.warn('WARNING: JWT_SECRET not set, using default (insecure)');
   }
   ```

10. SENSITIVE DATA EXPOSURE IN RESPONSES
    Severity: MEDIUM
    Issue: User email addresses are exposed in the /users endpoint without access control.

    Current Code:
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      ...
    ]);

    Recommended Fix:
    ```javascript
    const filterUserData = (user, isAdmin = false) => {
      const { id, name, email, role, ...rest } = user;

      if (isAdmin) {
        return { id, name, email, role };
      }

      // Regular users only get public data
      return { id, name };
    };

    app.get('/users', authenticateToken, (req, res) => {
      const users = [...];
      const isAdmin = req.user.role === 'admin';

      res.json(users.map(user => filterUserData(user, isAdmin)));
    });
    ```

========================================
MEDIUM PRIORITY ISSUES
========================================

11. NO DEPENDENCY VULNERABILITY SCANNING
    Severity: MEDIUM
    Issue: No mechanism to check for vulnerabilities in dependencies.

    Recommended Fix:
    ```bash
    # Add to package.json scripts:
    "scripts": {
      "audit": "npm audit",
      "audit:fix": "npm audit fix",
      "pretest": "npm audit"
    }
    ```

12. NO INPUT TYPE COERCION PROTECTION
    Severity: LOW
    Issue: Express doesn't validate Content-Type headers strictly.

    Recommended Fix:
    ```javascript
    app.use((req, res, next) => {
      if (['POST', 'PUT', 'PATCH'].includes(req.method)) {
        if (!req.is('application/json')) {
          return res.status(415).json({ error: 'Content-Type must be application/json' });
        }
      }
      next();
    });
    ```

========================================
OWASP TOP 10 MAPPING
========================================

A01:2021 - Broken Access Control
  Status: VULNERABLE
  Issues: No authentication, no authorization, no rate limiting
  Recommendations: Implement JWT authentication, role-based access control, rate limiting

