```javascript
// secrets-manager.js
const NODE_ENV = process.env.NODE_ENV || 'development';

class SecretsManager {
  static async loadSecrets() {
    switch (NODE_ENV) {
      case 'production':
        return this.loadFromAWSSecretsManager();
      case 'staging':
        return this.loadFromVault();
      case 'development':
      default:
        return this.loadFromDotEnv();
    }
  }

  static async loadFromAWSSecretsManager() {
    const AWS = require('aws-sdk');
    const secretsManager = new AWS.SecretsManager();

    try {
      const secret = await secretsManager
        .getSecretValue({ SecretId: 'prod/app/secrets' })
        .promise();
      return JSON.parse(secret.SecretString);
    } catch (error) {
      console.error('AWS Secrets Manager error:', error);
      throw error;
    }
  }

  static async loadFromVault() {
    const vault = require('node-vault');
    const client = vault({
      endpoint: process.env.VAULT_ADDR,
      token: process.env.VAULT_TOKEN,
    });

    try {
      const secret = await client.read('secret/data/staging/app');
      return secret.data.data;
    } catch (error) {
      console.error('Vault error:', error);
      throw error;
    }
  }

  static loadFromDotEnv() {
