**Recommendation**:
```javascript
const express = require('express');
const { body, param, validationResult, query } = require('express-validator');
const app = express();

app.use(express.json());

// Input validation middleware
const validateUserId = param('id')
  .isInt({ min: 1 })
  .withMessage('User ID must be a positive integer');

const validateEmail = body('email')
  .isEmail()
  .normalizeEmail()
  .withMessage('Invalid email format');

const validateName = body('name')
  .trim()
  .isLength({ min: 1, max: 100 })
  .matches(/^[a-zA-Z\s'-]+$/)
  .withMessage('Name contains invalid characters');

// Error handling middleware
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

app.get('/users/:id', validateUserId, handleValidationErrors, (req, res) => {
  const id = req.params.id; // Safe - already validated as integer
  res.json({ id, name: 'User', email: 'user@example.com' });
});

app.post('/users', 
  validateName, 
  validateEmail, 
  handleValidationErrors, 
  (req, res) => {
    const { name, email } = req.body;
    // Safe to use - validated and sanitized
    res.json({ id: 1, name, email });
  }
);
```

