### 7. **NO LOGGING & MONITORING** ⚠️ Medium
**Issue**: Security events are not logged.

**Risk**: Difficulty detecting and responding to security incidents

**OWASP**: A09:2021 - Logging and Monitoring Failures

**Recommendation**:
```javascript
const express = require('express');
const morgan = require('morgan');
const winston = require('winston');
const app = express();

// Security logging with Winston
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'logs/error.log', level: 'error' }),
    new winston.transports.File({ filename: 'logs/combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// HTTP request logging
app.use(morgan('combined'));

// Custom security logging middleware
app.use((req, res, next) => {
  const originalSend = res.send;
  res.send = function(data) {
    const statusCode = res.statusCode;

    // Log authentication failures
    if (statusCode === 401 || statusCode === 403) {
      logger.warn({
        event: 'AUTH_FAILURE',
        path: req.path,
        ip: req.ip,
        timestamp: new Date(),
      });
    }

    // Log suspicious patterns
    if (req.query && Object.keys(req.query).length > 5) {
      logger.warn({
        event: 'SUSPICIOUS_QUERY',
        path: req.path,
        queryCount: Object.keys(req.query).length,
      });
    }

    res.send = originalSend;
    return res.send(data);
  };
  next();
});

app.listen(3000, () => {
  logger.info('Server running on port 3000');
});
```

