## ✅ REMEDIATION: Secure Secrets Management

### **Option 1: AWS Secrets Manager (AWS Environments)** ⭐ RECOMMENDED

**Step 1: Create Secret in AWS Console or CLI**
```bash
aws secretsmanager create-secret \
  --name app/production/db \
  --secret-string '{"username":"admin","password":"SecureRandomPassword123!"}'

aws secretsmanager create-secret \
  --name app/production/aws-keys \
  --secret-string '{"access_key_id":"AKIA[REDACTED-EXAMPLE]","secret_access_key":"wJalrXUtnFEMI/K7MDENG/bPxRfiCYEXAMPLEKEY"}'
```

**Step 2: Install AWS SDK**
```bash
npm install aws-sdk
```

**Step 3: Create Secure Configuration Loader**
```javascript
// config/secrets.js
const AWS = require('aws-sdk');
const client = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

class SecretsManager {
  constructor() {
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const data = await client.getSecretValue({ SecretId: secretName }).promise();

      const secret = data.SecretString 
        ? JSON.parse(data.SecretString) 
        : Buffer.from(data.SecretBinary, 'base64').toString('ascii');

      // Cache with timestamp
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);
      throw error;
    }
  }

  async getSecretValue(secretName, key) {
    const secret = await this.getSecret(secretName);
    return key ? secret[key] : secret;
  }
}

module.exports = new SecretsManager();
```

**Step 4: Use in Application**
```javascript
// app.js
const express = require('express');
const secretsManager = require('./config/secrets');
const app = express();

app.get('/initialize', async (req, res) => {
  try {
    // Never store secrets in app state - retrieve on demand
    const dbConfig = await secretsManager.getSecret('app/production/db');
    const awsKeys = await secretsManager.getSecret('app/production/aws-keys');

    // Use credentials (don't log them!)
