```javascript
// config/vault.js
const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR || 'http://vault:8200',
  token: process.env.VAULT_TOKEN,
});

class VaultSecretsManager {
  constructor() {
    this.cache = new Map();
    this.cacheTTL = 300000; // 5 minutes
  }

  async getSecret(path) {
    const cached = this.cache.get(path);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const response = await vault.read(path);
      const secret = response.data.data || response.data;

      this.cache.set(path, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret from ${path}:`, error.message);
      throw error;
    }
  }

  async renew() {
    try {
      await vault.renewSelf();
    } catch (error) {
      console.error('Failed to renew Vault token:', error);
    }
  }
}

const manager = new VaultSecretsManager();

// Renew token periodically
setInterval(() => manager.renew(), 300000);

module.exports = manager;
```

