 * Returns user data only to authenticated users
 * Restricted to admin role for full list
 */
app.get('/users',
  authenticate,
  authorize('admin', 'user'),
  query('limit').optional().isInt({ min: 1, max: 100 }),
  query('offset').optional().isInt({ min: 0 }),
  validateQueryParams,
  (req, res) => {
