      res.json({
        data: paginatedUsers.map(u => ({
          id: u.id,
          name: u.name,
          // Email only shown to self or admins
          ...(req.user.role === 'admin' || req.user.id === u.id ? { email: u.email } : {})
        })),
        total: users.length,
        limit,
        offset,
        requestId: req.id
      });

      logger.info('Users fetched', {
        userId: req.user.id,
        count: paginatedUsers.length,
        requestId: req.id
      });
    } catch (err) {
      logger.error('Error fetching users', {
