// ==========================================
app.use((err, req, res, next) => {
  const requestId = req.id || 'unknown';

  logger.error('Unhandled error', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    requestId
  });

  // Don't expose internal error details to client
  const status = err.status || 500;
  const isDevelopment = process.env.NODE_ENV !== 'production';

  res.status(status).json({
    error: err.name || 'Internal Server Error',
    message: isDevelopment ? err.message : 'An error occurred',
    requestId,
    ...(isDevelopment && { stack: err.stack })
  });
});

// ==========================================
// 14. SERVER STARTUP
// ==========================================
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

const server = app.listen(PORT, HOST, () => {
  logger.info(`Server running on ${HOST}:${PORT}`, {
    environment: process.env.NODE_ENV || 'development',
    nodeVersion: process.version
  });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  logger.info('SIGINT signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  logger.error('Uncaught Exception', {
    message: err.message,
    stack: err.stack
  });
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection', {
    reason,
    promise
  });
  process.exit(1);
});

module.exports = app;

# Security Best Practices for Node.js/Express Applications

## 1. DEPENDENCY MANAGEMENT

### Recommended package.json with security focus:
```json
{
  "name": "secure-app",
  "version": "1.0.0",
  "description": "Secure Express application",
  "main": "app_secure.js",
  "scripts": {
    "start": "node app_secure.js",
    "dev": "NODE_ENV=development nodemon app_secure.js",
    "audit": "npm audit --audit-level=moderate",
    "security-check": "npm audit && snyk test"
  },
  "dependencies": {
    "express": "^4.18.2",
    "helmet": "^7.0.0",
    "cors": "^2.8.5",
    "express-rate-limit": "^7.0.0",
    "express-validator": "^7.0.0",
    "jsonwebtoken": "^9.0.0",
    "dotenv": "^16.0.3",
    "morgan": "^1.10.0",
    "winston": "^3.8.2",
    "bcryptjs": "^2.4.3"
  },
  "devDependencies": {
    "nodemon": "^3.0.0",
    "jest": "^29.0.0",
    "supertest": "^6.3.0"
  },
  "engines": {
    "node": ">=18.0.0"
  }
}
```

### Security Commands:
```bash
# Regular audits
npm audit                          # Check for vulnerabilities
npm audit fix                      # Auto-fix where possible
npm audit --audit-level=moderate  # Set minimum severity

# Dependency updates
npm update                         # Update all packages
npm outdated                       # Check for outdated packages

# Third-party security scanning
npm install -g snyk               # Install Snyk globally
snyk test                         # Test current project
snyk monitor                      # Monitor for vulnerabilities

# Dependency locking (always use lock files)
npm ci                            # Use package-lock.json
npm ci --production               # Production installation
```

---

## 2. AUTHENTICATION & AUTHORIZATION

### Password Hashing (DO NOT store plaintext):
```javascript
const bcrypt = require('bcryptjs');

// Hashing (registration)
const password = 'user-password';
const salt = await bcrypt.genSalt(10);
const passwordHash = await bcrypt.hash(password, salt);

// Verification (login)
const isPasswordValid = await bcrypt.compare(password, storedHash);
```

### JWT Token Management:
```javascript
const jwt = require('jsonwebtoken');

// Token creation
const token = jwt.sign(
  { id: user.id, role: user.role },
  process.env.JWT_SECRET,
  { 
    expiresIn: '1h',
    algorithm: 'HS256'
  }
);

// Token verification
const decoded = jwt.verify(token, process.env.JWT_SECRET);
```

---

## 3. INPUT VALIDATION & SANITIZATION

### Using express-validator:
```javascript
const { body, validationResult } = require('express-validator');

app.post('/register',
  body('email').isEmail().normalizeEmail(),
  body('username').trim().isLength({ min: 3, max: 20 }).matches(/^[a-zA-Z0-9_]+$/),
  body('password').isLength({ min: 12 }).matches(/[A-Z]/).matches(/[0-9]/),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Process valid input
  }
);
```

### SQL Injection Prevention (if using database):
```javascript
// ❌ WRONG - SQL Injection vulnerability
const users = await db.query(`SELECT * FROM users WHERE email = '${email}'`);

// ✅ CORRECT - Parameterized query
const users = await db.query('SELECT * FROM users WHERE email = $1', [email]);
```

---

## 4. SECURE DATA STORAGE

### Environment Variables:
```bash
# .gitignore - ALWAYS include these
.env
.env.local
.env.*.local
.env.test
.env.production.local
node_modules/
*.pem
*.key
.aws/
.ssh/

# Usage in code
require('dotenv').config();
const secret = process.env.JWT_SECRET;
```

### Production Secrets Management:
- AWS Secrets Manager
- HashiCorp Vault
- Azure Key Vault
- Google Secret Manager
- 1Password or Bitwarden

