## 5. HTTPS & TLS

### Let's Encrypt with Certbot (Recommended):
```bash
# Install certbot
sudo apt-get install certbot python3-certbot-nginx

# Get certificate
sudo certbot certonly --standalone -d example.com

# Auto-renewal
sudo systemctl enable certbot.timer
```

### Express with HTTPS:
```javascript
const https = require('https');
const fs = require('fs');

const options = {
  key: fs.readFileSync(process.env.KEY_PATH),
  cert: fs.readFileSync(process.env.CERT_PATH)
};

https.createServer(options, app).listen(443);

// Also redirect HTTP to HTTPS
const http = require('http');
http.createServer((req, res) => {
  res.writeHead(301, { Location: `https://${req.headers.host}${req.url}` });
  res.end();
}).listen(80);
```

---

## 6. SECURITY HEADERS

### Implemented by Helmet (already in secure version):
```javascript
const helmet = require('helmet');

app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"]
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  frameguard: { action: 'deny' },
  xssFilter: true,
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' }
}));
```

---

## 7. LOGGING & MONITORING

### Winston Logger Configuration:
```javascript
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'app' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
    new winston.transports.Console({ format: winston.format.simple() })
  ]
});

// Log security events
logger.warn('Unauthorized access attempt', { userId, ip });
logger.error('Database error', { error, requestId });
```

### What to Log:
- Authentication attempts (successes and failures)
- Authorization failures
- Data access patterns
- Error conditions
- Security-relevant configuration changes
- Rate limit violations

### What NOT to log:
- Passwords or API keys
- Personal data unnecessarily
- Full request bodies with sensitive data
- Session tokens

---

## 8. ERROR HANDLING

### Prevent Information Disclosure:
```javascript
// ❌ BAD - Exposes internal details
res.status(500).json({ error: err.message, stack: err.stack });

// ✅ GOOD - Generic message in production
const isDev = process.env.NODE_ENV !== 'production';
res.status(500).json({
  error: 'Internal Server Error',
  message: isDev ? err.message : undefined,
  requestId: req.id
});
```

---

## 9. RATE LIMITING & DDoS PROTECTION

### Express Rate Limit:
```javascript
const rateLimit = require('express-rate-limit');

// General API limiter
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests',
  standardHeaders: true,
  legacyHeaders: false
});

// Stricter auth limiter
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true
});

app.use(limiter);
app.post('/auth/login', authLimiter, ...);
```

### Advanced: Consider:
- CDN rate limiting (Cloudflare)
- Web Application Firewall (WAF)
- API Gateway (Kong, AWS API Gateway)

---

## 10. TESTING FOR SECURITY

### Security Testing Examples:
```javascript
// Using Jest and Supertest
const request = require('supertest');
const app = require('./app_secure');

describe('Security Tests', () => {
  test('Should reject requests without authentication', async () => {
    const res = await request(app).get('/users');
    expect(res.status).toBe(401);
  });

  test('Should reject invalid JWT tokens', async () => {
    const res = await request(app)
      .get('/users')
      .set('Authorization', 'Bearer invalid-token');
    expect(res.status).toBe(401);
  });

  test('Should include security headers', async () => {
    const res = await request(app).get('/health');
    expect(res.headers['x-content-type-options']).toBe('nosniff');
    expect(res.headers['x-frame-options']).toBe('DENY');
  });

  test('Should reject invalid input', async () => {
    const res = await request(app)
      .get('/health')
      .query({ format: 'invalid' });
    expect(res.status).toBe(400);
  });

  test('Should rate limit requests', async () => {
    // Send multiple requests
    for (let i = 0; i < 5; i++) {
      await request(app).post('/auth/login');
    }
    const res = await request(app).post('/auth/login');
    expect(res.status).toBe(429);
  });
});
```

