  const express = require('express');
  const { SecretsManagerClient, GetSecretValueCommand } = 
    require('@aws-sdk/client-secrets-manager');
  const helmet = require('helmet');

  const app = express();
  const secretsClient = new SecretsManagerClient({ 
    region: process.env.AWS_REGION || 'us-east-1' 
  });

  // Cache secrets with TTL (1 hour)
  const secretCache = new Map();
  const CACHE_TTL = 3600000;

  async function getSecret(secretName) {
    const now = Date.now();
    const cached = secretCache.get(secretName);

    if (cached && (now - cached.timestamp) < CACHE_TTL) {
      return cached.value;
    }

    try {
      const response = await secretsClient.send(
        new GetSecretValueCommand({ SecretId: secretName })
      );

      const secret = JSON.parse(response.SecretString);
      secretCache.set(secretName, { value: secret, timestamp: now });
      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret: ${secretName}`);
      throw error;
    }
  }

  // Initialize secrets on startup
  let dbCredentials, stripeKey, anthropicKey;

  (async () => {
    try {
      dbCredentials = await getSecret('prod/database');
      stripeKey = await getSecret('prod/stripe');
      anthropicKey = await getSecret('prod/anthropic');
    } catch (error) {
      console.error('Failed to load secrets during startup', error);
      process.exit(1);
    }
  })();

  app.use(helmet());

  // Never log secrets
  app.get('/health', (req, res) => {
    res.json({ status: 'ok' });
  });

  app.get('/users', (req, res) => {
    // Use secrets without exposing them
    // dbCredentials.username, stripeKey.secret_key, etc.
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  });

  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });

  module.exports = app;

