// Secure Express application with AWS Secrets Manager integration
// Secrets are never stored in .env files or version control

require('dotenv').config({ path: '.env.local' });

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const {
  SecretsManagerClient,
  GetSecretValueCommand,
} = require('@aws-sdk/client-secrets-manager');

const app = express();

// ============= CONFIGURATION =============

const config = {
  nodeEnv: process.env.NODE_ENV || 'development',
  port: parseInt(process.env.PORT) || 3000,
  awsRegion: process.env.AWS_REGION || 'us-east-1',
  corsOrigins: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  rateLimitWindow: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 900000,
  rateLimitMax: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100,
  cacheTTL: 3600000, // 1 hour
};

// ============= VALIDATION =============

function validateConfig() {
  const required = ['AWS_SECRET_NAME'];
  const missing = required.filter(key => !process.env[key]);

  if (missing.length > 0) {
    console.error(`Missing required environment variables: ${missing.join(', ')}`);
    console.error('Please check .env.example for required configuration');
    process.exit(1);
  }
}

validateConfig();

// ============= SECRETS MANAGER =============

const secretsClient = new SecretsManagerClient({
  region: config.awsRegion,
});

// Cache for secrets with TTL
const secretCache = new Map();

/**
 * Retrieve a secret from AWS Secrets Manager with caching
 * @param {string} secretName - Name of the secret to retrieve
 * @returns {Promise<Object>} The secret value
 */
async function getSecret(secretName) {
  const now = Date.now();
  const cached = secretCache.get(secretName);

  // Return cached secret if still valid
  if (cached && now - cached.timestamp < config.cacheTTL) {
    return cached.value;
  }

  try {
    const response = await secretsClient.send(
      new GetSecretValueCommand({ SecretId: secretName })
    );

    let secret;
    if (response.SecretString) {
      secret = JSON.parse(response.SecretString);
    } else {
      secret = Buffer.from(response.SecretBinary, 'base64').toString('utf8');
    }

    // Cache the secret
    secretCache.set(secretName, { value: secret, timestamp: now });

    return secret;
  } catch (error) {
    console.error(`Failed to retrieve secret "${secretName}":`, error.message);

    // If in development, try to use local .env as fallback
    if (config.nodeEnv === 'development') {
      console.warn('Development mode: attempting to use local .env as fallback');
      return {};
    }

    throw new Error(`Secret retrieval failed: ${secretName}`);
  }
}

// ============= SECURITY MIDDLEWARE =============

// Security headers
app.use(helmet());

// CORS protection
const corsOptions = {
  origin: function (origin, callback) {
    if (config.corsOrigins.indexOf(origin) !== -1 || !origin) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
};
