### Solution 1: **AWS Secrets Manager** (Recommended for AWS-based deployments)

```javascript
// config/secretsManager.js
const AWS = require('aws-sdk');

class SecretsManager {
  constructor() {
    this.secretsManagerClient = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1',
    });
    this.cache = {};
  }

  async getSecret(secretName) {
    // Return from cache if available
    if (this.cache[secretName]) {
      return this.cache[secretName];
    }

    try {
      const response = await this.secretsManagerClient
        .getSecretValue({ SecretId: secretName })
        .promise();

      let secretValue;
      if ('SecretString' in response) {
        secretValue = JSON.parse(response.SecretString);
      } else {
        secretValue = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
      }

      // Cache for 1 hour
      this.cache[secretName] = secretValue;
      setTimeout(() => delete this.cache[secretName], 3600000);

      return secretValue;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);
      throw error;
    }
  }
}

module.exports = new SecretsManager();
```

