// config/secretRotation.js
class SecretRotationManager {
  constructor(secretsManager) {
    this.secretsManager = secretsManager;
    this.rotationIntervals = new Map();
  }

  // Rotate secrets every 30 days
  scheduleRotation(secretName, rotationDays = 30) {
    const rotationMs = rotationDays * 24 * 60 * 60 * 1000;

    const interval = setInterval(async () => {
      try {
        console.log(`Rotating secret: ${secretName}`);
        await this.secretsManager.rotateSecret(secretName);
        console.log(`✓ Secret rotated successfully: ${secretName}`);
      } catch (error) {
        console.error(`✗ Failed to rotate secret: ${secretName}`, error);
      }
    }, rotationMs);

    this.rotationIntervals.set(secretName, interval);
  }

  stopRotation(secretName) {
    const interval = this.rotationIntervals.get(secretName);
    if (interval) {
      clearInterval(interval);
      this.rotationIntervals.delete(secretName);
    }
  }
}

module.exports = SecretRotationManager;
