  describe('Sensitive Data Handling', () => {

    test('Should not expose email in user list for non-admin', async () => {
      const token = createToken({ id: 1, username: 'user', role: 'user' });
      // This will fail auth check, but validates permission model
      const res = await request(app)
        .get('/users')
        .set('Authorization', `Bearer ${token}`);
      expect(res.statusCode).toBe(403);
    });

    test('Should return only required fields', async () => {
      const token = createToken({ id: 1, username: 'admin', role: 'admin' });
      const res = await request(app)
        .get('/users')
        .set('Authorization', `Bearer ${token}`);
      expect(res.statusCode).toBe(200);

      res.body.forEach(user => {
        // Should have id and name
        expect(user.id).toBeDefined();
        expect(user.name).toBeDefined();
        // Should NOT have email (exposed in original vulnerable code)
        // Email should only be visible if requester is admin
      });
    });
  });

  // ========================================================================
  // ERROR HANDLING
  // ========================================================================

  describe('Error Handling', () => {

    test('Should not expose stack trace in production', async () => {
      const originalEnv = process.env.NODE_ENV;
      process.env.NODE_ENV = 'production';

      const res = await request(app).get('/nonexistent');
      expect(res.statusCode).toBe(404);
      expect(res.body.details).toBeUndefined();

      process.env.NODE_ENV = originalEnv;
    });

    test('Should return proper 404 response', async () => {
      const res = await request(app).get('/api/nonexistent');
      expect(res.statusCode).toBe(404);
      expect(res.body.error).toBeDefined();
    });
  });
});
