});

/**
 * Get All Users Endpoint
 * Requires: Authentication + Admin role
 * Input: Pagination parameters (validated)
 * Returns: List of users (safe subset of data)
 */
app.get('/users',
  authenticateToken,
  authorizeRole(['admin']),
  validatePagination,
  handleValidationErrors,
  (req, res) => {
    const { limit, offset } = req.query;

    // Sample user data - in production, fetch from database
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination safely
    const paginatedUsers = allUsers.slice(offset, offset + limit);

    // Sanitize response
    const sanitizedUsers = paginatedUsers.map(user => ({
      id: Number(user.id),
      name: String(user.name).trim(),
      email: String(user.email).toLowerCase(),
    }));

    res.status(200).json({
      success: true,
      data: sanitizedUsers,
      pagination: {
        offset: Number(offset),
        limit: Number(limit),
        total: allUsers.length,
      },
      timestamp: new Date().toISOString(),
    });
  }
);

/**
 * Get Single User Endpoint
 * Requires: Authentication
 * Input: User ID (validated as integer)
 * Returns: Single user or 404
 */
app.get('/users/:id',
  authenticateToken,
  query('id').isInt({ min: 1 }).toInt(),
  handleValidationErrors,
  (req, res) => {
    const userId = parseInt(req.params.id, 10);

    // Validate user ID format
    if (isNaN(userId) || userId < 1) {
      return res.status(400).json({
        error: 'Invalid user ID format',
        code: 'INVALID_ID'
      });
    }

    // Check if user owns this data or is admin
    if (req.user.sub !== userId && !req.user.roles?.includes('admin')) {
      return res.status(403).json({
        error: 'Insufficient permissions',
        code: 'FORBIDDEN'
      });
    }

    // Sample data - in production, fetch from database
    const users = {
      1: { id: 1, name: 'Alice', email: 'alice@example.com' },
      2: { id: 2, name: 'Bob', email: 'bob@example.com' },
    };

    const user = users[userId];

    if (!user) {
      return res.status(404).json({
        error: 'User not found',
        code: 'NOT_FOUND'
      });
    }

    res.status(200).json({
      success: true,
      data: user,
      timestamp: new Date().toISOString(),
    });
  }
);

