      });
    }

    if (typeof username !== 'string' || typeof password !== 'string') {
      return res.status(400).json({
        error: 'Invalid input format',
        code: 'INVALID_FORMAT'
      });
    }

    // Limit string lengths to prevent DoS
    if (username.length > 50 || password.length > 128) {
