  ? ['DATABASE_URL', 'JWT_SECRET', 'API_KEY', 'STRIPE_SECRET_KEY']
  : ['NODE_ENV'];

const validateSecrets = () => {
  const missing = requiredSecrets.filter(s => !process.env[s]);
  if (missing.length > 0) {
    console.error(`❌ Missing secrets: ${missing.join(', ')}`);
    if (process.env.NODE_ENV === 'production') {
      process.exit(1);
    }
  }
