### Updated app.js with AWS Secrets Manager

```javascript
require('dotenv').config();
const express = require('express');
const AWS = require('aws-sdk');

const app = express();

// ==================== SECRETS MANAGEMENT ====================

const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

let cachedSecrets = null;
const CACHE_TTL = 3600000; // 1 hour
let lastCacheTime = 0;

/**
 * Retrieve secrets from AWS Secrets Manager with caching
 * @returns {Promise<Object>} Secrets object
 */
async function getSecrets() {
  const now = Date.now();

  // Return cached secrets if still valid
  if (cachedSecrets && (now - lastCacheTime) < CACHE_TTL) {
    return cachedSecrets;
  }

  try {
    const secretName = process.env.SECRETS_NAME || 'prod/app/credentials';

    const data = await secretsManager.getSecretValue({
      SecretId: secretName
    }).promise();

    let secrets;
    if ('SecretString' in data) {
      secrets = JSON.parse(data.SecretString);
    } else {
      secrets = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
    }

    cachedSecrets = secrets;
    lastCacheTime = now;

    console.log(`[${new Date().toISOString()}] Secrets refreshed from AWS Secrets Manager`);

    return secrets;
  } catch (error) {
    console.error('Error retrieving secrets from AWS Secrets Manager:', error);

    // Fallback to environment variables in development only
    if (process.env.NODE_ENV !== 'production') {
      console.warn('WARNING: Using environment variables fallback (development only)');
      return {
        DB_USER: process.env.DB_USER,
        DB_PASSWORD: process.env.DB_PASSWORD,
        JWT_SECRET: process.env.JWT_SECRET,
        AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
        AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
        ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
        STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
        LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN
      };
    }

    // In production, fail hard if secrets cannot be retrieved
    throw new Error('FATAL: Cannot retrieve secrets from AWS Secrets Manager');
  }
}

/**
 * Initialize secrets on startup
 */
async function initializeSecrets() {
  try {
    const secrets = await getSecrets();
    console.log('✓ Secrets loaded successfully');
    return secrets;
  } catch (error) {
    console.error('FATAL: Failed to initialize secrets:', error);
    process.exit(1);
  }
}

// ==================== MIDDLEWARE ====================

let secrets = null;

// Initialize secrets on startup
app.use(async (req, res, next) => {
  if (!secrets) {
    secrets = await initializeSecrets();
  }
  next();
});

// ==================== ROUTES ====================

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV
  });
});

app.get('/users', (req, res) => {
  // Secrets are now in memory from secrets manager, not from .env
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.get('/api/config', (req, res) => {
  // Never expose secrets! This is just for verification
  res.json({
    message: 'Secrets are loaded from AWS Secrets Manager',
    hasDbSecret: !!secrets.DB_PASSWORD,
    hasJwtSecret: !!secrets.JWT_SECRET,
    hasMtlsCert: !!secrets.MTLS_CERT
  });
});

// ==================== STARTUP ====================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} (${NODE_ENV})`);
  console.log('Secrets managed by AWS Secrets Manager');
});

module.exports = app;
```

