require('dotenv').config();
const express = require('express');
const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
  token: process.env.VAULT_TOKEN // From service account
});

const app = express();

let cachedSecrets = null;
const CACHE_TTL = 3600000; // 1 hour
let lastCacheTime = 0;

/**
 * Retrieve secrets from Vault with caching
 */
async function getSecrets() {
  const now = Date.now();

  if (cachedSecrets && (now - lastCacheTime) < CACHE_TTL) {
    return cachedSecrets;
  }

  try {
    const result = await vault.read('secret/data/app/credentials');
    cachedSecrets = result.data.data;
    lastCacheTime = now;

    console.log(`[${new Date().toISOString()}] Secrets refreshed from Vault`);

    return cachedSecrets;
  } catch (error) {
    console.error('Error retrieving secrets from Vault:', error);

    if (process.env.NODE_ENV !== 'production') {
      console.warn('WARNING: Using environment variables fallback (development only)');
      return process.env;
    }

    throw new Error('FATAL: Cannot retrieve secrets from Vault');
  }
}

let secrets = null;

app.use(async (req, res, next) => {
  if (!secrets) {
    secrets = await getSecrets();
  }
  next();
});

// ... routes here ...

app.listen(process.env.PORT || 3000, () => {
  console.log('Server running - Secrets from Vault');
});

module.exports = app;
```

