/**
 * SECURE VERSION OF app.js
 * Implements all recommended security best practices
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const { param, validationResult } = require('express-validator');
const winston = require('winston');
require('dotenv').config();

const app = express();

// ============================================================================
// LOGGER CONFIGURATION
// ============================================================================
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'secure-app' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Add security headers using helmet
app.use(helmet());

// 2. CORS configuration
const corsOptions = {
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization']
};
app.use(cors(corsOptions));

// 3. Body parsing middleware
app.use(express.json({ limit: '10kb' })); // Limit payload size

// 4. Request logging middleware
app.use((req, res, next) => {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;
    logger.info({
      method: req.method,
      path: req.path,
      status: res.statusCode,
      ip: req.ip,
      duration: `${duration}ms`,
      userAgent: req.get('user-agent'),
      timestamp: new Date().toISOString()
    });
  });

  next();
});

// 5. Rate limiting - Global
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(globalLimiter);

// 6. Rate limiting - Strict (for sensitive endpoints)
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many requests to this endpoint, please try again later.',
  skipSuccessfulRequests: false,
});

// ============================================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================================

const verifyToken = (req, res, next) => {
  try {
    const authHeader = req.headers.authorization;

    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      logger.warn(`Unauthorized access attempt to ${req.path} from ${req.ip}`);
      return res.status(401).json({ 
        error: 'Unauthorized: Missing or invalid token',
        code: 'MISSING_TOKEN'
      });
    }

    const token = authHeader.substring(7); // Remove 'Bearer ' prefix
    const decoded = jwt.verify(token, process.env.JWT_SECRET);

    req.userId = decoded.id;
    req.userRole = decoded.role || 'user';
    next();
  } catch (err) {
    logger.warn(`Invalid token attempt from ${req.ip}:`, err.message);

    const statusCode = err.name === 'TokenExpiredError' ? 401 : 403;
    const message = err.name === 'TokenExpiredError' 
      ? 'Token expired' 
      : 'Invalid token';

    return res.status(statusCode).json({ 
      error: `Unauthorized: ${message}`,
      code: err.name
    });
  }
};

// ============================================================================
// DATA SANITIZATION
// ============================================================================

/**
 * Sanitize user data - only return necessary fields
 * Prevents exposure of sensitive information
 */
const sanitizeUser = (user, includeEmail = false) => {
  const sanitized = {
    id: user.id,
    name: user.name
  };

  // Only include email if explicitly requested and user has permission
  if (includeEmail) {
    sanitized.email = user.email;
  }

  return sanitized;
};

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint
 * No authentication required (public)
 */
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok',
      service: 'user-api',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (err) {
    logger.error('Health check error:', err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Get all users
 * Requires authentication
 * Rate limited to prevent abuse
 */
app.get('/users', strictLimiter, verifyToken, (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Sanitize response - remove emails by default
    const sanitizedUsers = users.map(user => sanitizeUser(user, false));

    res.json({
      success: true,
      data: sanitizedUsers,
      timestamp: new Date().toISOString()
    });
  } catch (err) {
    logger.error('Error fetching users:', err);
    res.status(500).json({ 
      error: process.env.NODE_ENV === 'production' 
        ? 'Internal server error'
        : err.message
    });
  }
});

/**
 * Get user by ID
 * Requires authentication
 * Input validation on ID parameter
 */
app.get('/users/:id',
  strictLimiter,
  verifyToken,
  param('id').isInt({ min: 1, max: 2147483647 }).toInt(),
  (req, res) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          error: 'Invalid input',
          details: errors.array()
        });
      }

      const userId = req.params.id;

      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({ 
          error: 'User not found',
          code: 'USER_NOT_FOUND'
        });
      }

      // Check authorization - users can only see their own full profile
      const canSeeEmail = req.userId === user.id || req.userRole === 'admin';

      res.json({
        success: true,
        data: sanitizeUser(user, canSeeEmail),
        timestamp: new Date().toISOString()
      });
    } catch (err) {
      logger.error('Error fetching user:', err);
      res.status(500).json({ 
        error: process.env.NODE_ENV === 'production' 
          ? 'Internal server error'
          : err.message
      });
    }
  }
);

/**
 * Login endpoint - Create JWT token
 * (Simplified for demonstration - implement proper authentication)
 */
app.post('/login', globalLimiter, (req, res) => {
  try {
    // WARNING: This is simplified for demonstration
    // In production, verify credentials against a database with bcrypt
    const { username, password } = req.body;

    if (!username || !password) {
      return res.status(400).json({ 
        error: 'Username and password required'
      });
    }

    // Validate credentials (should use bcrypt in production)
    if (username !== 'demo' || password !== 'password') {
      logger.warn(`Failed login attempt for user: ${username}`);
      return res.status(401).json({ 
        error: 'Invalid credentials'
      });
    }

    // Create JWT token
    const token = jwt.sign(
      { 
        id: 1, 
        username: username,
        role: 'user'
      },
      process.env.JWT_SECRET,
      { expiresIn: '24h' }
    );

    res.json({
      success: true,
      token: token,
      expiresIn: '24h'
    });
  } catch (err) {
    logger.error('Login error:', err);
    res.status(500).json({ 
      error: process.env.NODE_ENV === 'production' 
        ? 'Internal server error'
        : err.message
    });
  }
});

// ============================================================================
// ERROR HANDLING
// ============================================================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    code: 'ENDPOINT_NOT_FOUND',
    path: req.path
  });
});

// Global error handler
app.use((err, req, res, next) => {
  logger.error({
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't expose stack traces in production
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error'
    : err.message;

  const statusCode = err.status || err.statusCode || 500;

  res.status(statusCode).json({ 
    error: message,
    code: 'INTERNAL_ERROR'
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Validate required environment variables
if (!process.env.JWT_SECRET) {
  logger.error('FATAL: JWT_SECRET environment variable not set');
  process.exit(1);
}

const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${NODE_ENV} mode`);
  console.log(`✓ Server running on port ${PORT}`);
  console.log(`✓ Environment: ${NODE_ENV}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  logger.info('SIGINT signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;
