**SECURE (Fixed):**
```javascript
const verifyToken = (req, res, next) => {
  try {
    const authHeader = req.headers.authorization;

    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.status(401).json({ 
        error: 'Unauthorized: Missing or invalid token'
      });
    }

    const token = authHeader.substring(7);
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.userId = decoded.id;
    next();
  } catch (err) {
    return res.status(403).json({ error: 'Invalid token' });
  }
};

app.get('/users', strictLimiter, verifyToken, (req, res) => {
  // Only authenticated users can access
  res.json({
    success: true,
    data: users.map(user => sanitizeUser(user, false))
  });
});
```
**Benefits:** 
- JWT-based authentication
- Token expiration
- Secure error handling

---

### 2. SENSITIVE DATA EXPOSURE

**VULNERABLE (Original):**
```javascript
{ id: 1, name: 'Alice', email: 'alice@example.com' }
```
**Problem:** Email exposed to all authenticated users.

**SECURE (Fixed):**
```javascript
const sanitizeUser = (user, includeEmail = false) => {
  const sanitized = {
    id: user.id,
    name: user.name
  };

  if (includeEmail) {
    sanitized.email = user.email;
  }

  return sanitized;
};

// Usage - emails hidden by default
users.map(user => sanitizeUser(user, false))
```
**Benefits:**
- Data minimization principle
- Conditional exposure based on permissions
- Reduced information leakage

---

### 3. NO SECURITY HEADERS

**VULNERABLE (Original):**
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```
**Problem:** No HTTP security headers set.

**SECURE (Fixed):**
```javascript
const helmet = require('helmet');

app.use(helmet()); // Automatically sets:
// - Content-Security-Policy
// - X-Frame-Options: DENY
// - X-Content-Type-Options: nosniff
// - X-XSS-Protection: 1; mode=block
// - Referrer-Policy: strict-origin-when-cross-origin
// - Strict-Transport-Security
```
**Benefits:**
- Protection against clickjacking (X-Frame-Options)
- XSS prevention (Content-Security-Policy)
- MIME type sniffing prevention
- HTTPS enforcement (HSTS)

