# Secrets Manager Implementation Guide

## Comparison of Solutions

### Option 1: AWS Secrets Manager ⭐⭐⭐⭐⭐

**Best for:** AWS-based applications

**Pros:**
- Native AWS integration
- Automatic rotation support
- Fine-grained IAM access control
- CloudTrail audit logging
- Database credential rotation
- Multi-region replication

**Cons:**
- AWS-specific (vendor lock-in)
- Price: ~$0.40/secret/month + API calls

**Setup Time:** 1-2 hours

```bash
# Install AWS SDK
npm install aws-sdk

# Create secret via AWS CLI
aws secretsmanager create-secret \
  --name prod/db/password \
  --secret-string '{"username":"admin","password":"SecureP@ssw0rd"}'

# Store another secret
aws secretsmanager create-secret \
  --name prod/stripe/api-key \
  --secret-string 'sk_live_your_real_key_here'
```

**Implementation:**

```javascript
const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager({ region: 'us-east-1' });

// Cache secrets to reduce API calls
const secretCache = new Map();

async function getSecret(secretName) {
  // Check cache first
  if (secretCache.has(secretName)) {
    return secretCache.get(secretName);
  }

  try {
    const response = await secretsManager.getSecretValue({ 
      SecretId: secretName 
    }).promise();

    let secret;
    if ('SecretString' in response) {
      secret = JSON.parse(response.SecretString);
    } else {
      secret = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
    }

    // Cache for 1 hour
    secretCache.set(secretName, secret);
    setTimeout(() => secretCache.delete(secretName), 3600000);

    return secret;
  } catch (err) {
    console.error(`Error retrieving secret ${secretName}:`, err);
    throw err;
  }
}

// Usage in app.js
async function initializeSecrets() {
  const dbSecret = await getSecret('prod/db/password');
  const stripeKey = await getSecret('prod/stripe/api-key');

  return { dbSecret, stripeKey };
}
```

**Cost:**
- First 100 secrets: $0/month
- Additional secrets: $0.40/secret/month
- API calls: $0.05 per 10,000 calls

---

### Option 2: HashiCorp Vault ⭐⭐⭐⭐

**Best for:** Multi-cloud, complex requirements

**Pros:**
- Cloud-agnostic
- Dynamic secrets generation
- Automatic credential rotation
- Audit logging
- Multi-tenant support
- Self-hosted (full control)

**Cons:**
- More complex to set up
- Requires separate infrastructure
- Steeper learning curve

**Setup Time:** 4-8 hours

```bash
# Install Vault CLI
brew install vault  # macOS
choco install vault # Windows

# Start development server
vault server -dev

# Initialize (outputs in dev mode)
# Set VAULT_ADDR and VAULT_TOKEN environment variables
export VAULT_ADDR='http://127.0.0.1:8200'
export VAULT_TOKEN='s.xxxxxxxxxxxxxxxx'

# Store secrets
vault kv put secret/prod/db/password \
  username=admin \
  password='SecureP@ssw0rd'

vault kv put secret/prod/stripe/api-key \
  key='sk_live_your_real_key_here'
```

**Implementation:**

```javascript
const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR,
  token: process.env.VAULT_TOKEN
});

const secretCache = new Map();

async function getSecret(path) {
  if (secretCache.has(path)) {
    return secretCache.get(path);
  }

  try {
    const response = await vault.read(`secret/data/${path}`);
    const secret = response.data.data;

    // Cache for 1 hour
    secretCache.set(path, secret);
    setTimeout(() => secretCache.delete(path), 3600000);

    return secret;
  } catch (err) {
    console.error(`Error retrieving secret ${path}:`, err);
    throw err;
  }
}

// Dynamic database credentials
async function getDynamicDBSecret() {
  try {
