const express = require('express');
const helmet = require('helmet');
const AWS = require('aws-sdk');
require('dotenv').config();

const app = express();

// Initialize AWS Secrets Manager
const secretsManager = new AWS.SecretsManager({ 
  region: process.env.AWS_REGION || 'us-east-1' 
});

// Secrets cache
const secretCache = new Map();
const CACHE_TTL = 3600000; // 1 hour

// Retrieve secret from Secrets Manager
async function getSecret(secretName) {
  if (secretCache.has(secretName)) {
    return secretCache.get(secretName);
  }

  try {
    console.log(`Retrieving secret: ${secretName}`);
    const response = await secretsManager.getSecretValue({ 
      SecretId: secretName 
    }).promise();

    let secret;
    if ('SecretString' in response) {
      secret = JSON.parse(response.SecretString);
    } else {
      secret = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
    }

    // Cache secret
    secretCache.set(secretName, secret);
    setTimeout(() => {
      console.log(`Cache expired for: ${secretName}`);
      secretCache.delete(secretName);
    }, CACHE_TTL);

    return secret;
  } catch (err) {
    console.error(`Error retrieving secret ${secretName}:`, err);
    throw err;
  }
}

// Initialize application
async function initializeApp() {
  try {
    // Get secrets
    console.log('Loading secrets...');
    const jwtSecret = await getSecret('prod/jwt/secret');
    const dbPassword = await getSecret('prod/db/password');
    const stripeKey = await getSecret('prod/stripe/api-key');

    console.log('Secrets loaded successfully');

    // Security headers
    app.use(helmet());

    // Health check
    app.get('/health', (req, res) => {
      res.json({ 
        status: 'ok',
        timestamp: new Date().toISOString()
      });
    });

    // Start server
    const PORT = process.env.PORT || 3000;
    app.listen(PORT, () => {
      console.log(`✓ Server running on port ${PORT}`);
      console.log(`✓ Secrets loaded from AWS Secrets Manager`);
    });
  } catch (err) {
    console.error('Fatal error during initialization:', err);
    process.exit(1);
  }
}

// Start app
initializeApp();

module.exports = app;
```

