### RECOMMENDED: AWS Secrets Manager Integration

```javascript
const AWS = require('aws-sdk');
const sm = new AWS.SecretsManager({ region: 'us-east-1' });

class SecretsManager {
  constructor() {
    this.cache = {};
    this.cacheTTL = 3600000; // 1 hour
    this.cacheTimestamps = {};
  }

  async getSecret(secretName) {
    // Return cached secret if fresh
    if (this.cache[secretName] && 
        Date.now() - this.cacheTimestamps[secretName] < this.cacheTTL) {
      return this.cache[secretName];
    }

    try {
      const data = await sm.getSecretValue({ SecretId: secretName }).promise();

      let secret;
      if (data.SecretString) {
        secret = JSON.parse(data.SecretString);
      } else {
        secret = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.cache[secretName] = secret;
      this.cacheTimestamps[secretName] = Date.now();

      return secret;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error);
      throw error;
    }
  }

  async getAllSecrets() {
    return {
      db: await this.getSecret('prod/database/credentials'),
      aws: await this.getSecret('prod/aws/credentials'),
      api: await this.getSecret('prod/api/keys'),
      jwt: await this.getSecret('prod/jwt/secret'),
    };
  }
}

const secretsManager = new SecretsManager();

// Usage in app.js
const secrets = await secretsManager.getSecret('prod/jwt/secret');
const JWT_SECRET = secrets.key;
```

**AWS Secrets Manager Benefits**:
- ✅ Centralized secret management
- ✅ Automatic secret rotation
- ✅ IAM-based access control
- ✅ Encryption at rest (KMS)
- ✅ Audit logging (CloudTrail)
- ✅ Secrets never stored locally
