**Recommendation: Strict Environment Separation**

```javascript
// config/secrets.js
const SecretsManager = require('./managers/SecretsManager');

const environments = {
  development: {
    source: 'dotenv', // .env.local only
    rotation: false,
  },
  staging: {
    source: 'aws-secrets-manager',
    region: 'us-east-1',
    secretPrefix: 'staging/',
  },
  production: {
    source: 'aws-secrets-manager',
    region: 'us-east-1',
    secretPrefix: 'prod/',
    rotation: 'automatic',
  },
};

const env = process.env.NODE_ENV || 'development';
const config = environments[env];

class ConfigManager {
  async load() {
    if (config.source === 'dotenv') {
      return this.loadFromDotenv();
    } else if (config.source === 'aws-secrets-manager') {
      return this.loadFromAWS(config);
    }
  }

  loadFromDotenv() {
    // Only load from .env.local (never committed)
    require('dotenv').config({ path: '.env.local' });

    if (!process.env.DATABASE_URL) {
      throw new Error('DATABASE_URL not found in .env.local');
    }

    return {
      database: process.env.DATABASE_URL,
      jwtSecret: process.env.JWT_SECRET,
      apiKeys: process.env.API_KEYS,
    };
  }

  async loadFromAWS(config) {
    const sm = new SecretsManager(config.region);

    return {
      database: await sm.getSecret(`${config.secretPrefix}database`),
      jwtSecret: await sm.getSecret(`${config.secretPrefix}jwt`),
      apiKeys: await sm.getSecret(`${config.secretPrefix}api-keys`),
    };
  }
}

module.exports = ConfigManager;
```

