/**
 * Configuration Management with Secrets Validation
 * 
 * This module handles environment variables and validates them on startup.
 * It provides a single source of truth for all configuration.
 */

require('dotenv').config();

// Define all required and optional environment variables
const ENVIRONMENT_SCHEMA = {
  // Required variables (will throw error if missing)
  required: {
    NODE_ENV: {
      type: 'string',
      default: 'development',
      validate: (val) => ['development', 'production', 'staging', 'test'].includes(val),
      errorMsg: 'NODE_ENV must be one of: development, production, staging, test',
    },
    PORT: {
      type: 'number',
      default: 3000,
      validate: (val) => val > 0 && val <= 65535,
      errorMsg: 'PORT must be between 1 and 65535',
    },
    JWT_SECRET: {
      type: 'string',
      validate: (val) => val && val.length >= 32,
      errorMsg: 'JWT_SECRET must be at least 32 characters long',
      sensitive: true,
    },
    ENCRYPTION_KEY: {
      type: 'string',
      validate: (val) => val && val.length >= 32,
      errorMsg: 'ENCRYPTION_KEY must be at least 32 characters long',
      sensitive: true,
    },
  },

  // Optional variables (will use defaults if missing)
  optional: {
    LOG_LEVEL: {
      type: 'string',
      default: 'info',
      validate: (val) => ['debug', 'info', 'warn', 'error'].includes(val),
    },
    CORS_ORIGIN: {
      type: 'string',
      default: 'http://localhost:3000',
    },
    DATABASE_URL: {
      type: 'string',
      default: null,
      sensitive: true,
    },
    AWS_SECRETS_MANAGER_ENABLED: {
      type: 'boolean',
      default: false,
    },
    DEBUG_MODE: {
      type: 'boolean',
      default: false,
    },
  },
};

/**
 * Parse and validate environment variables
 */
function loadConfiguration() {
  const config = {};
  const errors = [];
  const sensitiveKeys = [];

  // Process required variables
  Object.entries(ENVIRONMENT_SCHEMA.required).forEach(([key, schema]) => {
    const value = process.env[key];

    if (!value && !schema.default) {
      errors.push(`Missing required environment variable: ${key}`);
      return;
    }

    const finalValue = value || schema.default;

    // Type conversion
    const convertedValue = convertType(finalValue, schema.type);

    // Validation
    if (schema.validate && !schema.validate(convertedValue)) {
      errors.push(`${key}: ${schema.errorMsg}`);
      return;
    }

    config[key] = convertedValue;

    if (schema.sensitive) {
      sensitiveKeys.push(key);
    }
  });

  // Process optional variables
  Object.entries(ENVIRONMENT_SCHEMA.optional).forEach(([key, schema]) => {
    const value = process.env[key];
    const finalValue = value !== undefined ? value : schema.default;

    if (finalValue !== null && finalValue !== undefined) {
      config[key] = convertType(finalValue, schema.type);

      if (schema.sensitive) {
        sensitiveKeys.push(key);
      }
    }
  });

  // Throw if there are errors
  if (errors.length > 0) {
    console.error('❌ Configuration Validation Errors:');
    errors.forEach((err) => console.error(`  - ${err}`));
    process.exit(1);
  }

  // Log loaded configuration (hiding sensitive values)
  console.log('\n✅ Configuration loaded successfully');
  console.log('\n📋 Configuration Summary:');
  Object.entries(config).forEach(([key, value]) => {
    const masked = sensitiveKeys.includes(key) ? '***' : value;
    console.log(`   ${key}: ${masked}`);
  });
  console.log('');

  return {
    ...config,
    _sensitiveKeys: sensitiveKeys,
  };
}

/**
 * Convert string values to correct types
 */
function convertType(value, type) {
  switch (type) {
    case 'number':
      return parseInt(value, 10);
    case 'boolean':
      return value === 'true' || value === '1' || value === true;
    case 'string':
    default:
      return String(value);
  }
}

/**
 * Get config value with safe access
 */
function getConfig(key, defaultValue = undefined) {
  const config = module.exports.config;
  return config[key] !== undefined ? config[key] : defaultValue;
}

/**
 * Check if a config key is sensitive
 */
function isSensitive(key) {
  return module.exports.config._sensitiveKeys?.includes(key) || false;
}

/**
 * Export config object for safe logging
 */
function getConfigForLogging() {
  const config = module.exports.config;
  const safeConfig = { ...config };
  config._sensitiveKeys?.forEach((key) => {
    if (safeConfig[key]) {
      safeConfig[key] = '***' + (safeConfig[key] ? safeConfig[key].slice(-4) : '');
    }
  });
  delete safeConfig._sensitiveKeys;
  return safeConfig;
}

/**
 * Load AWS Secrets Manager secrets (if enabled)
 */
async function loadAwsSecrets() {
  if (module.exports.config.AWS_SECRETS_MANAGER_ENABLED !== true) {
    return;
  }

  try {
    const AWS = require('aws-sdk');
    const secretsManager = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1',
    });

    console.log('📡 Loading secrets from AWS Secrets Manager...');

    // Specify which secrets to load from AWS
    const secretsToLoad = [
      'app/jwt-secret',
      'app/encryption-key',
      'app/database-password',
    ];

    for (const secretName of secretsToLoad) {
      try {
        const secret = await secretsManager.getSecretValue({ SecretId: secretName }).promise();
        const secretValue = JSON.parse(secret.SecretString);

        // Map AWS secret names to config keys
        const keyMapping = {
          'app/jwt-secret': 'JWT_SECRET',
          'app/encryption-key': 'ENCRYPTION_KEY',
          'app/database-password': 'DATABASE_PASSWORD',
        };

        const configKey = keyMapping[secretName];
        if (configKey) {
          module.exports.config[configKey] = secretValue[secretName];
        }
      } catch (err) {
        if (err.code !== 'ResourceNotFoundException') {
          console.warn(`⚠️  Warning: Could not load secret ${secretName}: ${err.message}`);
        }
      }
    }

    console.log('✅ AWS Secrets loaded successfully');
  } catch (err) {
    console.error('❌ Failed to load AWS Secrets Manager:', err.message);
    process.exit(1);
  }
}

/**
 * Validate secrets periodically (checks if they haven't been rotated too long)
 */
function validateSecretRotation(lastRotationDate, maxAgeDays = 90) {
  const now = new Date();
  const rotationDate = new Date(lastRotationDate);
  const ageInDays = Math.floor((now - rotationDate) / (1000 * 60 * 60 * 24));

  if (ageInDays > maxAgeDays) {
    console.warn(`⚠️  Warning: Secrets are ${ageInDays} days old. Consider rotating them.`);
    return false;
  }
  return true;
}

// Load configuration on module require
const config = loadConfiguration();

module.exports = {
  config,
  getConfig,
  isSensitive,
  getConfigForLogging,
  loadAwsSecrets,
  validateSecretRotation,
};

/**
 * Secure Express Application with Proper Secrets Management
 * 
 * This is an improved version of app.js that:
 * - Loads secrets via configuration management
 * - Validates secrets on startup
 * - Never logs sensitive information
 * - Uses secure defaults
 */

const express = require('express');
const config = require('./config');

const app = express();

// Log configuration (safely, without secrets)
console.log('🔧 Application Configuration:');
console.log(config.getConfigForLogging());

// ============= MIDDLEWARE =============

// Request logging middleware (don't log Authorization headers)
app.use((req, res, next) => {
  const safeHeaders = { ...req.headers };
  delete safeHeaders.authorization;
  delete safeHeaders.cookie;

  console.log(`${new Date().toISOString()} ${req.method} ${req.path}`);
  next();
});

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: config.getConfig('NODE_ENV'),
  });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Error handler - never expose stack traces with sensitive info
app.use((err, req, res, next) => {
  console.error('Error:', err.message);
  res.status(err.status || 500).json({
    error: 'Internal Server Error',
    ...(config.getConfig('DEBUG_MODE') && { 
      details: err.message 
    }),
  });
});

// Start server using configured port
const port = config.getConfig('PORT');
app.listen(port, () => {
  console.log(`✅ Server running on port ${port}`);
  console.log(`📍 Environment: ${config.getConfig('NODE_ENV')}`);
});

module.exports = app;

