### PHASE 3: Secret Rotation & Monitoring

#### 1. Automated Secret Rotation

```javascript
// secret-rotation.js
const config = require('./config');
const crypto = require('crypto');

class SecretRotationManager {
  constructor() {
    this.rotationInterval = 90 * 24 * 60 * 60 * 1000; // 90 days
    this.lastRotationFile = './data/last-rotation.json';
  }

  async rotateJwtSecret() {
    console.log('🔄 Rotating JWT Secret...');

    const newSecret = crypto.randomBytes(32).toString('hex');

    // Update in AWS Secrets Manager
    const secretsManager = new (require('aws-sdk')).SecretsManager();
    await secretsManager.updateSecret({
      SecretId: 'app/jwt-secret',
      SecretString: JSON.stringify({ 'app/jwt-secret': newSecret }),
    }).promise();

    // Update config
    process.env.JWT_SECRET = newSecret;

    console.log('✅ JWT Secret rotated successfully');
    this.recordRotation('JWT_SECRET');
  }

  recordRotation(secretName) {
    const fs = require('fs');
    const data = {
      [secretName]: new Date().toISOString(),
    };
    fs.writeFileSync(this.lastRotationFile, JSON.stringify(data, null, 2));
  }

  checkRotationDue() {
    const fs = require('fs');
    if (!fs.existsSync(this.lastRotationFile)) {
      return true;
    }

    const data = JSON.parse(fs.readFileSync(this.lastRotationFile, 'utf8'));
    const lastRotation = new Date(data.JWT_SECRET);
    const now = new Date();

    return (now - lastRotation) > this.rotationInterval;
  }
}

module.exports = SecretRotationManager;
```

#### 2. Audit Logging for Secret Access

```javascript
// audit-logger.js
const fs = require('fs');
const path = require('path');

class AuditLogger {
  constructor() {
    this.logFile = path.join('./logs', 'secret-audit.log');
    this.ensureLogDirectory();
  }

  ensureLogDirectory() {
    const dir = path.dirname(this.logFile);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
  }

  logSecretAccess(secretName, action, status) {
    const timestamp = new Date().toISOString();
    const logEntry = {
      timestamp,
      secretName,
      action, // 'read', 'update', 'delete'
      status, // 'success', 'failure'
      pid: process.pid,
    };

    fs.appendFileSync(
      this.logFile,
      JSON.stringify(logEntry) + '\n'
    );
  }

  logSecretRotation(secretName, newVersion) {
    this.logSecretAccess(secretName, 'rotate', 'success');
  }
}

module.exports = AuditLogger;
```

