// EXAMPLE 4: Docker Secrets (Docker Swarm)
// ============================================================

/*
# Create secrets in Docker Swarm
docker secret create jwt_secret -
docker secret create encryption_key -
docker secret create db_password -

# Reference in service
version: '3.8'
services:
  app:
    image: app:latest
    secrets:
      - jwt_secret
      - encryption_key
      - db_password
    environment:
      JWT_SECRET_FILE: /run/secrets/jwt_secret
      ENCRYPTION_KEY_FILE: /run/secrets/encryption_key
      DATABASE_PASSWORD_FILE: /run/secrets/db_password

secrets:
  jwt_secret:
    external: true
  encryption_key:
    external: true
  db_password:
    external: true
*/

// Read secrets from files (Docker Secrets style)
const fs = require('fs');

function loadSecretsFromFiles() {
  const secrets = {};

  // JWT Secret
  if (process.env.JWT_SECRET_FILE) {
    secrets.JWT_SECRET = fs.readFileSync(process.env.JWT_SECRET_FILE, 'utf8').trim();
  }

  // Encryption Key
  if (process.env.ENCRYPTION_KEY_FILE) {
    secrets.ENCRYPTION_KEY = fs.readFileSync(process.env.ENCRYPTION_KEY_FILE, 'utf8').trim();
  }

  // Database Password
  if (process.env.DATABASE_PASSWORD_FILE) {
    secrets.DATABASE_PASSWORD = fs.readFileSync(process.env.DATABASE_PASSWORD_FILE, 'utf8').trim();
  }

  return secrets;
}

// ============================================================
// EXAMPLE 5: HashiCorp Vault
// ============================================================

const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
  token: process.env.VAULT_TOKEN,
});

async function initializeFromVault() {
  try {
    // Authenticate if using AppRole or other methods
    if (process.env.VAULT_ROLE_ID && process.env.VAULT_SECRET_ID) {
      const approleAuth = await vault.approleLogin({
        role_id: process.env.VAULT_ROLE_ID,
        secret_id: process.env.VAULT_SECRET_ID,
      });
      vault.token = approleAuth.auth.client_token;
    }

    // Read secrets from Vault
    const jwtSecret = await vault.read('secret/data/app/jwt-secret');
    process.env.JWT_SECRET = jwtSecret.data.data.value;

    const encKey = await vault.read('secret/data/app/encryption-key');
    process.env.ENCRYPTION_KEY = encKey.data.data.value;

    const dbCreds = await vault.read('secret/data/app/database');
    const creds = dbCreds.data.data;
    process.env.DATABASE_URL = `postgresql://${creds.username}:${creds.password}@${creds.host}:5432/${creds.dbname}`;

    console.log('✅ Secrets loaded from Vault');
    return true;
  } catch (err) {
    console.error('❌ Failed to load from Vault:', err);
    process.exit(1);
  }
}

