    process.env.ENCRYPTION_KEY = encKey.value;

    const dbPassword = await client.getSecret('app-database-password');
    process.env.DATABASE_PASSWORD = dbPassword.value;

    console.log('✅ Secrets loaded from Azure Key Vault');
    return true;
  } catch (err) {
    console.error('❌ Failed to load from Azure Key Vault:', err);
    process.exit(1);
  }
}

// ============================================================
// EXAMPLE 7: Google Secret Manager
// ============================================================

const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');

async function initializeFromGoogleSecrets() {
  try {
    const client = new SecretManagerServiceClient();
    const projectId = process.env.GOOGLE_CLOUD_PROJECT;

    // Helper function to get secret
    async function getSecret(secretName) {
      const name = client.secretVersionPath(projectId, secretName, 'latest');
      const [version] = await client.accessSecretVersion({ name });
      return version.payload.data.toString('utf8');
    }

    // Fetch secrets
    process.env.JWT_SECRET = await getSecret('app-jwt-secret');
    process.env.ENCRYPTION_KEY = await getSecret('app-encryption-key');
    process.env.DATABASE_PASSWORD = await getSecret('app-database-password');

    console.log('✅ Secrets loaded from Google Secret Manager');
    return true;
  } catch (err) {
    console.error('❌ Failed to load from Google Secrets:', err);
    process.exit(1);
  }
}

// ============================================================
// EXAMPLE 8: Combining Multiple Secret Sources (Priority Order)
// ============================================================

async function loadSecretsWithFallback() {
  let secretsLoaded = false;

  // Priority 1: AWS Secrets Manager
  if (process.env.AWS_REGION && !secretsLoaded) {
    try {
      await initializeFromAWSSecrets();
      secretsLoaded = true;
      console.log('Using AWS Secrets Manager');
    } catch (err) {
      console.warn('AWS Secrets Manager unavailable, trying next source...');
    }
  }

  // Priority 2: HashiCorp Vault
  if (process.env.VAULT_ADDR && !secretsLoaded) {
    try {
      await initializeFromVault();
      secretsLoaded = true;
      console.log('Using HashiCorp Vault');
    } catch (err) {
      console.warn('Vault unavailable, trying next source...');
    }
  }

  // Priority 3: Kubernetes Secrets (from environment)
  if (process.env.KUBERNETES_SERVICE_HOST && !secretsLoaded) {
    console.log('Using Kubernetes Secrets (from environment)');
    secretsLoaded = true;
  }

  // Priority 4: Docker Secrets
  if (!secretsLoaded) {
    const secrets = loadSecretsFromFiles();
    if (Object.keys(secrets).length > 0) {
      Object.assign(process.env, secrets);
      console.log('Using Docker Secrets');
      secretsLoaded = true;
    }
  }

  // Priority 5: Environment variables / .env
  if (!secretsLoaded) {
    console.log('Using environment variables / .env file');
    secretsLoaded = true;
  }

  if (!secretsLoaded) {
    console.error('❌ No secrets loaded from any source');
    process.exit(1);
  }
}

// ============================================================
// EXAMPLE 9: Secrets Rotation Implementation
// ============================================================

class SecretsRotationService {
  constructor(rotationIntervalDays = 90) {
    this.rotationIntervalMs = rotationIntervalDays * 24 * 60 * 60 * 1000;
    this.lastRotation = {};
  }

  async rotateSecret(secretName, rotationFunction) {
    const now = Date.now();
    const lastRotationTime = this.lastRotation[secretName] || 0;
    const timeSinceLastRotation = now - lastRotationTime;

    if (timeSinceLastRotation >= this.rotationIntervalMs) {
      try {
        console.log(`🔄 Rotating ${secretName}...`);
        const newSecret = await rotationFunction();
        this.lastRotation[secretName] = now;
        console.log(`✅ ${secretName} rotated successfully`);
        return newSecret;
      } catch (err) {
        console.error(`❌ Failed to rotate ${secretName}:`, err);
        throw err;
      }
    }

    return null; // No rotation needed
  }

  scheduleRotations(secretConfigs) {
    // Check daily if rotation is needed
    setInterval(async () => {
      for (const config of secretConfigs) {
        await this.rotateSecret(config.name, config.rotationFunction);
      }
    }, 24 * 60 * 60 * 1000); // Daily check
  }
}

// ============================================================
// EXAMPLE 10: Secure Logging with Secrets Masking
// ============================================================

function maskSecrets(text) {
  if (!text) return text;

  const sensitivePatterns = [
    /JWT_SECRET[=:]\s*([^\s,}]+)/gi,
    /ENCRYPTION_KEY[=:]\s*([^\s,}]+)/gi,
    /DATABASE_PASSWORD[=:]\s*([^\s,}]+)/gi,
    /Authorization:\s*Bearer\s+([^\s]+)/gi,
    /"secret"\s*:\s*"([^"]+)"/gi,
  ];

  let masked = String(text);
  sensitivePatterns.forEach((pattern) => {
    masked = masked.replace(pattern, (match, secret) => {
      const maskedSecret = secret.substring(0, 4) + '***' + secret.substring(secret.length - 4);
      return match.replace(secret, maskedSecret);
    });
  });

  return masked;
}

// Usage in logging
console.log(maskSecrets('JWT_SECRET=abc123def456ghi789'));
// Output: JWT_SECRET=abc1***789

// ============================================================
// EXPORTS FOR USE IN MAIN APP
// ============================================================

module.exports = {
  loadSecretsWithFallback,
  loadSecretsFromFiles,
  initializeFromAWSSecrets,
  initializeFromVault,
  initializeFromAzureKeyVault,
  initializeFromGoogleSecrets,
  SecretsRotationService,
  maskSecrets,
};

