// Secure Express.js Application Template
// Implements OWASP Top 10 security best practices

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, param, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');

const app = express();

// ============================================================================
// ENVIRONMENT CONFIGURATION
// ============================================================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const JWT_SECRET = process.env.JWT_SECRET;
const ALLOWED_ORIGINS = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',');

// Validate required environment variables
if (NODE_ENV === 'production' && !JWT_SECRET) {
  throw new Error('JWT_SECRET environment variable is required in production');
}

// ============================================================================
// SECURITY MIDDLEWARE - Layer 1: Request Size & Parsing
// ============================================================================

app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// ============================================================================
// SECURITY MIDDLEWARE - Layer 2: HTTP Headers (Helmet)
// ============================================================================

app.use(helmet());

// ============================================================================
// SECURITY MIDDLEWARE - Layer 3: CORS
// ============================================================================

const corsOptions = {
  origin: (origin, callback) => {
    if (!origin || ALLOWED_ORIGINS.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
  optionsSuccessStatus: 200,
};

app.use(cors(corsOptions));

// ============================================================================
// SECURITY MIDDLEWARE - Layer 4: Rate Limiting
// ============================================================================

const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
});

app.use(generalLimiter);

// ============================================================================
// SECURITY MIDDLEWARE - Layer 5: HTTPS Enforcement
// ============================================================================

if (NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (!req.secure && req.get('x-forwarded-proto') !== 'https') {
      return res.redirect(301, `https://${req.get('host')}${req.url}`);
    }
    next();
  });
}

// ============================================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================================

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  try {
    const decoded = jwt.verify(token, JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    console.warn('[SECURITY] Invalid token attempt', { 
      ip: req.ip, 
      error: err.message 
    });
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
};

// ============================================================================
// AUTHORIZATION MIDDLEWARE
// ============================================================================

const authorizeRole = (roles) => {
  return (req, res, next) => {
    if (!req.user || !roles.includes(req.user.role)) {
      console.warn('[SECURITY] Authorization denied', { 
        user: req.user?.id, 
        requiredRoles: roles 
      });
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
};

// ============================================================================
// ROUTES
// ============================================================================

// Public health check endpoint
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    ...(NODE_ENV === 'development' && { 
      timestamp: new Date().toISOString(),
      environment: NODE_ENV,
    }),
  });
});

// Public login endpoint (simplified example)
app.post('/login', strictLimiter, [
  body('username').isLength({ min: 3, max: 50 }).trim().escape(),
  body('password').isLength({ min: 8 }).withMessage('Password must be at least 8 characters'),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // In real app: verify credentials against database
  // This is a simplified example
  if (req.body.username === 'alice' && req.body.password === 'password123') {
    const token = jwt.sign(
      { id: 1, username: 'alice', role: 'admin' },
      JWT_SECRET,
      { expiresIn: '1h' }
    );
    return res.json({ token });
  }

  console.warn('[SECURITY] Failed login attempt', { 
    username: req.body.username,
    ip: req.ip,
  });
  res.status(401).json({ error: 'Invalid credentials' });
});

// Protected endpoint - Get all users (admin only)
app.get('/users', 
  authenticateToken, 
  authorizeRole(['admin']), 
  (req, res) => {
    // Return masked/safe data only
    const users = [
      { id: 1, name: 'Alice', role: 'admin' },
      { id: 2, name: 'Bob', role: 'user' },
    ];

    res.json(users);
  }
);

// Protected endpoint - Get single user
app.get('/users/:id',
  authenticateToken,
  param('id').isInt().withMessage('ID must be an integer'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const userId = parseInt(req.params.id, 10);

    // Authorization check: users can only see their own profile unless admin
    if (req.user.id !== userId && req.user.role !== 'admin') {
