      } else if (this.provider === 'vault') {
        return this.initializeVault();
      } else if (this.provider === 'env') {
        return this.initializeEnv();
      }
    }

    async getSecret(key, options = {}) {
      // Check cache first
      if (this.cache[key] && !options.noCache) {
        return this.cache[key];
      }

      let value;
      if (this.provider === 'aws') {
        value = await this.getFromAWS(key);
      } else if (this.provider === 'vault') {
        value = await this.getFromVault(key);
      } else {
        value = this.getFromEnv(key);
      }

      if (!value && options.required) {
        throw new Error(`Required secret not found: ${key}`);
      }

      // Cache for TTL
      if (options.cacheTTL) {
        this.cache[key] = value;
        setTimeout(() => delete this.cache[key], options.cacheTTL);
      }

      return value;
    }

    async initializeAWS() {
      const AWS = require('aws-sdk');
      this.awsClient = new AWS.SecretsManager();
    }

    async getFromAWS(key) {
      try {
        const data = await this.awsClient.getSecretValue({
          SecretId: key
        }).promise();
        return data.SecretString || 
               Buffer.from(data.SecretBinary, 'base64').toString();
      } catch (error) {
        logger.error(`Failed to get AWS secret ${key}`, error);
        throw error;
      }
    }

    async initializeVault() {
      const vault = require('node-vault')({
        endpoint: process.env.VAULT_ADDR,
        token: process.env.VAULT_TOKEN
      });
      this.vaultClient = vault;
    }

    async getFromVault(key) {
      try {
        const secret = await this.vaultClient.read(`secret/data/${key}`);
        return secret.data.data.value;
      } catch (error) {
        logger.error(`Failed to get Vault secret ${key}`, error);
        throw error;
      }
    }

    async initializeEnv() {
      // Validate required secrets exist
      const required = [
        'DATABASE_URL',
        'JWT_SECRET',
        'ANTHROPIC_API_KEY'
      ];

      for (const key of required) {
        if (!process.env[key]) {
          throw new Error(`Missing required environment variable: ${key}`);
        }
      }
    }

    getFromEnv(key) {
      const value = process.env[key];
      if (!value) {
        logger.warn(`Environment variable not found: ${key}`);
      }
      return value;
    }
  }

  module.exports = new SecretsManager();


