/**
 * Secrets Manager - Abstraction layer for multiple secret backends
 * Supports: AWS Secrets Manager, HashiCorp Vault, Environment Variables
 */

const logger = require('./logger');

class SecretsManager {
  constructor() {
    this.cache = new Map();
    this.provider = process.env.SECRETS_PROVIDER || 'env';
    this.initialized = false;
  }

  async initialize() {
    if (this.initialized) {
      return;
    }

    logger.info(`Initializing secrets manager with provider: ${this.provider}`);

    try {
      switch (this.provider) {
        case 'aws':
          await this.initializeAWS();
          break;
        case 'vault':
          await this.initializeVault();
          break;
        case 'env':
          await this.initializeEnv();
          break;
        default:
          throw new Error(`Unknown secrets provider: ${this.provider}`);
      }
      this.initialized = true;
    } catch (error) {
      logger.error('Failed to initialize secrets manager', error);
      throw error;
    }
  }

  async getSecret(key, options = {}) {
    const { required = false, noCache = false, cacheTTL = 3600000 } = options;

    // Check cache first
    if (!noCache && this.cache.has(key)) {
      const cached = this.cache.get(key);
      if (Date.now() < cached.expiry) {
        logger.debug(`Retrieved ${key} from cache`);
        return cached.value;
      } else {
        this.cache.delete(key);
      }
    }

    let value;

    try {
      switch (this.provider) {
        case 'aws':
          value = await this.getFromAWS(key);
          break;
        case 'vault':
          value = await this.getFromVault(key);
          break;
        case 'env':
          value = this.getFromEnv(key);
          break;
      }
    } catch (error) {
      logger.error(`Error retrieving secret ${key}`, error);
      if (required) {
        throw error;
      }
      return undefined;
    }

    if (!value && required) {
      throw new Error(`Required secret not found: ${key}`);
    }

    // Cache the value
    if (value && cacheTTL > 0) {
      this.cache.set(key, {
        value,
        expiry: Date.now() + cacheTTL
      });
    }

    return value;
  }

  async initializeAWS() {
    try {
      const AWS = require('aws-sdk');
      this.awsClient = new AWS.SecretsManager({
        region: process.env.AWS_REGION || 'us-east-1'
      });
      logger.info('AWS Secrets Manager initialized');
    } catch (error) {
      throw new Error('Failed to initialize AWS SDK: ' + error.message);
    }
  }

  async getFromAWS(key) {
    try {
      const data = await this.awsClient.getSecretValue({
        SecretId: key
      }).promise();

      if ('SecretString' in data) {
        return JSON.parse(data.SecretString);
      } else {
        return Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }
    } catch (error) {
      if (error.code === 'ResourceNotFoundException') {
        logger.warn(`Secret not found in AWS: ${key}`);
        return undefined;
      }
      throw new Error(`AWS Secrets Manager error: ${error.message}`);
    }
  }

  async initializeVault() {
    try {
      const vault = require('node-vault')({
        endpoint: process.env.VAULT_ADDR,
        token: process.env.VAULT_TOKEN
      });
      this.vaultClient = vault;
      logger.info('HashiCorp Vault initialized');
    } catch (error) {
      throw new Error('Failed to initialize Vault: ' + error.message);
    }
  }

  async getFromVault(key) {
    try {
      const secret = await this.vaultClient.read(`secret/data/${key}`);
      return secret.data.data;
    } catch (error) {
      if (error.statusCode === 404) {
        logger.warn(`Secret not found in Vault: ${key}`);
        return undefined;
      }
      throw new Error(`Vault error: ${error.message}`);
    }
  }

  async initializeEnv() {
    // Validate required environment variables for local development
    const required = [
      'DATABASE_URL',
      'JWT_SECRET'
    ];

    const missing = required.filter(key => !process.env[key]);
    if (missing.length > 0) {
      throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
    }

    logger.info('Environment variable secrets initialized');
  }

  getFromEnv(key) {
    const value = process.env[key];
    if (!value) {
      logger.debug(`Environment variable not found: ${key}`);
    }
    return value;
  }

  /**
   * Get all secrets for a given prefix (AWS only)
   */
  async getAllSecretsWithPrefix(prefix) {
    if (this.provider !== 'aws') {
      throw new Error('getAllSecretsWithPrefix only supported with AWS provider');
    }

    try {
      const secrets = {};
      const paginator = this.awsClient.listSecrets({ Filters: [{ Key: 'name', Values: [`${prefix}*`] }] });

      for await (const page of paginator) {
        for (const secret of page.SecretList || []) {
          const value = await this.getFromAWS(secret.Name);
          secrets[secret.Name] = value;
        }
      }

      return secrets;
    } catch (error) {
      logger.error(`Failed to list secrets with prefix ${prefix}`, error);
      throw error;
    }
  }

  /**
   * Clear cache
   */
  clearCache() {
    this.cache.clear();
    logger.info('Secrets cache cleared');
  }
}

module.exports = new SecretsManager();

