const AWS = require('aws-sdk');

class SecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1',
    });
    this.cache = {};
  }

  async getSecret(secretName) {
    // Return from cache if fresh
    if (this.cache[secretName]?.expiry > Date.now()) {
      return this.cache[secretName].value;
    }

    try {
      const response = await this.client
        .getSecretValue({ SecretId: secretName })
        .promise();

      const secret = response.SecretString 
        ? JSON.parse(response.SecretString) 
        : response.SecretBinary;

      // Cache for 1 hour
      this.cache[secretName] = {
        value: secret,
        expiry: Date.now() + (60 * 60 * 1000),
      };

      return secret;
    } catch (err) {
      console.error(`Failed to retrieve secret: ${secretName}`, err);
      throw err;
    }
  }

  async getDatabaseCredentials() {
    return this.getSecret('prod/database/credentials');
  }

  async getAwsCredentials() {
    return this.getSecret('prod/aws/credentials');
  }

  async getApiKeys() {
    return this.getSecret('prod/api-keys');
  }
}

module.exports = SecretsManager;
