const AWS = require('aws-sdk');

class ProductionSecretsManager {
  constructor() {
    this.secretsClient = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1',
    });
    this.cache = new Map();
    this.cacheExpiry = 60 * 60 * 1000; // 1 hour
  }

  async getSecret(secretName) {
    const cached = this.cache.get(secretName);

    if (cached && cached.expiry > Date.now()) {
      console.log(`Using cached secret: ${secretName}`);
      return cached.value;
    }

    try {
      const response = await this.secretsClient
        .getSecretValue({ SecretId: secretName })
        .promise();

      const secret = response.SecretString 
        ? JSON.parse(response.SecretString)
        : response.SecretBinary;

      // Store in cache
      this.cache.set(secretName, {
        value: secret,
        expiry: Date.now() + this.cacheExpiry,
      });

      return secret;
    } catch (error) {
      console.error(`SecretManager error for ${secretName}:`, error.message);

      // Audit log
      this.logSecretAccess(secretName, 'FAILED', error.message);

      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  logSecretAccess(secretName, status, details) {
    console.log(JSON.stringify({
      timestamp: new Date().toISOString(),
      secretName,
      status,
      details,
      source: 'SecretsManager',
    }));
  }

  async getAllSecrets() {
    const secrets = {};
    const secretNames = [
      'prod/database/connection',
      'prod/aws/credentials',
      'prod/api-keys',
      'prod/jwt-signing-key',
    ];

    for (const name of secretNames) {
      secrets[name] = await this.getSecret(name);
    }

    return secrets;
  }
}

module.exports = new ProductionSecretsManager();
