// ============ SECURE SECRETS LOADING (AWS Secrets Manager) ============

const AWS = require('aws-sdk');
const client = new AWS.SecretsManager({ region: process.env.AWS_REGION || 'us-east-1' });

class SecretsManager {
  constructor() {
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour cache
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && cached.expiry > Date.now()) {
      return cached.value;
    }

    try {
      const data = await client.getSecretValue({ SecretId: secretName }).promise();

      // Parse JSON if it's a structured secret
      let secretValue = data.SecretString ? JSON.parse(data.SecretString) : data.SecretBinary;

      // Cache the secret with TTL
      this.cache.set(secretName, {
        value: secretValue,
        expiry: Date.now() + this.cacheTTL,
      });

      return secretValue;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }
}

const secretsManager = new SecretsManager();

// Usage in application
app.get('/users', async authenticate, async (req, res) => {
  try {
    const dbConfig = await secretsManager.getSecret('production/database');
    // Use dbConfig.host, dbConfig.username, dbConfig.password, etc.

    res.json([
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ]);
  } catch (error) {
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

module.exports = app;
```

