// ============ SECURE SECRETS LOADING (HashiCorp Vault) ============

const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR || 'https://vault.example.com',
  token: process.env.VAULT_TOKEN,
});

class VaultSecretsManager {
  constructor() {
    this.cache = new Map();
  }

  async getSecret(path) {
    const cached = this.cache.get(path);
    if (cached && cached.expiry > Date.now()) {
      return cached.value;
    }

    try {
      const result = await vault.read(`secret/data/${path}`);
      const secretValue = result.data.data;

      this.cache.set(path, {
        value: secretValue,
        expiry: Date.now() + 3600000, // 1 hour
      });

      return secretValue;
    } catch (error) {
      console.error(`Failed to retrieve secret from Vault at ${path}:`, error);
      throw new Error(`Vault secret retrieval failed`);
    }
  }

  async rotateSecret(path, newSecret) {
    try {
      await vault.write(`secret/data/${path}`, {
        data: newSecret,
      });
      this.cache.delete(path);
      console.log(`Secret rotated at ${path}`);
    } catch (error) {
      console.error(`Failed to rotate secret:`, error);
      throw error;
    }
  }
}

const vaultSecrets = new VaultSecretsManager();

app.get('/users', authenticate, async (req, res) => {
