const xss = require('xss-clean');
const cors = require('cors');

const app = express();

// ===== SECURITY MIDDLEWARE =====

// 1. Set security HTTP headers
app.use(helmet());

// 2. Data sanitization against NoSQL injection
app.use(mongoSanitize());

// 3. Data sanitization against XSS attacks
app.use(xss());

// 4. CORS configuration - restrict to trusted origins
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  optionsSuccessStatus: 200,
  allowedHeaders: ['Content-Type', 'Authorization']
};
app.use(cors(corsOptions));

// 5. Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in RateLimit-* headers
  legacyHeaders: false, // Disable X-RateLimit-* headers
});

// Apply rate limiter to all routes
app.use('/api/', limiter);

// Stricter rate limiter for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true, // Only count failed requests
});

// 6. Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ===== INPUT VALIDATION =====
const { body, query, param, validationResult } = require('express-validator');

// Middleware to handle validation errors
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      status: 'error',
      message: 'Validation failed',
      errors: errors.array().map(e => ({
        field: e.param,
        message: e.msg
      }))
    });
  }
  next();
};

// ===== AUTHENTICATION MIDDLEWARE =====
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ status: 'error', message: 'Access token required' });
  }

  // TODO: Implement proper JWT verification
  // const decoded = jwt.verify(token, process.env.JWT_SECRET);
  // req.user = decoded;

  next();
};

// ===== ROUTES WITH SECURITY =====

/**
 * Health check endpoint - NO authentication required
 * GET /health
 */
app.get('/health', (req, res) => {
  // Don't expose sensitive information in health checks
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString()
    // DO NOT expose: version, environment, internal IPs, etc.
  });
});

/**
 * Get users with proper validation and authentication
 * GET /api/users
 * Query parameters: limit, offset
 */
app.get(
  '/api/users',
  authenticateToken,
  limiter,
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a positive integer')
  ],
  handleValidationErrors,
  (req, res) => {
    const limit = Math.min(parseInt(req.query.limit) || 10, 100);
    const offset = parseInt(req.query.offset) || 0;

    // Mock data - in production, query from database with proper parameterized queries
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json({
      status: 'success',
      data: users.slice(offset, offset + limit),
      pagination: {
        total: users.length,
        limit,
        offset
      }
    });
  }
);

/**
 * Get specific user by ID with validation
 * GET /api/users/:id
 */
app.get(
  '/api/users/:id',
  authenticateToken,
  limiter,
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('User ID must be a positive integer')
  ],
  handleValidationErrors,
  (req, res) => {
    const userId = parseInt(req.params.id);

    // Mock data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      // Don't reveal whether user exists or not (information disclosure)
      return res.status(404).json({
        status: 'error',
        message: 'User not found'
      });
    }

    res.json({
      status: 'success',
      data: user
    });
  }
);

/**
 * Create user with strict validation
 * POST /api/users
 */
app.post(
  '/api/users',
  authenticateToken,
  strictLimiter,
  [
    body('name')
      .trim()
      .notEmpty()
      .withMessage('Name is required')
      .isLength({ min: 2, max: 100 })
      .withMessage('Name must be between 2 and 100 characters')
      .matches(/^[a-zA-Z\s'-]+$/)
      .withMessage('Name contains invalid characters'),
