 * - Uses AWS Secrets Manager (or falls back to .env.local for dev)
 * - Implements secret rotation
 * - Sanitizes error messages
 * - Validates required secrets at startup
 * - Provides audit logging for secret access
 */

const express = require('express');
const AWS = require('aws-sdk');
require('dotenv').config({ path: '.env.local' });

const app = express();

// ============================================================================
// SECRETS MANAGEMENT
// ============================================================================

const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

/**
 * Cache for secrets to avoid repeated API calls
 * In production, implement TTL-based cache with automatic refresh
 */
const secretsCache = {
  data: null,
  lastUpdated: null,
  ttl: 60 * 60 * 1000, // 1 hour
};

/**
 * Load secrets from AWS Secrets Manager
 * Falls back to environment variables for development
 */
async function loadSecrets() {
  const environment = process.env.NODE_ENV || 'development';

  // Development: Load from .env.local (not in version control)
  if (environment === 'development') {
    console.log('📝 Development mode: Using .env.local');
    return {
      DATABASE_URL: process.env.DATABASE_URL,
      AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
      AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
      ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
      STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
      LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN,
    };
  }

  // Check cache first
  if (secretsCache.data && Date.now() - secretsCache.lastUpdated < secretsCache.ttl) {
    console.log('💾 Using cached secrets');
    return secretsCache.data;
  }

  // Staging/Production: Load from Secrets Manager
  try {
    console.log(`🔐 Loading secrets from AWS Secrets Manager (${environment})...`);

    const secretId = `myapp/${environment}`;
    const response = await secretsManager.getSecretValue({ SecretId: secretId }).promise();

    let secrets;
    if ('SecretString' in response) {
      secrets = JSON.parse(response.SecretString);
    } else {
      // Handle binary secrets if needed
      const buff = Buffer.from(response.SecretBinary, 'base64');
      secrets = JSON.parse(buff.toString('ascii'));
    }

    // Cache the secrets
    secretsCache.data = secrets;
    secretsCache.lastUpdated = Date.now();

    // Audit log
    auditLog('SECRETS_LOADED', {
      environment,
      timestamp: new Date().toISOString(),
      secretId
    });

    console.log('✓ Secrets loaded successfully');
    return secrets;

  } catch (err) {
    console.error('✗ Failed to load secrets from Secrets Manager:', err.message);

    // SECURITY: Do NOT fall back to plaintext secrets in production
    if (environment === 'production') {
      console.error('✗ CRITICAL: Cannot continue without secrets in production');
      process.exit(1);
    }

    throw err;
  }
}

/**
 * Validate that all required secrets are present
 */
function validateSecrets(secrets) {
  const requiredSecrets = [
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'ANTHROPIC_API_KEY',
    'STRIPE_SECRET_KEY',
    'LOGFIRE_TOKEN',
  ];

  const missing = requiredSecrets.filter(secret => !secrets[secret]);

  if (missing.length > 0) {
    console.error(`✗ Missing required secrets: ${missing.join(', ')}`);
    console.error('✗ Cannot start application without all required secrets');
    process.exit(1);
  }

  console.log('✓ All required secrets are configured');
}

/**
 * Sanitize error messages to prevent secret leakage
 */
function sanitizeError(err) {
  // Patterns for common secret formats
  const sensitivePatterns = [
    /password[\s=:'"]+[^\s'"]*[\s'"]/gi,
    /secret[\s=:'"]+[^\s'"]*[\s'"]/gi,
    /api[_-]?key[\s=:'"]+[^\s'"]*[\s'"]/gi,
    /token[\s=:'"]+[^\s'"]*[\s'"]/gi,
    /auth[\s=:'"]+[^\s'"]*[\s'"]/gi,
    /AKIA[0-9A-Z]{16}/g,  // AWS Access Key pattern
    /sk_live_[A-Za-z0-9]{24}/g,  // Stripe Live Key pattern
    /sk_test_[A-Za-z0-9]{24}/g,  // Stripe Test Key pattern
    /sk-ant-[A-Za-z0-9]{48}/g,  // Anthropic API Key pattern
  ];

  let sanitized = err.toString();
  sensitivePatterns.forEach(pattern => {
    sanitized = sanitized.replace(pattern, '[REDACTED]');
  });

  return sanitized;
}

/**
 * Safe logging that redacts sensitive information
 */
function safeLog(message, data = {}) {
  const sensitiveKeys = [
    'password', 'secret', 'token', 'key', 'api_key', 'access_key',
    'DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY',
    'STRIPE_SECRET_KEY', 'ANTHROPIC_API_KEY'
  ];

  const cleaned = JSON.parse(JSON.stringify(data), (key, value) => {
    if (sensitiveKeys.some(k => key.toLowerCase().includes(k.toLowerCase()))) {
      return '[REDACTED]';
    }
    return value;
  });

  console.log(message, cleaned);
}

/**
 * Audit logging for security events
 */
function auditLog(event, details = {}) {
  const timestamp = new Date().toISOString();
  console.log(`[AUDIT] ${timestamp} - ${event}`, details);

  // In production, send to centralized logging service
  // Example: sendToCloudWatch(event, { timestamp, ...details });
}

/**
 * Rotate secrets - called periodically
 * AWS Secrets Manager can trigger this automatically via Lambda
 */
async function rotateSecrets() {
  const secretsToRotate = [
    'myapp/database-password',
    'myapp/api-keys',
    'myapp/encryption-key'
  ];

  for (const secretId of secretsToRotate) {
    try {
      await secretsManager.rotateSecret({
        SecretId: secretId,
        RotationLambdaARN: process.env.ROTATION_LAMBDA_ARN,
        RotationRules: {
          AutomaticallyAfterDays: 30
        }
      }).promise();

      auditLog('SECRET_ROTATION_SCHEDULED', { secretId });
      console.log(`✓ Rotation scheduled for ${secretId}`);

    } catch (err) {
      console.error(`✗ Failed to schedule rotation for ${secretId}:`, err.message);
      auditLog('SECRET_ROTATION_FAILED', { secretId, error: err.message });
    }
  }
}

// ============================================================================
// MIDDLEWARE
// ============================================================================

// Parse JSON with size limit
app.use(express.json({ limit: '10kb' }));

// Request logging (without secrets)
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`${req.method} ${req.path} ${res.statusCode} ${duration}ms`);
  });
  next();
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  auditLog('UNHANDLED_ERROR', {
    message: sanitizeError(err),
    path: req.path,
    method: req.method
  });

  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production'
    ? 'An error occurred'
    : sanitizeError(err.message);

  res.status(statusCode).json({
    status: 'error',
    message,
    ...(process.env.NODE_ENV !== 'production' && { error: sanitizeError(err.stack) })
  });
});

// ============================================================================
// ROUTES
// ============================================================================

app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
});

/**
 * Get configuration (non-sensitive only)
 * NEVER expose actual secrets in API responses
 */
app.get('/api/config', (req, res) => {
  res.json({
    environment: process.env.NODE_ENV || 'development',
    logLevel: process.env.LOG_LEVEL || 'info',
    // DO NOT expose: AWS keys, database URLs, API keys, etc.
  });
});

/**
 * Example route showing safe database connection
 */
