  try {
    // In real implementation, use parameterized queries
    // const client = new PgClient(secrets.DATABASE_URL);
    // const query = 'SELECT * FROM users LIMIT $1';
    // const result = await client.query(query, [10]);

    // Mock data
    const users = [
