// ============================================================================
// STARTUP
// ============================================================================

async function start() {
  try {
    console.log('🚀 Starting application...');

    // Load secrets
    const secrets = await loadSecrets();

    // Validate secrets
    validateSecrets(secrets);

    // Store secrets in process.env (but don't expose them)
    Object.keys(secrets).forEach(key => {
      process.env[key] = secrets[key];
    });

    console.log('✓ Application initialized successfully');

    // Start server
    const PORT = process.env.PORT || 3000;
    app.listen(PORT, () => {
      console.log(`✓ Server running on port ${PORT}`);
      console.log(`✓ Environment: ${process.env.NODE_ENV || 'development'}`);
    });

    // Schedule periodic secret rotation check (every 24 hours)
    if (process.env.NODE_ENV === 'production') {
      setInterval(rotateSecrets, 24 * 60 * 60 * 1000);
    }

    auditLog('APPLICATION_STARTED', {
      environment: process.env.NODE_ENV || 'development',
      port: PORT
    });

  } catch (err) {
    console.error('✗ Failed to start application:', sanitizeError(err));
    auditLog('STARTUP_FAILED', { error: sanitizeError(err.message) });
    process.exit(1);
  }
}

// Start the application
start();

module.exports = app;
